----------------------------------------------------------------
--- Validate Parameters                                      ---
----------------------------------------------------------------
PROCEDURE validate_parameters(
            p_doc_type                     IN VARCHAR2    DEFAULT NULL
           ,p_po_type                      IN VARCHAR2    DEFAULT NULL
           ,p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_po_number                    IN VARCHAR2    DEFAULT NULL
           ,p_release_number               IN NUMBER      DEFAULT NULL
           ,p_rma_number                   IN VARCHAR2    DEFAULT NULL
           ,p_req_number                   IN VARCHAR2    DEFAULT NULL
           ,p_organization_id              IN NUMBER      DEFAULT NULL
           ,p_iot_number                   IN VARCHAR2    DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'Y'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------
l_header_id       NUMBER;
l_rel_id          NUMBER;
l_DBbanner        VARCHAR2(255);





BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Source Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Purchase Order Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit (For PO, PR, RMA and RQ)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Purchase Order Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Blanket Release Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_release_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'RMA Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_rma_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Internal Requisition Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_req_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Destination Inventory Org (For IOT Shipment)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_organization_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Inter Org Shipment Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_iot_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Diagnostic Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_include_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.55  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/02/23 18:20:15 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'rcv_podata_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_doc_type');
IF p_doc_type IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Source Document Type is required.');
   raise invalid_parameters;
END IF;
IF p_doc_type IS NOT NULL AND p_doc_type NOT IN ( 'IOT','PO','PR','RMA','RQ') THEN
   print_error('INVALID ARGUMENT: Source Document Type is Not Valid');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_doc_type');

debug('begin parameter validation: p_po_type');
IF p_po_type IS NOT NULL THEN
BEGIN
SELECT SUBSTR(LOOKUP_CODE,1,2) 
INTO l_exists_val
FROM FND_LOOKUP_VALUES_VL
WHERE SUBSTR(LOOKUP_CODE,1,2)  = p_po_type
 AND lookup_type                = 'PO TYPE'
AND LOOKUP_CODE not in ('QUOTATION','RFQ')
AND 
((p_doc_type = 'PO' AND LOOKUP_CODE <> 'BLANKET')
OR
(p_doc_type = 'PR' AND LOOKUP_CODE = 'BLANKET')
)
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Purchase Order Type is Not Valid');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_po_type failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_po_type');

debug('begin parameter validation: p_org_id');
IF p_org_id IS NOT NULL THEN
BEGIN
SELECT U.ORGANIZATION_ID
INTO l_exists_val
FROM PO_SYSTEM_PARAMETERS_ALL SP, HR_OPERATING_UNITS U
WHERE U.ORGANIZATION_ID = p_org_id
 AND p_doc_type in ('PO','PR','RQ','RMA')
and u.organization_id = sp.org_id
and (fnd_global.resp_id = -1 or fnd_global.org_id = u.organization_id)
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: No operating unit organization ID specified. The organization ID parameter is required if the source document type is PO, PR, RMA, and RQ.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_org_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_org_id');

debug('begin parameter validation: p_po_number');
IF p_po_number IS NOT NULL THEN
BEGIN
SELECT SEGMENT1
INTO l_exists_val
FROM PO_HEADERS_ALL
WHERE SEGMENT1 = p_po_number
 AND org_id = p_org_id and
type_lookup_code = Decode (p_po_type,'ST','STANDARD','PL','PLANNED','CO','CONTRACT','BL','BLANKET')
and p_doc_type in ('PO','PR')
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Purchase Order Number specified.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_po_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_po_number');

debug('begin parameter validation: p_release_number');
IF p_release_number IS NOT NULL THEN
BEGIN
SELECT R.RELEASE_NUM
INTO l_exists_val
FROM PO_RELEASES_ALL R, PO_HEADERS_ALL H
WHERE R.RELEASE_NUM = p_release_number
 AND r.po_header_id = h.po_header_id 
and p_doc_type = 'PR' 
and h.segment1 = p_po_number
and h.org_id = p_org_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid release, PO and org_id combination.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_release_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_release_number');

debug('begin parameter validation: p_rma_number');
IF p_rma_number IS NOT NULL THEN
BEGIN
SELECT ORDER_NUMBER
INTO l_exists_val
FROM (SELECT DISTINCT SOH.ORDER_NUMBER  FROM OE_ORDER_HEADERS_ALL SOH , OE_ORDER_LINES_ALL SOL   WHERE  SOH.ORG_ID = P_ORG_ID  AND SOH.HEADER_ID = SOL.HEADER_ID   AND SOL.LINE_CATEGORY_CODE = 'RETURN')
WHERE ORDER_NUMBER = p_rma_number
 AND p_doc_type = 'RMA'

 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: RMA Number entered is not valid');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_rma_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_rma_number');

debug('begin parameter validation: p_req_number');
IF p_req_number IS NOT NULL THEN
BEGIN
SELECT SEGMENT1
INTO l_exists_val
FROM (SELECT DISTINCT PRH.SEGMENT1 FROM PO_REQUISITION_HEADERS_ALL PRH,  PO_REQUISITION_LINES_ALL PRL  WHERE  PRH.ORG_ID = P_ORG_ID AND PRL.REQUISITION_HEADER_ID = PRH.REQUISITION_HEADER_ID  AND PRL.SOURCE_TYPE_CODE = 'INVENTORY')
WHERE SEGMENT1 = p_req_number
 AND p_doc_type = 'RQ'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Entered Requisition Number is not Valid');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_req_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_req_number');

debug('begin parameter validation: p_organization_id');
IF p_organization_id IS NOT NULL THEN
BEGIN
SELECT ORGANIZATION_ID
INTO l_exists_val
FROM (SELECT M.ORGANIZATION_ID, OOD.ORGANIZATION_CODE, OOD.ORGANIZATION_NAME FROM MTL_PARAMETERS M, ORG_ORGANIZATION_DEFINITIONS OOD WHERE M.ORGANIZATION_ID = OOD.ORGANIZATION_ID)
WHERE ORGANIZATION_ID = p_organization_id
 AND p_doc_type = 'IOT'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Incorrect organization id');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_organization_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_organization_id');

debug('begin parameter validation: p_iot_number');
IF p_iot_number IS NOT NULL THEN
BEGIN
SELECT SHIPMENT_NUMBER
INTO l_exists_val
FROM (SELECT SHIPMENT_NUMBER,TRANSACTION_TYPE_ID, TRANSFER_ORGANIZATION_ID FROM MTL_MATERIAL_TRANSACTIONS  UNION SELECT RSH.SHIPMENT_NUM,21,SHIP_TO_ORG_ID FROM RCV_SHIPMENT_HEADERS RSH WHERE RSH.RECEIPT_SOURCE_CODE = 'INVENTORY' )
WHERE SHIPMENT_NUMBER = p_iot_number
 AND TRANSACTION_TYPE_ID = 21
AND TRANSFER_ORGANIZATION_ID = p_organization_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Shipment Number');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_iot_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_iot_number');

debug('begin parameter validation: p_include_apps_check');
IF p_include_apps_check IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include Diagnostic Apps Check is required.');
   raise invalid_parameters;
END IF;
IF p_include_apps_check IS NOT NULL AND p_include_apps_check NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Gather and Include Apps Check Information is invalid.  Valid values are Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_include_apps_check');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('11.5','12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 11i,12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
 IF p_doc_type  not in ('PO','PR','RMA','IOT','RQ') THEN
    print_log( 'The Source Document Type parameter is not valid . '||
      'Value should be either ''PO'' or ''PR'' or ''RMA'' or ''IOT'' or ''RQ''');
    raise invalid_parameters;
  END IF;
  
 
 l_step := '30';
  IF p_org_id is null and p_doc_type <> 'IOT' THEN
    print_log('No operating unit organization ID specified. '||
      'The org_id parameter is mandatory.');
    raise invalid_parameters;
  END IF;
 
 
  IF p_doc_type = 'PO' THEN
   
   l_step := '35';

   IF p_po_type  not in ('ST','PL','CO','BL') THEN
    print_log( 'Purchase Order Type is Not Valid . '||
      'Value should be either ''ST'' or ''PL'' or ''CO'' or ''BL''');
    raise invalid_parameters;
   END IF;

   l_step := '36';

   IF p_po_type in ('ST','PL','CO','BL') and p_po_number is NULL THEN
    print_log( 'Purchase Order Number parameter is not specified, please specify.');
    raise invalid_parameters;
   END IF;
  
   
   l_step := '40';
   
  BEGIN
      SELECT h.po_header_id
      INTO l_header_id
      FROM po_headers_all h
      WHERE h.segment1       = p_po_number
      AND h.type_lookup_code = Decode (p_po_type,'ST','STANDARD','PL','PLANNED','CO','CONTRACT')
      AND h.org_id           = p_org_id;
      
       EXCEPTION   WHEN NO_DATA_FOUND THEN
        print_error('Invalid  PO and org_id combination');
        print_error('No Purchase Order document exists for values ' 
        || TO_CHAR(p_po_number)||'/'||TO_CHAR(p_org_id));

        raise invalid_parameters;
    END;
  END IF;

  l_step := '41';

  IF p_doc_type = 'PR' and p_po_number is NULL THEN
      print_log('Purchase Order Number parameter is not specified, please specify.');
      raise invalid_parameters;
  END IF;

  l_step := '42';

  IF p_doc_type = 'PR' and p_release_number is NULL THEN
      print_log('Release Number parameter is not specified, please specify.');
      raise invalid_parameters;
  END IF;

  IF p_doc_type = 'PR' THEN
   l_step := '45';
    BEGIN
      SELECT h.po_header_id, r.po_release_id
      INTO   l_header_id, l_rel_id 
      FROM   po_headers_all h, po_releases_all r
      WHERE  h.segment1 = p_po_number
	  AND	h.type_lookup_code = 'BLANKET'
      AND    h.org_id = p_org_id
      AND    r.org_id = h.org_id
      AND    r.po_header_id = h.po_header_id
      AND    r.release_num = p_release_number;
	      EXCEPTION WHEN NO_DATA_FOUND THEN
      print_error('Invalid release, PO and org_id combination');
      print_error('No release document exists for values '||
        to_char(p_release_number)||'/'||p_po_number||'/'||to_char(p_org_id));
      raise invalid_parameters;
    END;
  END IF;

  
  IF p_doc_type = 'RMA' THEN
   l_step := '46';

    IF (p_rma_number is NULL) THEN
      print_log('RMA Number parameter is not specified, please specify.');
      raise invalid_parameters;
    END IF;

   l_step := '47';

    BEGIN
	
		select distinct soh.HEADER_ID
		INTO l_header_id
		from oe_order_headers_all soh , oe_order_lines_all sol 
		where order_number 	= TO_CHAR(p_rma_number)
		and soh.org_id 		= p_org_id 
		and soh.header_id 	= sol.header_id 
		and sol.line_category_code = 'RETURN'  ;

		EXCEPTION   WHEN NO_DATA_FOUND THEN
		print_error('Invalid  RMA and org_id combination');
		print_error('No RMA Order document exists for values ' || TO_CHAR(p_po_number)||'/'||TO_CHAR(p_org_id));

		raise invalid_parameters;

    END;

    l_step := '471';		  

    BEGIN

	select count(1)
	INTO g_soline_cnt      
	from oe_order_headers_all soh , oe_order_lines_all sol 
	where order_number 	= TO_CHAR(p_rma_number)
	and soh.org_id 		= p_org_id 
	and soh.header_id 	= sol.header_id 
	and sol.line_category_code = 'RETURN'  
        and sol.reference_line_id IS NOT NULL;

    EXCEPTION  WHEN OTHERS THEN
            g_soline_cnt := 0;
    END;

  END IF;
  
  IF p_doc_type = 'IOT' THEN
   l_step := '48';

    IF (p_iot_number is NULL) THEN
      print_log('Inter Org Shipment Number parameter is not specified, please specify.');
      raise invalid_parameters;
    END IF;

   l_step := '49';
    BEGIN
	
	SELECT  RSH.SHIPMENT_HEADER_ID
	INTO l_header_id
	FROM RCV_SHIPMENT_HEADERS RSH
	WHERE RSH.RECEIPT_SOURCE_CODE = 'INVENTORY'
	AND RSH.SHIPMENT_NUM          = TO_CHAR(p_iot_number)
	AND RSH.SHIP_TO_ORG_ID        = p_organization_id;

	EXCEPTION   WHEN NO_DATA_FOUND THEN
        BEGIN             
        l_step := '50';

        SELECT  NVL(RTI.SHIPMENT_HEADER_ID, -99)
     	INTO l_header_id
	FROM RCV_TRANSACTIONS_INTERFACE RTI
	WHERE RTI.RECEIPT_SOURCE_CODE = 'INVENTORY'
    	AND RTI.SHIPMENT_NUM          = TO_CHAR(p_iot_number)
        AND RTI.TO_ORGANIZATION_ID    = p_organization_id;

	EXCEPTION   WHEN NO_DATA_FOUND THEN
        BEGIN             
        l_step := '501';

	SELECT  DISTINCT (RSL.SHIPMENT_HEADER_ID)
	INTO l_header_id
	FROM RCV_SHIPMENT_LINES RSL,
             MTL_MATERIAL_TRANSACTIONS MMT
	WHERE MMT.SHIPMENT_NUMBER = TO_CHAR(p_iot_number)
        AND RSL.TO_ORGANIZATION_ID = p_organization_id
        AND RSL.MMT_TRANSACTION_ID = MMT.TRANSACTION_ID
        AND MMT.transaction_type_id = 21 ;

	EXCEPTION   WHEN NO_DATA_FOUND THEN
        BEGIN             
        l_step := '5010';

   	    SELECT  RSH.SHIPMENT_HEADER_ID
     	    INTO l_header_id
	    FROM RCV_SHIPMENT_HEADERS RSH
	    WHERE RSH.RECEIPT_SOURCE_CODE = 'INTERNAL ORDER'
   	    AND RSH.SHIPMENT_NUM          = TO_CHAR(p_iot_number)
	    AND RSH.SHIP_TO_ORG_ID        = p_organization_id;

   	    EXCEPTION   WHEN NO_DATA_FOUND THEN

		print_error('Invalid  IOT SHIPMENT NUMBER and ORG_ID combination');
		print_error('No IOT SHIPMENT NUMBER exists for values ' || TO_CHAR(p_po_number)||'/'||TO_CHAR(p_org_id));
		
      	        raise invalid_parameters;	
        END;	  
        END;
        END;
    END;
  END IF;
  
  IF p_doc_type = 'RQ' THEN

   l_step := '51';

    IF (p_req_number is NULL) THEN
      print_log('Internal Requisition Number parameter is not specified, please specify.');
      raise invalid_parameters;
    END IF;

   l_step := '52';
    BEGIN
	
		SELECT DISTINCT PRH.REQUISITION_HEADER_ID
		INTO l_header_id
		FROM PO_REQUISITION_HEADERS_ALL PRH, 
		PO_REQUISITION_LINES_ALL PRL 
		WHERE PRH.TYPE_LOOKUP_CODE IN ('INTERNAL', 'PURCHASE') 
		AND PRH.SEGMENT1 = TO_CHAR(p_req_number)
		AND PRH.ORG_ID = p_org_id
		AND PRL.REQUISITION_HEADER_ID = PRH.REQUISITION_HEADER_ID 
		AND PRL.SOURCE_TYPE_CODE = 'INVENTORY';

	EXCEPTION   WHEN NO_DATA_FOUND THEN
		print_error('Invalid  INTERNAL REQUISITION and ORG_ID combination');
		print_error('No INTERNAL REQUISITION NUMBER exists for values ' || TO_CHAR(p_po_number)||'/'||TO_CHAR(p_org_id));
		
      	raise invalid_parameters;		  
    END;
  END IF;

    /* Accomodations for 19C DB */

g_db_version:=  l_dbversion;
select CASE
WHEN g_db_version > '18'
THEN 'banner_full'
Else 'banner'
END into l_DBbanner from dual where rownum=1;
g_DBbanner := l_DBbanner;
g_header_id := l_header_id;



    /* SEEDED EBS BANNER BEGIN */

    -- Premier Support Checks by priority
    select min(error_type) into l_system_function_var from (
        -- Database in Sustaining Support
        select 1 error_type from V$VERSION WHERE banner like '%11.2%' or banner like '%11.1%' or banner like '%10.%'
        union
        -- Application Version 11.5
        select 2 error_type from fnd_product_groups where release_name like '11.5%'
        union
        -- Application Version 12.1
        select 3 error_type from fnd_product_groups where release_name like '12.1%'
        union
        -- Database in Extended Support
        select 4 error_type from V$VERSION WHERE banner like '%12.1%'
        union
        -- Application Version 12.0
        select 5 error_type from fnd_product_groups where release_name like '12.0%'
        union
        -- Application Version 12.2.x outdated
        select 6 error_type from fnd_product_groups where release_name in ('12.2.0' , '12.2.1' , '12.2.2' , '12.2.3' , '12.2.4' , '12.2.5' , '12.2.6')
    );

    -- Set banner message by error type
    case l_system_function_var
        when 1 then
            -- Database in Sustaining Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Sustaining Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 2 then
            -- Application Version 11.5
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on November 2010. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br> Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 3 then
            -- Application Version 12.1
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support End for the application version on this instance is on December 2021. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp]. <br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 4 then
            -- Database in Extended Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Extended Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 5 then
            -- Application Version 12.0
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on January 2012. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 6 then
           -- Application Version 12.2.7
           g_banner_severity := 'W';
           g_banner_message := '<b>Effective July 1, 2024, the E-Business Suite 12.2 Error Correction Baseline will be 12.2.7.</b><br>
<br>
<div><div style="display:inline-block; text-align:left; max-width:800px;">Updating the application version to release 12.2.7 or higher will ensure you have access to major product releases.<br>
Refer to:<ul>
<li>[1195034/KB696368] Oracle E-Business Suite Error Correction Support Policy</li>
<li><a href="https://blogs.oracle.com/ebstech/post/update-error-correction-baseline-for-ebs-122" target="_blank">Oracle E-Business Suite Technology Blog</a> Update: Error Correction Baseline for EBS 12.2</li>
</ul>
Customers running E-Business Suite products on the 12.2.3 - 12.2.6 release levels are encouraged to update to current code levels of those products before July 2024 so they can benefit from the simpler and smaller patches that will be available starting in July 2024.<br>
In the event a new issue is reported on a product at a code level below the baseline, Oracle Support will attempt to resolve the issue and engage Development if necessary. Development may determine that the issue can be resolved at the customer code level, or may determine that the only practical way to provide the fix is for the customer to apply the baseline (or later) code in the affected area, and provide the fix at that level.
</div></div>';
        else
            -- No banner required
            g_banner_message := null;
    end case;
    /* SEEDED EBS BANNER END */
debug('end Additional Code: Additional Validation');



  g_parameters.DELETE;

  -- Recreate global hash for parameters after validation (includes the modifiers)
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Source Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Purchase Order Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit (For PO, PR, RMA and RQ)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Purchase Order Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Blanket Release Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_release_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'RMA Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_rma_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Internal Requisition Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_req_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Destination Inventory Org (For IOT Shipment)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_organization_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Inter Org Shipment Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_iot_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Diagnostic Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_include_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  l_step := '11';
  print_log(chr(10)||'Parameter Values after validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  -- Create global hash of SQL token values
debug('begin populate sql tokens hash table');
   g_sql_tokens('##$$DOCNUM$$##') := nvl(to_char(p_po_number),'NULL');
   g_masked_tokens('##$$DOCNUM$$##') := mask_text( g_sql_tokens('##$$DOCNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$RELNUM$$##') := nvl(to_char(p_release_number),'NULL');
   g_masked_tokens('##$$RELNUM$$##') := mask_text( g_sql_tokens('##$$RELNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$HEADID$$##') := nvl(to_char(l_header_id),'NULL');
   g_masked_tokens('##$$HEADID$$##') := mask_text( g_sql_tokens('##$$HEADID$$##'), 'NO_MASK');
   g_sql_tokens('##$$RELID$$##') := nvl(to_char(l_rel_id),'NULL');
   g_masked_tokens('##$$RELID$$##') := mask_text( g_sql_tokens('##$$RELID$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGID$$##') := to_char(p_org_id);
   g_masked_tokens('##$$ORGID$$##') := mask_text( g_sql_tokens('##$$ORGID$$##'), 'NO_MASK');
   g_sql_tokens('##$$IOTNUM$$##') := nvl(to_char(p_iot_number),'NULL');
   g_masked_tokens('##$$IOTNUM$$##') := mask_text( g_sql_tokens('##$$IOTNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$IOTORGID$$##') := nvl(to_char(p_organization_id),'NULL');
   g_masked_tokens('##$$IOTORGID$$##') := mask_text( g_sql_tokens('##$$IOTORGID$$##'), 'NO_MASK');
   g_sql_tokens('##$$RMANUM$$##') := nvl(to_char(p_rma_number),'NULL');
   g_masked_tokens('##$$RMANUM$$##') := mask_text( g_sql_tokens('##$$RMANUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$REQNUM$$##') := nvl(to_char(p_req_number),'NULL');
   g_masked_tokens('##$$REQNUM$$##') := mask_text( g_sql_tokens('##$$REQNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM2$$##') := '201';
   g_masked_tokens('##$$APPS_PARAM2$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM2$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM1$$##') := '401';
   g_masked_tokens('##$$APPS_PARAM1$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM1$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM3$$##') := '385';
   g_masked_tokens('##$$APPS_PARAM3$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM3$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM4$$##') := '177';
   g_masked_tokens('##$$APPS_PARAM4$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM4$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM5$$##') := 'null';
   g_masked_tokens('##$$APPS_PARAM5$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM5$$##'), 'NO_MASK');
   g_sql_tokens('##$$RESPID$$##') := 'null';
   g_masked_tokens('##$$RESPID$$##') := mask_text( g_sql_tokens('##$$RESPID$$##'), 'NO_MASK');
   g_sql_tokens('##$$USERNAME$$##') := 'null';
   g_masked_tokens('##$$USERNAME$$##') := mask_text( g_sql_tokens('##$$USERNAME$$##'), 'NO_MASK');
   g_sql_tokens('##$$REL$$##') := g_rep_info('Apps Version');
   g_masked_tokens('##$$REL$$##') := mask_text( g_sql_tokens('##$$REL$$##'), 'NO_MASK');
   g_sql_tokens('##$$VALID_ORGS$$##') := 'select organization_id from hr_operating_units where (fnd_global.resp_id = -1 or fnd_global.org_id = organization_id)';
   g_masked_tokens('##$$VALID_ORGS$$##') := mask_text( g_sql_tokens('##$$VALID_ORGS$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_CHECK$$##') := p_include_apps_check;
   g_masked_tokens('##$$APPS_CHECK$$##') := mask_text( g_sql_tokens('##$$APPS_CHECK$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGS$$##') := to_char(p_org_id);
   g_masked_tokens('##$$ORGS$$##') := mask_text( g_sql_tokens('##$$ORGS$$##'), 'NO_MASK');
   g_sql_tokens('##$$LINEID$$##') := 'req.requisition_line_id';
   g_masked_tokens('##$$LINEID$$##') := mask_text( g_sql_tokens('##$$LINEID$$##'), 'NO_MASK');
debug('end populate sql tokens hash table');



  l_key := g_masked_tokens.first;
  -- Print token values to the log

  -- if max rows param is not set and does not have a default, g_max_output_rows might end up being -1. We don't want that.
  IF (g_max_output_rows <= 0) THEN
     print_log ('Max rows was not set and there is no default value for it. Defaulting to 20.');
     g_max_output_rows := 20;
  ELSIF (g_max_output_rows > 100000) THEN
     print_log ('Max rows was set too high. Defaulting to 100000.');
     g_max_output_rows := 100000;
  END IF;

  l_step := '12';
  print_log('SQL Token Values');

  WHILE l_key IS NOT NULL LOOP
    -- Ensure tokens do not contain invalid characters (EBSAF-263)
    g_sql_tokens(l_key) := filter_html(g_sql_tokens(l_key), 'I', 'D' );
    g_masked_tokens(l_key) := filter_html(g_masked_tokens(l_key), 'I', 'D' );

    -- Allow tokens to be masked in log (EBSAF-275)
    print_log(l_key||': '|| g_masked_tokens(l_key));
    l_key := g_masked_tokens.next(l_key);
  END LOOP;

EXCEPTION
  WHEN INVALID_PARAMETERS THEN
    print_error_args('Invalid parameters provided. Process cannot continue.', l_step);
    raise;
  WHEN INVALID_ESCAPE THEN
    print_error('INVALID ESCAPE: Regular expression search results are incorrect.' ||
        ' Calling method "' || g_rep_info('Calling From') || '" module "' || g_rep_info('Calling Module') || '".' );
    raise;
  WHEN OTHERS THEN
    print_error_args('Error validating parameters: '||sqlerrm, l_step);
    raise;
END validate_parameters;


