             SELECT ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1)
               ))) || '' - '' ||
               ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 3) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2)
               )))
             FROM dba_source c
             WHERE c.owner = a.owner
             AND   c.name = a.object_name
             AND   c.type = a.object_type
             AND   c.line = 2
             AND   c.text like ''%$Header%''
           ) "File Version",
           b.text "Error Text"
    FROM dba_objects a,
         dba_errors b
    WHERE a.object_name = b.name(+)
    AND a.object_type = b.type(+)
    AND a.owner = ''APPS''
    AND (a.object_name like ''INV%'' OR
         a.object_name like ''MTL_%'' OR 
         a.object_name like ''WMS_%'' OR
         a.object_name like ''EGO_%'' OR
         a.object_name like ''CST_%'')
    AND a.status = ''INVALID''',
      p_title                  => 'Invalid Objects Exist Related to Inventory',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checking if Invalid Objects exist related to Inventory.',
      p_solution               => 'The invalid objects are listed for information only. They may not impact your task, but it is advisable to review and address them as follows:<br>
<ul>
<li>Review any error messages provided.</li>
<li>Recompile the individual objects manually or recompile the entire APPS schema with adadmin utility.</li>
<li>If you still have invalid objects, please review steps from [1325394/KB401905] Troubleshooting Guide - Invalid Objects in the E-Business Suite Environment 11i and 12.</li>
</ul>',
      p_success_msg            => 'No invalid objects indicated. All objects beginning with INV, MTL_, WMS_, EGO_, and CST_, were validated.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '20'
      );
   l_info.delete;
debug('end add_signature: INV_INVALIDS');



debug('begin add_signature: INV_TXN_KEY_FILE_VERSIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6725',
      p_sig_id                 => 'INV_TXN_KEY_FILE_VERSIONS',
      p_sig_sql                => 'select o.object_name,
substr(ltrim(rtrim(substr(substr(s.text, instr(s.text,''Header: '')),
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 1),
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2) -
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 1) ))), 1, 25) "FILE_NAME",
substr(ltrim(rtrim(substr(substr(s.text, instr(s.text,''Header: '')),
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2),
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 3) -
instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2) ))), 1, 30) "FILE_VERSION",
decode(o.object_type, ''PACKAGE'' , ''SPEC'', ''PACKAGE BODY'', ''BODY'') TYPE,
o.object_type PKG_TYPE,
o.status STATUS
from user_objects o , user_source s
where s.name = o.object_name
and s.type = o.object_type
and o.object_type in (''PACKAGE'' , ''PACKAGE BODY'')
and (o.object_name IN (
            ''INV_TXN_MANAGER_GRP'', 
            ''INV_PROCESS_TEMP'', 
            ''INV_QUANTITY_TREE_PVT'', 
            ''INV_PICK_RELEASE_PVT'', 
            ''INV_RCV_INTEGRATION_PVT'',
            ''INV_RESERVATION_PVT'') 
)
and s.line between 2 and 3
and s.text like ''%Header: %''
order by 1, 3 desc, 5 desc',
      p_title                  => 'Key File Versions',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Information about inventory transaction processing related packages. These packages are often a good version to check if you see incorrect behavior to ensure you have any recent patches and code-fixes:
<ul>
<li>INV_TXN_MANAGER_GRP (INVTXGGB.pls) - This package does interface transaction (MTL_TRANSACTIONS_INTERFACE) validations on the transaction open interface table data.</li>

<li>INV_PROCESS_TEMP (INVMMTTB.pls) - This package does pending transaction (MTL_MATERIAL_TRANSACTIONS_TEMP) validations on the temporary table data.</li>

<li>INV_PICK_RELEASE_PVT (INVVPICB.pls) - This package is used in pick release processing including the main logic for pick release as well as related functions like creating and maintaining reservations.</li>


<li>INV_QUANTITY_TREE_PVT (INVVQTTB.pls) - This package is responsible for calculating onhand data by creating a tree structure of onhand results then returning those values to calling programs. The onhand quantity data (MTL_ONHAND_QUANTITIES_DETAIL) is queried and summarized.</li>
</ul>',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: INV_TXN_KEY_FILE_VERSIONS');



debug('begin add_signature: EBS_MFG_INV_INVTAZ_FREEZE_DFF_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26782',
      p_sig_id                 => 'EBS_MFG_INV_INVTAZ_FREEZE_DFF_CHECK',
      p_sig_sql                => 'SELECT
    fa.application_short_name,
    fa.application_id,
    fdf.title,
    fdf.descriptive_flexfield_name,
    application_table_name,
    description,
    form_context_prompt context_prompt
FROM
    fnd_descriptive_flexs_vl fdf,
    fnd_application          fa
WHERE
        1 = 1
    and fa.application_id IN (##$$APPS_PARAM1$$##, ##$$APPS_PARAM2$$##, ##$$APPS_PARAM3$$##, ##$$APPS_PARAM4$$##, ##$$APPS_PARAM5$$##, 0)
    AND fa.application_id != 0
    AND fa.application_id = fdf.application_id
    AND concatenated_segs_view_name IS NOT NULL
    AND nvl(freeze_flex_definition_flag, ''N'') = ''N''
    AND context_user_override_flag = ''Y''
    AND EXISTS (
        SELECT
            1
        FROM
            fnd_descr_flex_contexts      ffc,
            fnd_descr_flex_column_usages fdu
        WHERE
                1 = 1
            AND fdu.descriptive_flexfield_name = fdf.descriptive_flexfield_name
            AND fdf.descriptive_flexfield_name = ffc.descriptive_flexfield_name
            AND fdu.descriptive_flex_context_code = ffc.descriptive_flex_context_code
            AND ffc.application_id = fdf.application_id
            AND ffc.application_id = fdu.application_id
            AND ffc.enabled_flag = ''Y''
            AND fdu.enabled_flag = ''Y''
    )',
      p_title                  => 'DFF Definition Not Frozen',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are DFF definition in the instance which are not frozen.  Such DFF fields will not work correctly on the application and may encounter error. For example: Done button may not be visible on mobile attribute page. ',
      p_solution               => 'See the  [2055400/KB706344] for solution.',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_INVTAZ_FREEZE_DFF_CHECK');



debug('begin add_signature: Inv_Trans_Specific_Profiles');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1571',
      p_sig_id                 => 'Inv_Trans_Specific_Profiles',
      p_sig_sql                => 'SELECT user_profile_option_name "Profile Option",
           a.profile_option_value "Profile Value",
           DECODE(e.profile_option_name, ''INV_DEBUG_TRACE'', DECODE(a.profile_option_value, 1, ''Yes'', 2, ''No'')
                                       , ''TRANSACTION_PROCESS_MODE'', DECODE(a.profile_option_value, 1, ''Online'', 2, ''Concurrent'', 3, ''Background'')
                                       , ''TRANSACTION_DATE'', DECODE(a.profile_option_value, 1, ''Allow date in any open period'', 2, ''Do not allow past date'', 3, ''Do not allow date in past period'', 4, ''Provide warning when date in past period'')
                                       , ''INV_OVERRIDE_RSV_FOR_BACKFLUSH'', DECODE(a.profile_option_value,  1, ''Yes'', 2, ''No'')
                                       , ''INV_OVERRIDE_NEG_FOR_BACKFLUSH'', DECODE(a.profile_option_value,  1, ''Yes'', 2, ''No'')
                                       , ''INV_MATERIAL_STATUS'', DECODE(a.profile_option_value,  1, ''Yes'', 2, ''No'')
                                       ) "Value Text",
           DECODE(a.level_id, 10001, ''Site'',
                              10002, ''Application'',
                              10003, ''Responsibility'',
                              10004, ''User'') "Level",
           DECODE(a.level_id, 10001, ''Site'', 10002, b.application_short_name, 10003, c.responsibility_name, 10004, rpad(
substr(d.user_name, 1, ceil(length(d.user_name)*0.25) ),
length(d.user_name), ''*'')) "Level Value",
           c.responsibility_id
    FROM fnd_profile_option_values a,
         fnd_application b,
         fnd_responsibility_tl c,
         fnd_user d,
         fnd_profile_options e,
         fnd_profile_options_tl t
    WHERE a.profile_option_id  = e.profile_option_id
      AND a.level_value          = b.application_id(+)
      AND a.level_value          = c.responsibility_id(+)
      AND a.level_value          = d.user_id(+)
      AND t.profile_option_name  = e.profile_option_name
      AND t.LANGUAGE             = ''US''
      AND nvl(c.LANGUAGE,''US'') = ''US''
      AND e.profile_option_name IN(''AFLOG_ENABLED'',
                                    ''INV_DEBUG_TRACE'',
                                    ''INV_DEBUG_FILE'',
				    ''INV_DEBUG_LEVEL'',
				    ''WSH_DEBUG_MODE'',
				    ''ONT_DEBUG_LEVEL'',
				    ''INV_BATCH_SIZE'',
				    ''INV_MATERIAL_STATUS'',
				    ''INV_OVERRIDE_NEG_FOR_BACKFLUSH'',
				    ''INV_OVERRIDE_RSV_FOR_BACKFLUSH'',
				    ''TRANSACTION_PROCESS_MODE'',
				    ''RCV_TP_MODE'',
				    ''DEFAULT_ORG_ID'', 
				    ''XLA_MO_SECURITY_PROFILE_LEVEL'',
				    ''TRANSACTION_DATE'',
				    ''ICX_FORMS_LAUNCHER'',
				    ''FND_DIAGNOSTICS'',
                    ''FLEXFIELDS:VALIDATE_ON_SERVER'',
                    ''ACCOUNT_GENERATOR:DEBUG_MODE'',
                    ''OVERRIDE_ROUTING'',
                    ''WSH_OVERPICK_ENABLED'',
                    ''INV_MVT_BREXIT_START_DT'',
                    ''INV_MVT_BREXIT_ARRIVALS_END_DT'',
                    ''INV_RCV_SHIPMENTS_BULK'') 
	  AND ((a.level_id = 10003 AND a.level_value = ##$$RESPID$$##) 
      OR   (a.level_id = 10004 AND d.user_name = ''##$$USERNAME$$##'')
      OR   (a.level_id = 10001 ))    
      ORDER BY e.profile_option_name,
            a.level_id DESC',
      p_title                  => 'Inventory Transactions Key Profile Options',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The results show key Inventory transactions related profile options.',
      p_solution               => 'Follow the information provided in [2053996/KB366153] for descriptions of Inventory profile options and the default settings.',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '20'
      );
   l_info.delete;
debug('end add_signature: Inv_Trans_Specific_Profiles');



debug('begin add_signature: P2P_RCV_TRANSACTION_MGR_PROCESSES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2587',
      p_sig_id                 => 'P2P_RCV_TRANSACTION_MGR_PROCESSES',
      p_sig_sql                => 'SELECT fdg.data_group_name,
           user_concurrent_queue_name Manager,
           concurrent_queue_name,
           concurrent_queue_id,
           sleep_seconds,
           running_processes,
           max_processes max_processes,
           decode(NVL(control_code,''A''),
           ''A'',''Activate concurrent Manager'',
           ''D'',''Deactivate concurrent manager'',
           ''E'',''Deactivated'',
           ''N'',''Target node/queue unavailable'',
           ''R'',''Restart concurrent manager'',
           ''T'',''Terminate requests and deactivate manager'',
           ''U'',''Update concurrent manager env inf.'',
           ''V'',''Verify concurrent managers status'',
           ''X'',''Terminated'',
           ''Error control code'') CONTROL_CODE
    FROM    FND_CONCURRENT_QUEUES_VL FCQ,
            FND_CONCURRENT_PROCESSORS FCP,
            FND_DATA_GROUPS FDG
    WHERE FCQ.DATA_GROUP_ID = FDG.DATA_GROUP_ID
    AND FCP.CONCURRENT_PROCESSOR_ID = FCQ.CONCURRENT_PROCESSOR_ID
    AND FCP.CONCURRENT_PROCESSOR_NAME = ''RCVOLTM''',
      p_title                  => 'Number of Receiving Transaction Manager Processes Are Low',
      p_fail_condition         => '[max_processes] < [10]',
      p_problem_descr          => 'Number of receiving transaction manager processes are low.',
      p_solution               => '<ul>
      <li>There is no specific value to suggest for MAX_PROCESSES, rather the value must be calculated</li>  
      <li>It is suggested to set to a minimum of 10 for production or high fidelity environments, MAX_PROCESSES should be AT LEAST 3</li>
      <li>See [404336/KB559648] - How Many Processes Should Be Set For The Receiving Transaction Manager</li> 
   </ul>',
      p_success_msg            => 'Number of receiving transaction manager processes are acceptable.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: P2P_RCV_TRANSACTION_MGR_PROCESSES');



