debug('begin add_signature: PORCVANLAZ_PO_WTS_DATA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '17864',
      p_sig_id                 => 'PORCVANLAZ_PO_WTS_DATA',
      p_sig_sql                => 'select distinct WTS.STOP_ID  
 , WTS.TRIP_ID
  , WTS.STATUS_CODE
  , WTS.STOP_SEQUENCE_NUMBER
  , WTS.PLANNED_ARRIVAL_DATE
  , WTS.PLANNED_DEPARTURE_DATE
  , WTS.ACTUAL_ARRIVAL_DATE
  , WTS.ACTUAL_DEPARTURE_DATE
  , WTS.PENDING_INTERFACE_FLAG
from    RCV_SHIPMENT_LINES              RSL , 
        WSH_DELIVERY_DETAILS             WDD,
        WSH_NEW_DELIVERIES               WND,
        WSH_DELIVERY_LEGS                LEG,
        WSH_DELIVERY_ASSIGNMENTS         WDA,
        WSH_TRIP_STOPS                   WTS
         where WDD.SOURCE_CODE = ''RTV''
        and RSL.PO_HEADER_ID =  ##$$HEADID$$## 
        and WDD.PO_SHIPMENT_LINE_ID         = RSL.SHIPMENT_LINE_ID
        and WND.DELIVERY_ID                 = WDA.DELIVERY_ID  
        and WDA.DELIVERY_DETAIL_ID          = WDD.DELIVERY_DETAIL_ID 
        and LEG.DELIVERY_ID                 = WND.DELIVERY_ID 
        and ( WTS.STOP_ID  =  LEG.PICK_UP_STOP_ID 
          or WTS.STOP_ID  = LEG.DROP_OFF_STOP_ID )
		and wdd.inv_interfaced_flag <> ''Y''
