debug('begin add_signature: EBS_MFG_INV_PORCVANL_OSP_WIP_JOB_INFO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30944',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_OSP_WIP_JOB_INFO',
      p_sig_sql                => 'SELECT pod.po_header_id , pod.po_line_id, pod.line_location_id, pod.po_distribution_id
  , WE.organization_id, WE.WIP_ENTITY_ID, WE.WIP_ENTITY_NAME,
WE.ENTITY_TYPE || ''-'' || decode((WE.ENTITY_TYPE) ,1,''Discrete Job'',2,''Repetitive Schedule'',3,''Closed Discrete Job'',4,''Flow/Work Order-less'',
5,''Lot Based Job'',6,''EAM Job'',7,''Closed EAM Work Order'')  ENTITY_TYPE ,
WDJ.STATUS_TYPE || ''-'' || decode((WDJ.STATUS_TYPE),
1, ''Unreleased - no charges allowed'',3, ''Released - charges allowed'',4, ''Complete - charges allowed'',5, ''Complete - no charges allowed'',6, ''Hold - no charges allowed'',7, ''Cancelled - no charges allowed'',
8, ''Pending bill of material load'',9, ''Failed bill of material load'',10,''Pending routing load'',11, ''Failed routing load'',12, ''Closed - no charges allowed'',
13, ''Pending - mass loaded'',14, ''Pending close'',15, ''Failed close'')  STATUS_TYPE
, decode (WE.ENTITY_TYPE , 3, ''Receiving not allowed as the job is closed'' 
                         , 7, ''Receiving not allowed as the job is closed''
                         , 6, decode (WDJ.STATUS_TYPE, 3, ''Job status valid for Receipt'',  4, ''Job status valid for Receipt'', ''Job status not valid for Receipt'') 
                         , 1, decode (WDJ.STATUS_TYPE, 3, ''Job status valid for Receipt'',  4, ''Job status valid for Receipt'', ''Job status not valid for Receipt'') ) status_Validation 
From WIP_ENTITIES WE, WIP_DISCRETE_JOBS WDJ , PO_DISTRIBUTIONS_ALL pod
Where WE.WIP_ENTITY_ID = WDJ.WIP_ENTITY_ID
And WE.WIP_ENTITY_ID = pod.wip_entity_id
and pod.wip_entity_id is not null 
and pod.DESTINATION_TYPE_CODE = ''SHOP FLOOR''
AND ( we.entity_type IN (3, 7) OR (we.entity_type IN (1, 6) AND wdj.status_type NOT IN (3, 4)))
AND  pod.po_header_id  = ##$$HEADID$$##',
      p_title                  => 'OSP WIP Job Detail',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Outside Processing (OSP) Job information linked to the Purchase Order',
      p_solution               => 'Review below notes for additional information if the job status is restricting receipt of PO -
[444771/KB652744#aref_section217] - How To Troubleshoot APP-PO-14094 When Performing Receiving Related Transactions 
[1267992/KB466791] - APP-PO-14094 in Find Expected Receipts. Cannot Find Receipts for Some POs Tied With Work Jobs / EAM Work Orders
[1592120/KB500706] - Unable to Find One Purchase Order Line to Receipt on RCVRCERC Form APP-PO-14094 OSP ',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_OSP_WIP_JOB_INFO');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_KEY_WAREHOUSE_PARAMETER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31226',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_KEY_WAREHOUSE_PARAMETER',
      p_sig_sql                => 'WITH ORG AS 
(SELECT DISTINCT OOD.ORGANIZATION_ID
FROM
rcv_shipment_headers         rsh,
rcv_shipment_lines           rsl,
ORG_ORGANIZATION_DEFINITIONS OOD 
WHERE
	1 = 1
AND rsh.shipment_header_id = rsl.shipment_header_id
AND rsh.shipment_header_id = ''##$$HEADID$$##''
AND ''##$$IOTNUM$$##'' IS NOT NULL
AND OOD.ORGANIZATION_ID IN (rsl.from_organization_id,rsl.to_organization_id)
UNION
SELECT DISTINCT OOD.ORGANIZATION_ID
FROM ORG_ORGANIZATION_DEFINITIONS OOD ,
PO_LINE_LOCATIONS_ALL PLL ,
PO_LINES_ALL PL ,PO_HEADERS_ALL PH ,
FINANCIALS_SYSTEM_PARAMS_ALL FSP
WHERE PL.PO_HEADER_ID    = PH.PO_HEADER_ID
AND PH.PO_HEADER_ID      = ''##$$HEADID$$##''
AND ''##$$DOCNUM$$##'' IS NOT NULL
AND PLL.PO_LINE_ID       = PL.PO_LINE_ID
AND FSP.ORG_ID           = PH.ORG_ID
AND OOD.ORGANIZATION_ID IN (FSP.INVENTORY_ORGANIZATION_ID , PLL.SHIP_TO_ORGANIZATION_ID)
UNION
 SELECT DISTINCT OOD.ORGANIZATION_ID
FROM oe_order_headers_all ooh,
oe_order_lines_all oel,
ORG_ORGANIZATION_DEFINITIONS OOD ,
FINANCIALS_SYSTEM_PARAMS_ALL FSP
where 1=1
AND ooh.order_number =''##$$RMANUM$$##''
AND ''##$$RMANUM$$##'' IS NOT NULL
AND ooh.org_id = ''##$$ORGID$$##''
AND ooh.header_id= oel.header_id
AND FSP.ORG_ID           = OOH.ORG_ID
AND OOD.ORGANIZATION_ID IN (FSP.INVENTORY_ORGANIZATION_ID , oel.ship_from_org_id)
UNION
SELECT DISTINCT OOD.ORGANIZATION_ID
FROM
po_requisition_headers_all        porh,
po_requisition_lines_all         porl,
ORG_ORGANIZATION_DEFINITIONS OOD ,
FINANCIALS_SYSTEM_PARAMS_ALL FSP
WHERE
	1 = 1
AND porl.requisition_header_id = porh.requisition_header_id
AND porh.requisition_header_id = ''##$$HEADID$$##''
AND ''##$$REQNUM$$##'' IS NOT NULL
AND FSP.ORG_ID           = porh.ORG_ID
AND OOD.ORGANIZATION_ID IN (FSP.INVENTORY_ORGANIZATION_ID , porl.SOURCE_ORGANIZATION_ID,porl.DESTINATION_ORGANIZATION_ID)
)
select attribute, value from 
(SELECT organization_id,1 sequence, ''-- INVENTORY PARAMETERS --'' Attribute, '''' Value from ORG
UNION 
SELECT organization_id,1.1 sequence, ''Organization Code'', organization_code || '' (ID: ''|| organization_id ||'')''  FROM mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union 
select organization_id,1.2 sequence, ''Item Master Organization'', NVL((select b.organization_code || '' (ID: '' || mp.master_organization_id || '')'' from mtl_parameters b where b.organization_id = mp.master_organization_id), mp.master_organization_id) master_organization_id from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union
select organization_id,1.3 sequence, ''Calendar'', calendar_code  FROM mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union
select organization_id,1.4 sequence, ''Allow Negative Balances'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_NEGATIVE_RECEIPT'' and lookup_code = negative_inv_receipt_code), negative_inv_receipt_code) negative_inv_receipt_code  from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union
select organization_id,1.5 sequence, ''Locator Control'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_LOCATION_CONTROL'' and lookup_code = stock_locator_control_code), stock_locator_control_code) stock_locator_control_code from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
 union
select organization_id,1.6 sequence, ''On-Hand Status Enabled'', decode(default_status_id, NULL, ''No'', ''Yes'') onhand_status_enabled from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union
select organization_id,1.7 sequence, ''WMS (Warehouse Management System) Enabled'', wms_enabled_flag  from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union
select organization_id,1.8 sequence, ''Process Manufacturing (OPM) Enabled'', process_enabled_flag  from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union 
select organization_id,1.9 sequence, ''EAM (Enterprise Asset Management) Enabled'', eam_enabled_flag from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union 
select organization_id,1.91  sequence, ''Project Enabled'', DECODE(project_reference_enabled, 1, ''1 (Yes)'', 2, ''2 (No)'', to_char(project_reference_enabled))  
from mtl_parameters mp
 where organization_id IN (SELECT organization_id from ORG) 
union
SELECT organization_id,2 sequence, '''' Attribute, '''' Value from ORG
UNION 
SELECT organization_id,2.1 sequence, ''-- COSTING INFORMATION --'' Attribute, '''' Value from ORG
union 
select organization_id,2.2 sequence, ''Costing Method'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_PRIMARY_COST'' and lookup_code = primary_cost_method), primary_cost_method) primary_cost_method from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union
select organization_id,2.3 sequence, ''Costing Organization'', NVL((select mp.cost_organization_id || '' ('' ||b.organization_code || '')'' from mtl_parameters b where b.organization_id = mp.cost_organization_id), mp.cost_organization_id) cost_organization_id from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union
select organization_id,2.4 sequence, ''Default Cost Group ID'', DEFAULT_COST_GROUP_ID || '' (''|| (select COST_GROUP from CST_COST_GROUPS where COST_GROUP_ID = DEFAULT_COST_GROUP_ID) ||'')'' from mtl_parameters mp  
 where organization_id IN (SELECT organization_id from ORG)
union
SELECT organization_id,3 sequence, '''' Attribute, '''' Value from ORG
union
SELECT organization_id,3.1 sequence, ''-- REVISION, LOT, SERIAL AND LPN -- '' Attribute, '''' Value from ORG
union 
select organization_id,3.2 sequence, ''Serial Uniqueness (Serial_Type)'', Decode(serial_number_type, 
''1'', ''1 (Within inventory model and items)'', 
''2'', ''2 (Unique within organization)'', 
''3'', ''3 (Unique across organizations)'', 
''4'', ''4 (Unique within inventory items)'', serial_number_type) SERIAL_NUMBER_TYPE 
 from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union 
select organization_id,3.3 sequence, ''Serial Generation'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_SERIAL_GENERATION'' and lookup_code = serial_number_generation), serial_number_generation) serial_number_generation  from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union 
select organization_id,3.4 sequence, ''Lot Uniqueness'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_LOT_UNIQUENESS'' and lookup_code = lot_number_uniqueness), lot_number_uniqueness) lot_number_uniqueness  from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
union 
select organization_id,3.5 sequence, ''Lot Generation'', NVL((select lookup_code || '' (''|| meaning || '')'' from mfg_lookups where lookup_type = ''MTL_LOT_GENERATION'' and lookup_code = lot_number_generation), lot_number_generation) lot_number_generation  from mtl_parameters mp 
 where organization_id IN (SELECT organization_id from ORG)
 )
order by organization_id, sequence
',
      p_title                  => 'Key Current Warehouse Parameters',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Provide a listing of organization details as a reference. Note : See "SERIAL_NUMBER_TYPE" column for the serial number uniqueness. ',
      p_solution               => '',
      p_success_msg            => 'No organizations found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_KEY_WAREHOUSE_PARAMETER');



