      p_sig_sql                => 'select hou.organization_id,hou.name, hou.date_from, hou.date_to,hoi.ORG_INFORMATION2 enabled
from HR_ORGANIZATION_UNITS hou, hr_organization_information hoi
where hou.organization_id= ##$$ORGID$$##
