debug('begin add_signature: EBS_MFG_INV_PORCVANL_PERIODS_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '32228',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_PERIODS_PO',
      p_sig_sql                => 'WITH ORG AS 
(SELECT DISTINCT OOD.ORGANIZATION_ID
FROM ORG_ORGANIZATION_DEFINITIONS OOD ,
PO_LINE_LOCATIONS_ALL PLL ,
PO_LINES_ALL PL,
PO_HEADERS_ALL PH ,
FINANCIALS_SYSTEM_PARAMS_ALL FSP
WHERE PL.PO_HEADER_ID    = PH.PO_HEADER_ID
AND PH.PO_HEADER_ID      = ''##$$HEADID$$##''
AND PLL.PO_LINE_ID       = PL.PO_LINE_ID
AND FSP.ORG_ID           = PH.ORG_ID
AND OOD.ORGANIZATION_ID IN (FSP.INVENTORY_ORGANIZATION_ID , PLL.SHIP_TO_ORGANIZATION_ID)
)
select 
period.ACCT_PERIOD_ID, 
period.PERIOD_NAME, 
period.ORGANIZATION_ID, 
period.PERIOD_SET_NAME, 
period.PERIOD_YEAR, 
period.PERIOD_NUM, 
period.DESCRIPTION, 
period.PERIOD_START_DATE, 
period.SCHEDULE_CLOSE_DATE, 
period.PERIOD_CLOSE_DATE, 
period.OPEN_FLAG, 
period.SUMMARIZED_FLAG, 
period.CREATION_DATE, 
period.CREATED_BY, 
period.LAST_UPDATE_DATE, 
period.LAST_UPDATED_BY, 
period.LAST_UPDATE_LOGIN 
from org_acct_periods period
where organization_id IN (SELECT organization_id from ORG)
and PERIOD_START_DATE > sysdate - 90
order by ORGANIZATION_ID, ACCT_PERIOD_ID',
      p_title                  => 'PO Accounting Periods',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Provide a listing of organization periods (from ORG_ACCT_PERIODS) for the last 90 days.',
      p_solution               => 'Listing related periods for the receiving organization. ',
      p_success_msg            => 'No periods were found related to the organization in the last 90 days.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_PERIODS_PO');



