debug('begin add_signature: PORCVANLAZ_GL_PERIOD_STATUS_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3532',
      p_sig_id                 => 'PORCVANLAZ_GL_PERIOD_STATUS_PO',
      p_sig_sql                => 'SELECT SET_OF_BOOKS_ID,
  PERIOD_NAME,
  DECODE(CLOSING_STATUS,''O'',''OPEN'', ''C'',''CLOSED'', ''F'',''FUTURE'', ''N'',''NEVER'', CLOSING_STATUS) "GL_STATUS",
  START_DATE,
  END_DATE
FROM GL_PERIOD_STATUSES
WHERE TRUNC(START_DATE) > SYSDATE-120
AND TRUNC(START_DATE)   < SYSDATE+1
AND APPLICATION_ID      = 101
AND SET_OF_BOOKS_ID    IN
  ( SELECT DISTINCT SET_OF_BOOKS_ID
  FROM PO_DISTRIBUTIONS_ALL
  WHERE PO_HEADER_ID = ##$$HEADID$$##
  )
ORDER BY APPLICATION_ID,START_DATE DESC',
      p_title                  => 'GL Period Status',
      p_fail_condition         => '[GL_STATUS] not in [OPEN, FUTURE]',
      p_problem_descr          => 'The Accounting period which you are working in needs to be open. If not you may receive:
APP-PO-14230: The GL date is not in an open period (code error name = PO_CNL_NO_PERIOD)
-OR-
Error - The Inventory Accounting Period in which you are trying to create this receiving transaction is not open for the following item(s)',
      p_solution               => 'See [552244/KB658365]',
      p_success_msg            => 'Inventory Accounting Periods are open',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_GL_PERIOD_STATUS_PO');



