debug('begin add_signature: PORCVANLAZ_INV_PERIOD_STATUS_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3534',
      p_sig_id                 => 'PORCVANLAZ_INV_PERIOD_STATUS_PO',
      p_sig_sql                => 'SELECT oap.acct_period_id, 
       oap.organization_id, 
       oap.period_set_name, 
       oap.period_year, 
       oap.period_num, 
       oap.period_name, 
       oap.description, 
      decode(oap.open_flag,
 ''P'',''P - Period Close is processing''
,''N'',''N - Period Close process is completed''
,''Y'',''Y - Period is open if Closed Date is NULL''
,''Unknown'') "PERIOD_STATUS",
       oap.period_start_date, 
       oap.schedule_close_date, 
       oap.period_close_date, 
       oap.last_update_date, 
       oap.creation_date
FROM ORG_ACCT_PERIODS oap
WHERE organization_id in (
SELECT destination_organization_id
FROM PO_DISTRIBUTIONS_ALL
WHERE po_header_id = ##$$HEADID$$## )
AND TRUNC(period_start_date) > SYSDATE-120
AND TRUNC(period_start_date) < SYSDATE+1
ORDER BY acct_period_id DESC',
