  add_signature(
      p_sig_repo_id            => '3602',
      p_sig_id                 => 'PORCVANLAZ_CONTROL_STATUS_PO',
      p_sig_sql                => 'SELECT ph.segment1 PO_NUMBER,
  pl.line_num,
  pll.shipment_num,
 decode (  NVL(pll.closed_code,''N''),''FINALLY CLOSED'', ''<strong><FONT COLOR = RED>FINALLY CLOSED</FONT></strong>'',NVL(pll.closed_code,''N''))  "PLL.CLOSED_CODE",
  ph.org_id,
  ph.po_header_id,
  pl.po_line_id,
  pll.line_location_id
FROM po_headers_all ph,
  po_lines_all pl,
  po_line_locations_all pll
WHERE ph.po_header_id = ##$$HEADID$$##
AND pl.po_header_id   = ph.po_header_id
