   CASE NVL(pll.approved_flag,''N'') WHEN ''Y'' THEN ''Y'' WHEN ''N'' THEN ''<strong><FONT COLOR = RED>N</FONT></strong>'' WHEN ''R'' THEN ''<strong><FONT COLOR = RED>R</FONT></strong>'' ELSE NVL(pll.approved_flag,''N'') END  "PLL.APPROVED_FLAG",
