debug('begin add_signature: PORCVANLAZ_ENCUMB_CHECK_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3605',
      p_sig_id                 => 'PORCVANLAZ_ENCUMB_CHECK_PO',
      p_sig_sql                => 'SELECT HOU.name "Operating Unit Name" ,
  POH.SEGMENT1 ,
  POH.PO_HEADER_ID ,
  POH.ORG_ID ,
  POH.TYPE_LOOKUP_CODE ,
  POL.PO_LINE_ID ,
  Pol.Line_Num ,
  PLL.LINE_LOCATION_ID ,
  PLL.SHIPMENT_NUM ,
  PLL.APPROVED_FLAG "PLL.APPROVED_FLAG" ,
  CASE FSP.PURCH_ENCUMBRANCE_FLAG 
    when PLL.ENCUMBERED_FLAG then FSP.PURCH_ENCUMBRANCE_FLAG
    ELSE ''<strong><FONT COLOR = RED>'' || FSP.PURCH_ENCUMBRANCE_FLAG|| ''</FONT></strong>'' END "Encumbered Flag- OU LEVEL" ,
  CASE PLL.ENCUMBERED_FLAG 
  when  FSP.PURCH_ENCUMBRANCE_FLAG then PLL.ENCUMBERED_FLAG 
  ELSE  ''<strong><FONT COLOR = RED>'' || PLL.ENCUMBERED_FLAG || ''</FONT></strong>'' END  "Encumbered Flag- PO SHIPMENT" ,
  POD.PO_DISTRIBUTION_ID ,
  POD.DISTRIBUTION_NUM
FROM PO_HEADERS_ALL POH ,
  PO_LINES_ALL POL ,
  PO_LINE_LOCATIONS_ALL PLL ,
  PO_DISTRIBUTIONS_ALL POD ,
  PO_RELEASES_ALL POR ,
  FINANCIALS_SYSTEM_PARAMS_ALL FSP ,
  HR_ORGANIZATION_UNITS HOU ,
  MTL_PARAMETERS MP
WHERE POH.PO_HEADER_ID   = ##$$HEADID$$##
AND POH.TYPE_LOOKUP_CODE = ''STANDARD''
AND POL.PO_HEADER_ID     = POH.PO_HEADER_ID
AND PLL.PO_LINE_ID       = POL.PO_LINE_ID
AND POD.LINE_LOCATION_ID = PLL.LINE_LOCATION_ID
AND POR.PO_RELEASE_ID(+) = PLL.PO_RELEASE_ID
AND POH.ORG_ID           = FSP.ORG_ID
AND FSP.ORG_ID           = HOU.ORGANIZATION_ID
AND POH.ORG_ID           = HOU.ORGANIZATION_ID
AND MP.ORGANIZATION_ID   = PLL.SHIP_TO_ORGANIZATION_ID
AND NOT EXISTS
  (SELECT 1
  FROM PO_DISTRIBUTIONS_ALL POD
  WHERE POD.LINE_LOCATION_ID     = PLL.LINE_LOCATION_ID
  AND (POD.DESTINATION_TYPE_CODE = ''SHOP FLOOR''
  OR POD.DISTRIBUTION_TYPE      <> ''STANDARD'')
  )
AND  PLL.ENCUMBERED_FLAG <> FSP.PURCH_ENCUMBRANCE_FLAG
ORDER BY POH.ORG_ID,
  POH.PO_HEADER_ID,
  POL.PO_LINE_ID,
  PLL.LINE_LOCATION_ID,
  POD.PO_DISTRIBUTION_ID',
      p_title                  => 'Encumbrance Check',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There is atleast one PO shipment with a different encumbered_flag compared to the Financial Options.<Br></BR>
This may cause the following error:<Br>
APP-PO-14094: No records meet your search criteria.<Br>
Cause: There are no records that match your search criteria.<Br>
Action: Re-enter your search criteria with fewer or different parameters.',
      p_solution               => 'This means the encumbrance setup has been changed after the PO was created.<Br>
Review APP-PO-14094 No Data Found On Several Receipt Forms After Encumbrance is Enabled. [759777/KB362581].',
      p_success_msg            => 'No problems found. The encumbered flag is same on the PO Shipment (column name ENCUMBERED_FLAG) and financial options (column name PURCH_ENCUMBRANCE_FLAG).',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '21'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_ENCUMB_CHECK_PO');



debug('begin add_signature: PORCVANLAZ_UNPROC_RTI_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3606',
      p_sig_id                 => 'PORCVANLAZ_UNPROC_RTI_PO',
      p_sig_sql                => 'SELECT INTERFACE_TRANSACTION_ID,
GROUP_ID,
CREATION_DATE,
TRANSACTION_TYPE,
PROCESSING_STATUS_CODE,
PROCESSING_MODE_CODE,
TRANSACTION_STATUS_CODE,
ITEM_ID,
QUANTITY,VALIDATION_FLAG, 
MOBILE_TXN, 
LPN_GROUP_ID 
FROM RCV_TRANSACTIONS_INTERFACE
WHERE PROCESSING_MODE_CODE = ''BATCH''
AND PROCESSING_STATUS_CODE = ''PENDING''
AND TRANSACTION_STATUS_CODE = ''PENDING''
AND (po_header_id        =  ##$$HEADID$$##
OR parent_transaction_id IN
(SELECT TRANSACTION_ID 
FROM RCV_TRANSACTIONS 
WHERE PO_HEADER_ID =  ##$$HEADID$$##))',
      p_title                  => 'Unprocessed Records in Interface - Batch Mode',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are unprocessed records in RCV_TRANSACTIONS_INTERFACE table which could prevent receiving transactions.',
