debug('begin add_signature: PORCVANLAZ_CORRUPT_VEN_AND_VENSITE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14062',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_VEN_AND_VENSITE',
      p_sig_sql                => 'SELECT poh.segment1,
  poh.po_header_id,
  poh.vendor_id po_vendor,
  poh.vendor_site_id po_vendor_site,
  rsh.receipt_num,
  rsh.shipment_header_id,
  rsh.vendor_id rsh_vendor,
  rsh.vendor_site_id rsh_vendor_site,
  rt.transaction_id,
  rt.transaction_type,
  rt.vendor_id rt_vendor,
  rt.vendor_site_id rt_vendor_site
FROM PO_HEADERS_ALL poh ,
  PO_LINE_LOCATIONS_ALL pll,
  RCV_SHIPMENT_HEADERS rsh,
  RCV_TRANSACTIONS rt
WHERE poh.po_header_id            = pll.po_header_id
AND pll.po_header_id              = rt.po_header_id
AND pll.line_location_id          = rt.po_line_location_id
AND rt.po_header_id               = ##$$HEADID$$##
AND rt.shipment_header_id         = rsh.shipment_header_id
AND ((rsh.vendor_id              <> poh.vendor_id
AND NVL(rsh.vendor_site_id,-999) <> poh.vendor_site_id)
OR (NVL(rt.vendor_id,-999)       <> poh.vendor_id
AND NVL(rt.vendor_site_id,-999)  <> poh.vendor_site_id))
AND (pll.quantity                >= NVL(pll.quantity_received,0)
OR pll.quantity                  >= NVL(pll.quantity_billed,0))
AND NVL(pll.cancel_flag, ''N'')    <> ''Y''
AND NVL(pll.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
ORDER BY poh.po_header_id,
         rsh.shipment_header_id,
         rt.transaction_id',
      p_title                  => 'Incorrect vendor And Vendor Site After Supplier Merge',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with incorrect vendor and vendor site after supplier merge is performed in receiving tables.<br>',
      p_solution               => 'Run the datafix script to update vendor and vendor site details in receiving tables. <br>
Review datafix for Supplier Merge Not Updating Receiving Tables [795686/KB618983]. <br>',
      p_success_msg            => 'There are no receipts with incorrect vendor and vendor site after supplier merge is performed in receiving tables.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_CORRUPT_VEN_AND_VENSITE');



debug('begin add_signature: PORCVANLAZ_CORRUPT_DESTN_TYPE_FOR_RTR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14063',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_DESTN_TYPE_FOR_RTR',
      p_sig_sql                => 'SELECT rt.transaction_id,
       rt.transaction_type,
       rt.destination_type_code ,
       rt.parent_transaction_id,
       prt.transaction_type,
       prt.destination_type_code,
       rt.po_header_id,
       rt.po_line_id,
       rt.po_line_location_id
FROM RCV_TRANSACTIONS rt,
     RCV_TRANSACTIONS prt
WHERE rt.transaction_type      = ''RETURN TO RECEIVING''
AND rt.destination_type_code   = ''RECEIVING''
AND rt.source_document_code    = ''PO''
AND rt.po_header_id            = ##$$HEADID$$##
AND rt.source_document_code    = prt.source_document_code
AND rt.parent_transaction_id   = prt.transaction_id
AND prt.destination_type_code <> rt.destination_type_code
AND prt.transaction_type       = ''DELIVER''
ORDER BY rt.transaction_id ASC',
