debug('begin add_signature: PORCVANLAZ_NULL_EMPLOYEE_ID_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14131',
      p_sig_id                 => 'PORCVANLAZ_NULL_EMPLOYEE_ID_PO',
      p_sig_sql                => 'select RSH.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_HEADERS'' "Level" 
from RCV_SHIPMENT_HEADERS RSH,
RCV_SHIPMENT_LINES RSL
WHERE ABS(RSL.PO_HEADER_ID) = ABS(##$$HEADID$$##)
AND RSH.employee_id is null
and RSH.created_by is not null
and RSH.shipment_header_id = RSL.shipment_header_id
union
select RSL.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_LINES'' "Level" 
from RCV_SHIPMENT_LINES RSL
where RSL.employee_id is null
and RSL.created_by is not null
AND ABS(RSL.PO_HEADER_ID) = ABS(##$$HEADID$$##)
union
select RT.shipment_header_id, ''Employee_id is NULL in RCV_TRANSACTIONS'' "Level" 
from RCV_TRANSACTIONS RT
where RT.employee_id is null
and RT.created_by is not null
and ABS(RT.PO_HEADER_ID)= ABS(##$$HEADID$$##)',
      p_title                  => 'Receipts With Null EMPLOYEE_ID',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with null EMPLOYEE_ID in receiving tables. <br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
