debug('begin add_signature: PORCVANLAZ_PIE_ RCV_ASN_SHIPMT_NOT_OPEN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21342',
      p_sig_id                 => 'PORCVANLAZ_PIE_ RCV_ASN_SHIPMT_NOT_OPEN',
      p_sig_sql                => '    SELECT 
      POA.SEGMENT1 PO_NUMBER
    , RTI.PO_HEADER_ID
    , pie.interface_type
    , pie.interface_transaction_id
    , pie.column_name
    , pie.error_message
    , pie.error_message_name
    , pie.table_name
    , pie.batch_id
    , pie.interface_header_id
    , pie.interface_line_id
    , pie.processing_date
    , pie.request_id
    , pie.program_application_id
FROM PO_INTERFACE_ERRORS PIE,
     RCV_TRANSACTIONS_INTERFACE RTI,
     PO_HEADERS_ALL POA
WHERE PIE.error_message_name = ''RCV_ASN_SHIPMT_NOT_OPEN''
  AND PIE.INTERFACE_LINE_ID = RTI.INTERFACE_TRANSACTION_ID
  AND POA.PO_HEADER_ID = RTI.PO_HEADER_ID
  AND RTI.PO_HEADER_ID = ##$$HEADID$$##
ORDER BY RTI.PO_HEADER_ID desc,PIE.INTERFACE_LINE_ID DESC',
      p_title                  => 'PO Shipment (NUMBER = 1) is not open',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When searching for the LCM shipment 
on Enter Receipts RCVRCERC form with Source Type = LCM, the following error occurs:

FRM-40212: Invalid value for field SHIPMENT_NUM.',
      p_solution               => 'See details in [1509997/KB309607]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_PIE_ RCV_ASN_SHIPMT_NOT_OPEN');



debug('begin add_signature: RCV_RETURNED_ASN_EXISTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21497',
      p_sig_id                 => 'RCV_RETURNED_ASN_EXISTS',
      p_sig_sql                => 'SELECT
    Shipment_line_id, Shipment_header_id,asn_line_flag, quantity_shipped,quantity_received,shipment_line_status_code,
PO_Header_id,PO_Line_id,Po_Line_Location_id
FROM
    rcv_shipment_lines 
WHERE
    asn_line_flag = ''Y''
    AND nvl(quantity_shipped, 0) > nvl(quantity_received, 0)
    AND shipment_line_status_code = ''FULLY RECEIVED''
   AND  PO_HEADER_ID                = ##$$HEADID$$##',
      p_title                  => 'Returned ASN Exists',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When trying to cancel a PO, it throws error "Open ASN Exists Against This Shipment" though the ASN Was Returned.',
      p_solution               => 'Please raise an SR with the Inventory > Receiving team for Datafix by referring [2771508/KB748598] ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: RCV_RETURNED_ASN_EXISTS');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_PO_RT_SHPHDR_MISMATCH');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23027',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_PO_RT_SHPHDR_MISMATCH',
      p_sig_sql                => 'SELECT
    rcv.invoice_status_code            "INVOICE_STATUS_CODE",
    rcv.transaction_id                 "RCV_TXN_ID",
    rcv.transaction_type               "TXN_TYPE",
    rcv.source_document_code,
    rcv.po_line_id,
    rcv.po_line_location_id,
    rcv.po_distribution_id,
    rcv.transaction_date,
    rcv.timecard_id,
    rcv.parent_transaction_id,
    rcv.shipment_header_id "RT_SHIPMENT_HEADER_ID",
    rsl.shipment_header_id "RSL_SHIPMENT_HEADER_ID"
FROM   rcv_transactions     rcv,
       rcv_shipment_lines    rsl
WHERE    rsl.shipment_line_id = rcv.shipment_line_id
    AND rsl.shipment_header_id <> rcv.shipment_header_id
    AND rcv.invoice_status_code = ''PENDING'' 
    AND rcv.transaction_type = ''RECEIVE''
    AND rcv.po_header_id = ##$$HEADID$$##',
      p_title                  => 'Shipment Header Mismatch in Receiving Transactions (PO)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Pay on Receipt program was unable to generate invoices due to corruption on shipment header id in RCV_TRANSACTIONS. ',
      p_solution               => 'This issue requires a datafix, Please review [2669230/KB514177] - Pay on Receipt Autoinvoice Not Generated, Because RCV_TRANSACTIONS.SHIPMENT_HEADER_ID Not Match with SHIPMENT_HEADER_ID  of RCV_SHIPMENT_HEADERS And RCV_SHIPMENT_LINES. ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_PO_RT_SHPHDR_MISMATCH');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_MSN_RESINRCV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27074',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_MSN_RESINRCV',
      p_sig_sql                => 'SELECT msn.*
FROM mtl_serial_numbers msn , 
  po_headers_all ph ,
  mtl_material_transactions mmt,
  rcv_transactions rt
WHERE  msn.current_status = 7
AND mmt.transaction_source_id    = ph.po_header_id
AND rt.transaction_id = mmt.rcv_transaction_id
AND rt.transaction_type  = ''DELIVER''
AND rt.po_header_id =  ph.po_header_id
AND mmt.transaction_source_type_id = 1
AND mmt.transaction_action_id = 27
AND mmt.transaction_type_id = 18 
AND ph.po_header_id = ##$$HEADID$$## 
AND msn.last_transaction_id = mmt.transaction_id',
      p_title                  => 'Serials In Receiving (After PO Receipt)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Serials still show status ''Resides in Receiving'' even after the deliver transaction has completed. These serials cannot be used on transactions.',
      p_solution               => 'Review [1985351/KB738650] - Serial Has CURRENT_STATUS=7 (Resides In Receiving) And Does Not Allow Any Transaction Even Though Purchase Order Has Been Successfully Delivered To Inventory',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_MSN_RESINRCV');



debug('begin add_signature: SHIPMENT_SUPPLY_EXISTS_AFTER_FULL_CORRECTON_OVER_RECEIVED_ASN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11432',
      p_sig_id                 => 'SHIPMENT_SUPPLY_EXISTS_AFTER_FULL_CORRECTON_OVER_RECEIVED_ASN',
      p_sig_sql                => 'SELECT *
FROM  (SELECT Sum(quantity) AS quantity, shipment_line_id, UNIT_OF_MEASURE , TO_ORG_PRIMARY_UOM , ITEM_ID, po_line_location_id
      FROM   mtl_supply
      WHERE  supply_type_code = ''SHIPMENT''  
      GROUP BY shipment_line_id, UNIT_OF_MEASURE, TO_ORG_PRIMARY_UOM, ITEM_ID, po_line_location_id
     ) ms,
     rcv_shipment_lines rsl,
     po_line_locations_all plla
WHERE  ms.shipment_line_id = rsl.shipment_line_id  
AND    rsl.PO_HEADER_ID = ##$$HEADID$$##
AND    rsl.ASN_LINE_FLAG = ''Y''
AND    ms.quantity + rsl.quantity_received > rsl.quantity_shipped
AND    ms.po_line_location_id = plla.line_location_id',
      p_title                  => 'Shipment supply data still exists after full correction of over received ASN',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Shipment supply data still exists after full correction of over received ASN',
      p_solution               => 'Please follow the solution from document: Shipment Supply Data Exists After Full Correction to Over Received ASN (Data Fix) [1204303/KB712390]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: SHIPMENT_SUPPLY_EXISTS_AFTER_FULL_CORRECTON_OVER_RECEIVED_ASN');



