debug('begin add_signature: EBS_MFG_INV_PORCVANL_RCV_TRX_PROJECT_TASK_MISMATCH');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30999',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_RCV_TRX_PROJECT_TASK_MISMATCH',
      p_sig_sql                => 'SELECT  RT.TRANSACTION_ID, RT.TRANSACTION_TYPE, PD.PO_HEADER_ID, PD.PO_LINE_ID, PD.LINE_LOCATION_ID,PD.PO_DISTRIBUTION_ID,
RT.PROJECT_ID RT_PROJECT_ID, RT.TASK_ID RT_TASK_ID, PD.PROJECT_ID PO_PROJECT_ID, PD.TASK_ID PO_TASK_ID
FROM RCV_TRANSACTIONS RT, PO_DISTRIBUTIONS_ALL PD
WHERE RT.PO_HEADER_ID = PD.PO_HEADER_ID
AND RT.PO_LINE_LOCATION_ID= PD.LINE_LOCATION_ID
AND RT.PO_DISTRIBUTION_ID =PD.PO_DISTRIBUTION_ID
AND PD.PO_HEADER_ID  = ##$$HEADID$$##    
AND PD.PROJECT_ID IS NOT NULL
AND RT.PROJECT_ID IS NOT NULL
AND (PD.PROJECT_ID <> RT.PROJECT_ID
OR NVL(PD.TASK_ID, -1) <> NVL(RT.TASK_ID, -1) ) ',
      p_title                  => 'Receiving Transaction Has Different Project or Task Than Purchase Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There is is a difference of data in the tables RCV_TRANSACTIONS (RT) and PO_DISTRIBUTIONS_ALL (POD). <br>
The inspection or delivery or return transaction for such PO may end in error with following error.<br>
RVTTH-115f: Subroutine process_transaction() returned error',
      p_solution               => 'Refer to [1528718/KB295143] for details.
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_RCV_TRX_PROJECT_TASK_MISMATCH');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_MISSING_SUPPLY_APPROVED_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31147',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_MISSING_SUPPLY_APPROVED_PO',
      p_sig_sql                => '    SELECT DISTINCT poll.line_location_id
        FROM   po_line_locations_all poll,
               po_headers_all poh
        WHERE  poh.po_header_id = poll.po_header_id
    AND poh.authorization_status = ''APPROVED''
           AND Nvl(poll.closed_code,''OPEN'') NOT IN
                    (''CLOSED'',''FINALLY CLOSED'',''CLOSED FOR RECEIVING'')
           AND Nvl(poll.cancel_flag,''N'') <> ''Y''
           AND poll.shipment_type IN (''STANDARD'')
           AND vendor_order_num is not null
          AND nvl(poll.quantity_received,0) <=0
           AND nvl(poll.quantity_shipped,0) <=0
           AND poh.PO_HEADER_ID = ##$$HEADID$$##
           AND  NOT  EXISTS
                  (SELECT * FROM mtl_supply mtl
                   WHERE mtl.po_line_location_id=poll.line_location_id)',
      p_title                  => 'Missing Supply for Approved PO',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing Supply for Purchase Order.   Line/Shipment does not show on Item Supply/Demand.',
      p_solution               => 'See [416113/KB425645] for solution steps.',
      p_success_msg            => 'Supply is available for Purchase Order.   Line/Shipment shows on Item Supply/Demand.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_MISSING_SUPPLY_APPROVED_PO');



