debug('begin add_signature: EBS_MFG_INV_PORCVANL_MISSING_DS_SO_ISSUE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '32625',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_MISSING_DS_SO_ISSUE',
      p_sig_sql                => 'SELECT rcv.transaction_id, oel.line_id, oel.flow_status_code , poll.line_location_id, poll.po_line_id, poll.po_header_id, oel.shipped_quantity
   FROM   rcv_transactions rcv,
          po_line_locations_all poll,
          oe_drop_ship_sources oed,
          oe_order_lines_all oel
   WHERE  oel.source_type_code = ''EXTERNAL''
   AND    nvl(oel.shipped_quantity,0) = 0
   AND    oed.line_id = oel.line_id
   AND    oed.line_location_id is not null
   AND    poll.line_location_id = oed.line_location_id
   AND    rcv.po_line_location_id = poll.line_location_id
   AND    rcv.TRANSACTION_TYPE = ''DELIVER'' 
   AND    rcv.po_header_id  =   ##$$HEADID$$##',
      p_title                  => 'Drop Ship Sales Order Issue Missing After PO Receipt',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Issue transaction missing for Drop Ship Purchase Order (PO) receipt and the Sales Order line Shipped quantity was not updated. ',
      p_solution               => 'Review -
Inventory Standard Datafix Instruction #21: Sales Order Issue Transaction Missing In MTI And MMT For A Drop Ship PO Receipt And Sales Order Line Shipped Qty Not Updated [1672571/KB629493]',
      p_success_msg            => 'No receiving transactions were found with missing sales order issue transactions and incomplete Sales Order Shipped quantity.  See [1672571/KB629493] for details',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_MISSING_DS_SO_ISSUE');



