debug('begin add_signature: PORCVANLAZ_PR_RTI_DATA');
   l_info('##MASK##CUSTOMER_PARTY_NAME'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3691',
      p_sig_id                 => 'PORCVANLAZ_PR_RTI_DATA',
      p_sig_sql                => 'select rti.* 
  from rcv_transactions_interface rti 
 where (nvl (rti.document_num , ''-99999'') =  ''##$$DOCNUM$$##'' 
       and nvl(rti.release_num , ''-99999'') =  ''##$$RELNUM$$##''
       AND nvl(rti.po_release_id, -99999) = ##$$RELID$$##   ) 
   or exists (
    select 1 
      from po_headers_all poh ,
           po_releases_all pr
     where pr.po_header_id = poh.po_header_id 
       and poh.segment1 =  ''##$$DOCNUM$$##''
       and pr.release_num =  ''##$$RELNUM$$##'' 
       and rti.po_release_id = pr.po_release_id) 
   or exists (
    select 2 
      from po_headers_all poh 
     where poh.segment1 =  ''##$$DOCNUM$$##'' 
       and rti.po_header_id = poh.po_header_id
       AND ##$$RELID$$## IS NULL	   )
    or parent_transaction_id IN
      (select transaction_id 
       from RCV_TRANSACTIONS
       where po_header_id = ##$$HEADID$$##
       and po_release_id = ##$$RELID$$##
      )',
      p_title                  => 'RCV_TRANSACTIONS_INTERFACE',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Records in Receiving Transactions Interface',
