    EXISTS
    (
      SELECT
        1
      FROM
        PO_HEADERS_ALL PH ,
        PO_RELEASES_ALL PR
      WHERE
        RTI.PO_HEADER_ID    = PH.PO_HEADER_ID
      AND PH.PO_HEADER_ID   = ##$$HEADID$$##
      AND PR.PO_HEADER_ID   = PH.PO_HEADER_ID
      AND PR.PO_RELEASE_ID  = ##$$RELID$$##
      AND RTI.PO_RELEASE_ID = PR.PO_RELEASE_ID
    )
  OR
    (
      NVL( RTI.DOCUMENT_NUM , ''-99999'') = ''##$$DOCNUM$$##''
    AND NVL(RTI.RELEASE_NUM , ''-99999'') = ''##$$RELNUM$$##''
    )
  )',
      p_title                  => 'RCV_LOTS_INTERFACE',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This table is used for storing temporary lot number transaction records for a parent record in the RCV_TRANSACTIONS_INTERFACE table. There were no details found.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_PR_RLI_DATA');



