debug('begin add_signature: PORCVANLAZ_ENCUMB_CHECK_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3723',
      p_sig_id                 => 'PORCVANLAZ_ENCUMB_CHECK_PR',
      p_sig_sql                => 'SELECT HOU.name "Operating Unit Name" ,
POH.SEGMENT1 ,
por.release_num,
por.po_release_id,
POH.PO_HEADER_ID ,
POH.ORG_ID ,
POH.TYPE_LOOKUP_CODE ,
POL.PO_LINE_ID ,
Pol.Line_Num ,
PLL.LINE_LOCATION_ID ,
PLL.SHIPMENT_NUM ,
PLL.APPROVED_FLAG "PLL.APPROVED_FLAG" ,
CASE FSP.PURCH_ENCUMBRANCE_FLAG 
when PLL.ENCUMBERED_FLAG then FSP.PURCH_ENCUMBRANCE_FLAG
ELSE ''<strong><FONT COLOR = RED>'' || FSP.PURCH_ENCUMBRANCE_FLAG|| ''</FONT></strong>'' END "Encumbered Flag- OU LEVEL" ,
CASE PLL.ENCUMBERED_FLAG 
when  FSP.PURCH_ENCUMBRANCE_FLAG then PLL.ENCUMBERED_FLAG 
ELSE  ''<strong><FONT COLOR = RED>'' || PLL.ENCUMBERED_FLAG || ''</FONT></strong>'' END  "Encumbered Flag- PO SHIPMENT" ,
POD.PO_DISTRIBUTION_ID ,
POD.DISTRIBUTION_NUM
FROM PO_HEADERS_ALL POH ,
PO_LINES_ALL POL ,
PO_LINE_LOCATIONS_ALL PLL ,
PO_DISTRIBUTIONS_ALL POD ,
PO_RELEASES_ALL POR ,
FINANCIALS_SYSTEM_PARAMS_ALL FSP ,
HR_ORGANIZATION_UNITS HOU ,
MTL_PARAMETERS MP
WHERE poh.po_header_id = ##$$HEADID$$##
AND pll.po_release_id = ##$$RELID$$##
AND POH.TYPE_LOOKUP_CODE = ''BLANKET'' 
AND POL.PO_HEADER_ID     = POH.PO_HEADER_ID
AND PLL.PO_LINE_ID       = POL.PO_LINE_ID
AND POD.LINE_LOCATION_ID = PLL.LINE_LOCATION_ID
AND POR.PO_RELEASE_ID    = PLL.PO_RELEASE_ID
AND pll.po_release_id    = pod.po_release_id
AND POH.ORG_ID           = FSP.ORG_ID
AND FSP.ORG_ID           = HOU.ORGANIZATION_ID
AND POH.ORG_ID           = HOU.ORGANIZATION_ID
AND MP.ORGANIZATION_ID   = PLL.SHIP_TO_ORGANIZATION_ID
AND NOT EXISTS
(SELECT 1
FROM PO_DISTRIBUTIONS_ALL POD
WHERE POD.LINE_LOCATION_ID     = PLL.LINE_LOCATION_ID
AND (POD.DESTINATION_TYPE_CODE = ''SHOP FLOOR''
OR POD.DISTRIBUTION_TYPE      <> ''BLANKET'')
)
AND  PLL.ENCUMBERED_FLAG <> FSP.PURCH_ENCUMBRANCE_FLAG
ORDER BY POH.ORG_ID,
POH.PO_HEADER_ID,
POL.PO_LINE_ID,
PLL.LINE_LOCATION_ID,
POD.PO_DISTRIBUTION_ID',
      p_title                  => 'Encumbrance Check',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There is atleast one PO shipment with a different ENCUMBERED_FLAG compared to financial options.<Br></BR>
This may cause the following error:<Br>
APP-PO-14094: No records meet your search criteria.<Br>
Cause: There are no records that match your search criteria.<Br>
Action: Re-enter your search criteria with fewer or different parameters.',
      p_solution               => 'This means the encumbrance setup has been changed after the PO was created.<Br>
Review APP-PO-14094 No data found on several receipt forms after encumbrance is enabled. [759777/KB362581].',
