debug('begin add_signature: PORCVANLAZ_UNPROC_RTI_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3724',
      p_sig_id                 => 'PORCVANLAZ_UNPROC_RTI_PR',
      p_sig_sql                => 'SELECT INTERFACE_TRANSACTION_ID,
   GROUP_ID,
  CREATION_DATE,
  TRANSACTION_TYPE,
  PROCESSING_STATUS_CODE,
  PROCESSING_MODE_CODE,
  TRANSACTION_STATUS_CODE,
  ITEM_ID,
  QUANTITY,VALIDATION_FLAG, 
  MOBILE_TXN, 
  LPN_GROUP_ID 
FROM RCV_TRANSACTIONS_INTERFACE
WHERE PROCESSING_MODE_CODE = ''BATCH''
AND PROCESSING_STATUS_CODE = ''PENDING''
AND TRANSACTION_STATUS_CODE = ''PENDING''
AND ( po_header_id        =  ##$$HEADID$$##
AND po_release_id         =  ##$$RELID$$##
OR parent_transaction_id IN
  (SELECT TRANSACTION_ID 
  FROM RCV_TRANSACTIONS 
  WHERE PO_HEADER_ID =  ##$$HEADID$$##
  AND po_release_id  =  ##$$RELID$$##))',
      p_title                  => 'Unprocessed Records in Interface - Batch Mode',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are unprocessed records in RCV_TRANSACTIONS_INTERFACE table, which could prevent receiving transactions.',
      p_solution               => 'Refer to the following note: <Br>
Review -FAQ: Receiving Transaction Processor (RTP) [210188/FAQ4846]. <Br>
Run receiving transaction processor for the above GROUP_ID to process the records of RCV_TRANSACTIONS_INTERFACE table.',
      p_success_msg            => 'There are no unprocessed records in RCV_TRANSACTIONS_INTERFACE table. No action required.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '19'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNPROC_RTI_PR');



debug('begin add_signature: PORCVANLAZ_STUCK_RTI_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3725',
      p_sig_id                 => 'PORCVANLAZ_STUCK_RTI_PR',
      p_sig_sql                => 'SELECT INTERFACE_TRANSACTION_ID,
  CREATION_DATE,
  TRANSACTION_TYPE,
  PROCESSING_STATUS_CODE,
  PROCESSING_MODE_CODE,
  TRANSACTION_STATUS_CODE,
  ITEM_ID,
  QUANTITY,
  VALIDATION_FLAG,
  MOBILE_TXN,
  LPN_GROUP_ID
FROM RCV_TRANSACTIONS_INTERFACE
WHERE ((po_header_id       = ##$$HEADID$$##
AND po_release_id         = ##$$RELID$$##)
OR parent_transaction_id IN
  (SELECT TRANSACTION_ID
  FROM RCV_TRANSACTIONS
  WHERE PO_HEADER_ID = ##$$HEADID$$##
  AND po_release_id  = ##$$RELID$$##
  )
OR 
  (DOCUMENT_NUM = ''##$$DOCNUM$$##'' 
  AND RELEASE_NUM = ''##$$RELNUM$$##''
  ) )
AND ( PROCESSING_MODE_CODE <> ''BATCH''
OR PROCESSING_STATUS_CODE  <> ''PENDING''
OR TRANSACTION_STATUS_CODE <> ''PENDING'')',
