debug('begin add_signature: PORCVANLAZ_SHIPMENT_HEADER_ID_CORRUPTION_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3730',
      p_sig_id                 => 'PORCVANLAZ_SHIPMENT_HEADER_ID_CORRUPTION_PR',
      p_sig_sql                => 'SELECT distinct rsl.shipment_header_id "rsl.shipment_header_id" ,
		rt.shipment_header_id "rt.shipment_header_id ", 
		rsl.shipment_line_id "rsl.shipment_line_id"
FROM   rcv_transactions     rt,
       rcv_shipment_lines   rsl,
       rcv_shipment_headers rsh
WHERE  rt.shipment_line_id = rsl.shipment_line_id
AND 	rsl.PO_HEADER_ID = ##$$HEADID$$##
AND rsl.po_release_id =  ##$$RELID$$##
AND    rsl.shipment_header_id = rsh.shipment_header_id
AND    rsl.shipment_line_status_code IN (''FULLY RECEIVED'', ''PARTIALLY RECEIVED'')
AND    rt.shipment_header_id <> rsl.shipment_header_id
AND    NOT EXISTS (select 1 
                   from   rcv_shipment_headers rtrsh
                   where  rtrsh.shipment_header_id = rt.shipment_header_id
                   and    rtrsh.receipt_source_code = rsh.receipt_source_code
                   and    rtrsh.ship_to_org_id = rsh.ship_to_org_id)',
      p_title                  => 'Shipment Header ID Corruption',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records with SHIPMENT_HEADER_ID corruption for the blanket release between RCV_SHIPMENT_LINES and RCV_TRANSACTIONS for the PO.',
      p_solution               => 'Run the datafix scripts of the following note to fix the records.<Br>
RCVTXERT APP-PO-14094 FRM-40212 Multiple receipt for intransit shipment gives corrupted SHIPMENT_HEADER_ID / Receipt record cannot be seen RCVRCVRC / Duplicate shipment number [1198144/KB486431]',
      p_success_msg            => 'There are no records with SHIPMENT_HEADER_ID corruption for the PO.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '22'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_SHIPMENT_HEADER_ID_CORRUPTION_PR');



