debug('begin add_signature: PORCANLZ_ORPHAN_RSH_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11525',
      p_sig_id                 => 'PORCANLZ_ORPHAN_RSH_PR',
      p_sig_sql                => 'SELECT SHIPMENT_HEADER_ID SHIPMENT_HEADER_ID,
  RECEIPT_NUM,
  SHIPMENT_NUM,
  RECEIPT_SOURCE_CODE,
  ASN_TYPE,
  SHIP_TO_ORG_ID
FROM RCV_SHIPMENT_HEADERS rsh
WHERE rsh.receipt_source_code = ''VENDOR''
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS rt
  WHERE rt.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS_INTERFACE rti
  WHERE rti.shipment_header_id     = rsh.shipment_header_id
  AND (rti.processing_status_code IN (''RUNNING'',''PENDING'')
  OR NVL(rti.validation_flag,''N'')  = ''N'' )
  AND ((rti.po_header_id is not null and rti.po_header_id = ##$$HEADID$$##  and rti.po_release_id is not null and rti.po_release_id =  ##$$RELID$$##) or (rti.document_num is not null and rti.document_num = ''##$$DOCNUM$$##'' and rti.release_num is not null and rti.release_num = ''##$$RELNUM$$##'' ))
  )
AND ROWNUM <=20
ORDER BY shipment_header_id',
