debug('begin add_signature: PORCVANLAZ_NULL_EMPLOYEE_ID_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14132',
      p_sig_id                 => 'PORCVANLAZ_NULL_EMPLOYEE_ID_PR',
      p_sig_sql                => 'select RSH.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_HEADERS'' "Level" 
from RCV_SHIPMENT_HEADERS RSH,
RCV_SHIPMENT_LINES RSL
WHERE ABS(RSL.PO_HEADER_ID) =ABS(##$$HEADID$$##)
AND RSL.SHIPMENT_HEADER_ID = RSH.SHIPMENT_HEADER_ID
AND RSL.PO_RELEASE_ID =  ABS(##$$RELID$$##)
AND RSH.employee_id is null
and RSH.created_by is not null
union
select RSL.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_LINES'' "Level" 
from RCV_SHIPMENT_LINES RSL
where RSL.employee_id is null
and RSL.created_by is not null
AND ABS(RSL.PO_HEADER_ID) = ABS(##$$HEADID$$##)
AND ABS(RSL.PO_RELEASE_ID) = ABS(##$$RELID$$##)
union
select RT.shipment_header_id, ''Employee_id is NULL in RCV_TRANSACTIONS'' "Level" 
from RCV_TRANSACTIONS RT
where RT.employee_id is null
and RT.created_by is not null
and ABS(RT.PO_HEADER_ID)=ABS(##$$HEADID$$##) 
AND ABS(RT.PO_RELEASE_ID) = ABS(##$$RELID$$##)',
      p_title                  => 'Receipts With Null EMPLOYEE_ID',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with null EMPLOYEE_ID in receiving tables. <br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
      p_solution               => 'Run the datafix to update EMPLOYEE_ID for all the problematic rows in receiving tables. <br>
Review datafix for RCVRCVRC: Receiver Is Null On Some Transactions [579554/KB619161]. <br>',
      p_success_msg            => 'There are no receipts with null EMPLOYEE_ID in receiving tables. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_NULL_EMPLOYEE_ID_PR');



debug('begin add_signature: PORCANLZ_NULL_LOCATOR_RCPTS_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14137',
      p_sig_id                 => 'PORCANLZ_NULL_LOCATOR_RCPTS_PR',
      p_sig_sql                => 'SELECT rt.transaction_id, rt.transaction_type, rt.parent_transaction_id, rt.transaction_date,
 rt.quantity, rt.unit_of_measure,rt.shipment_header_id,rt.shipment_line_id,
 rt.po_header_id,rt.po_release_id,rt.po_line_id,rt.po_line_location_id,rt.po_distribution_id,
rt.vendor_id,rt.vendor_site_id,rt.organization_id,rt.subinventory,rt.locator_id
FROM   rcv_transactions rt
WHERE  rt.destination_type_code = ''INVENTORY''
    AND rt.transaction_type = ''DELIVER''
    AND rt.source_document_code = ''PO''
    AND rt.po_header_id = ##$$HEADID$$##
    AND rt.po_release_id = ##$$RELID$$##
    AND (rt.locator_id IS NULL OR rt.locator_id = -1)
    AND EXISTS (SELECT ''1''
                  FROM  mtl_material_transactions mmt
                 WHERE  mmt.locator_id > 0
                   AND mmt.rcv_transaction_id = rt.transaction_id)',
      p_title                  => 'Receipts With Null Locator',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with null LOCATOR_ID in RCV_TRANSACTIONS table.<br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.',
      p_solution               => 'Run datafix to correct LOCATOR_ID in RCV_TRANSACTIONS table. <br>
Review the datafix of RCVRCERC: Receipts Form Allows Transaction To Save When Locator Is Null and Subinventory Is Locator Controlled [1515246/KB264006].',
      p_success_msg            => 'There are no receipts with null LOCATOR_ID in RCV_TRANSACTIONS table.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCANLZ_NULL_LOCATOR_RCPTS_PR');



