debug('begin add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14608',
      p_sig_id                 => 'PORCVANLAZ_UNWANTED_MTL_SUPPLY_PR',
      p_sig_sql                => 'SELECT ms.supply_type_code ,
  ms.supply_source_id ,
  ms.po_header_id ,
  ms.po_line_id ,
  ms.po_line_location_id ,
  ms.shipment_header_id ,
  ms.shipment_line_id ,
  ms.item_id ,
  ms.quantity ,
  ms.unit_of_measure ,
  ms.destination_type_Code ,
  ms.po_distribution_id ,
  ms.rcv_transaction_id ,
  ms.to_org_primary_quantity ,
  ms.to_org_primary_uom ,
  ms.to_organization_id ,
  ms.to_subinventory ,
  ms.cost_group_id
FROM MTL_SUPPLY ms
WHERE quantity    <0
AND po_header_id  = ##$$HEADID$$##
AND po_release_id = ##$$RELID$$##
UNION
SELECT ms.supply_type_code ,
  ms.supply_source_id ,
  ms.po_header_id ,
  ms.po_line_id ,
  ms.po_line_location_id ,
  ms.shipment_header_id ,
  ms.shipment_line_id ,
  ms.item_id ,
  ms.quantity ,
  ms.unit_of_measure ,
  ms.destination_type_Code ,
  ms.po_distribution_id ,
  ms.rcv_transaction_id ,
  ms.to_org_primary_quantity ,
  ms.to_org_primary_uom ,
  ms.to_organization_id ,
  ms.to_subinventory ,
  ms.cost_group_id
FROM MTL_SUPPLY ms,
  RCV_SHIPMENT_LINES rsl
WHERE ms.shipment_line_id         = rsl.shipment_line_id
AND rsl.shipment_line_status_code = ''CANCELLED''
AND ms.po_header_id               = ##$$HEADID$$##
AND ms.po_release_id              = ##$$RELID$$##
UNION
SELECT ms.supply_type_code ,
  ms.supply_source_id ,
  ms.po_header_id ,
  ms.po_line_id ,
  ms.po_line_location_id ,
  ms.shipment_header_id ,
  ms.shipment_line_id ,
  ms.item_id ,
  ms.quantity ,
  ms.unit_of_measure ,
  ms.destination_type_Code ,
  ms.po_distribution_id ,
  ms.rcv_transaction_id ,
  ms.to_org_primary_quantity ,
  ms.to_org_primary_uom ,
  ms.to_organization_id ,
  ms.to_subinventory ,
  ms.cost_group_id
FROM MTL_SUPPLY ms
WHERE ms.shipment_line_id IS NOT NULL
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.shipment_line_id = ms.shipment_line_id
  AND rsl.po_header_id       = ##$$HEADID$$##
  AND rsl.po_release_id      = ##$$RELID$$##
  )
AND ms.po_header_id  = ##$$HEADID$$##
AND ms.po_release_id = ##$$RELID$$##
UNION
SELECT ms.supply_type_code ,
  ms.supply_source_id ,
  ms.po_header_id ,
  ms.po_line_id ,
  ms.po_line_location_id ,
  ms.shipment_header_id ,
  ms.shipment_line_id ,
  ms.item_id ,
  ms.quantity ,
  ms.unit_of_measure ,
  ms.destination_type_Code ,
  ms.po_distribution_id ,
  ms.rcv_transaction_id ,
  ms.to_org_primary_quantity ,
  ms.to_org_primary_uom ,
  ms.to_organization_id ,
  ms.to_subinventory ,
  ms.cost_group_id
FROM MTL_SUPPLY ms,
  PO_LINE_LOCATIONS_ALL pll
WHERE pll.line_location_id         = ms.po_line_location_id
AND ms.supply_type_code           IN (''SHIPMENT'',''RECEIVING'')
AND (NVL(pll.closed_code, ''OPEN'') IN (''FINALLY CLOSED'')
OR NVL(pll.cancel_flag,''N'')        = ''Y'')
AND ms.po_header_id                = ##$$HEADID$$##
AND ms.po_release_id               = ##$$RELID$$##
UNION
SELECT ms.supply_type_code ,
  ms.supply_source_id ,
  ms.po_header_id ,
  ms.po_line_id ,
  ms.po_line_location_id ,
  ms.shipment_header_id ,
  ms.shipment_line_id ,
  ms.item_id ,
  ms.quantity ,
  ms.unit_of_measure ,
  ms.destination_type_Code ,
  ms.po_distribution_id ,
  ms.rcv_transaction_id ,
  ms.to_org_primary_quantity ,
  ms.to_org_primary_uom ,
  ms.to_organization_id ,
  ms.to_subinventory ,
  ms.cost_group_id
FROM MTL_SUPPLY ms,
  PO_LINE_LOCATIONS_ALL pll
WHERE ms.po_line_location_id IS NOT NULL
AND ms.po_line_location_id    = pll.line_location_id
AND ms.supply_type_code      IN (''PO'')
AND pll.quantity_received    >=pll.quantity
AND ms.po_header_id           = ##$$HEADID$$##
AND ms.po_release_id          = ##$$RELID$$##',
      p_title                  => 'Purchase Release Records With Unwanted MTL_SUPPLY',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are purchase release records with unwanted supply in MTL_SUPPLY table. <br>
',
      p_solution               => 'Run the datafix to clear unwanted supply in MTL_SUPPLY table. <br>
For datafix, refer to [1321193/KB742361] Datafix to Remove Unwanted Supply From Supply Tables <br>',
      p_success_msg            => 'There are no records with unwanted supply in MTL_SUPPLY table.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_PR');



