debug('begin add_signature: PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4815',
      p_sig_id                 => 'PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IOT',
      p_sig_sql                => 'SELECT rsl.shipment_header_id "rsl.shipment_header_id",
        rsl.shipment_line_id "rsl.shipment_line_id",
        rsh.shipment_num "rsh.shipment_num",
        rsl.mmt_transaction_id "rsl.mmt_transaction_id"
 FROM   rcv_shipment_lines rsl,
        rcv_shipment_headers rsh
 WHERE  rsl.shipment_header_id = rsh.shipment_header_id
 AND    rsl.mmt_transaction_id IS NOT null
 AND    rsh.receipt_source_code = ''INVENTORY''
 AND    rsh.shipment_num= ''##$$IOTNUM$$##''
 AND EXISTS
    (
     SELECT 1
     FROM mtl_parameters mp
     WHERE mp.organization_id = rsh.organization_id
    )
 AND NOT EXISTS
    (
     SELECT 1
     FROM mtl_material_transactions mmt
     WHERE mmt.transaction_id = rsl.mmt_transaction_id
     AND   mmt.transaction_source_type_id = 13
     AND   mmt.transaction_action_id in (3,21)
    )
 AND NOT EXISTS
    (
     SELECT 1
     FROM  mtl_material_transactions mmt,
           rcv_transactions rt
     WHERE mmt.rcv_transaction_id = rt.transaction_id
     AND   rt.shipment_line_id = rsl.shipment_line_id
     AND   rt.transaction_type = ''DELIVER''
    )
 ORDER BY 1',
      p_title                  => 'Missing Issue Material Transactions For IOT Shipment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are IOT shipments with missing issue material transactions data OR there are duplicate shipment lines. <br.>
You may see an error attempting to receive like this: "APP-PO-15576: Shipment source ### for shipment line ### is invalid" where the shipment source is an invalid transaction id (mmt_transaction_id).',
      p_solution               => 'Run the datafix script of: <br>
Datafix For Missing Issue Material Transactions For Intransit Shipments [789732/KB468168] for more information.<Br></Br>
The root cause for this issue can be reviewed in the following documents:<Br>
Some Intransit Shipments Fail with RVTII-060 Fob (Free On Board) Point Not Defined / Duplicate Shipments Lines [396788/KB235980].<Br>
Root Cause RVTII-060 Missing Fob Point Error Video - [1390812/KB309772].',
      p_success_msg            => 'There are no Inter Org transfer shipments with missing issue material transactions data.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
