debug('end add_signature: PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IOT');



debug('begin add_signature: PORCANLZ_ORPHAN_RSH_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11527',
      p_sig_id                 => 'PORCANLZ_ORPHAN_RSH_IOT',
      p_sig_sql                => 'SELECT SHIPMENT_HEADER_ID SHIPMENT_HEADER_ID,
  RECEIPT_NUM,
  SHIPMENT_NUM,
  RECEIPT_SOURCE_CODE,
  ASN_TYPE,
  SHIP_TO_ORG_ID
FROM RCV_SHIPMENT_HEADERS rsh
WHERE receipt_source_code = ''INVENTORY''
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS rt
  WHERE rt.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS_INTERFACE rti
  WHERE rti.shipment_header_id     = rsh.shipment_header_id
  AND (rti.processing_status_code IN (''RUNNING'',''PENDING'')
  OR NVL(rti.validation_flag,''N'')  = ''N'' )
  )
AND ROWNUM <=1
ORDER BY shipment_header_id',
      p_title                  => 'Orphan Shipment Headers for Inter Org Transfer Shipments',
      p_fail_condition         => '[SHIPMENT_HEADER_ID] = [##$$HEADID$$##]',
      p_problem_descr          => 'Orphan Shipment Headers exist in RCV_SHIPMENT_HEADERS table. <br>
There may be more number of records than the ones fetched. We are displaying only one or two records here for your reference.<br>
The records will not cause any issue but can be removed. <BR>
This is a general check. This is not specific to the analyzer parameters.',
      p_solution               => 'Remove the orphan records.<Br>
Review Datafix for Orphan Receipt or Shipment Headers (RCV_SHIPMENT_HEADERS) [977477/KB157568].',
      p_success_msg            => 'No orphan receiving shipment header records exist in RCV_SHIPMENT_HEADERS table for SHIPMENT_HEADER_ID ['||mask_text(g_header_id, nvl( upper(''), 'NO_MASK') )||'].',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '21'
      );
   l_info.delete;
debug('end add_signature: PORCANLZ_ORPHAN_RSH_IOT');



debug('begin add_signature: PORCVANLAZ_UNPROC_RTI_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11575',
      p_sig_id                 => 'PORCVANLAZ_UNPROC_RTI_IOT',
      p_sig_sql                => 'SELECT INTERFACE_TRANSACTION_ID,
GROUP_ID,
CREATION_DATE,
TRANSACTION_TYPE,
PROCESSING_STATUS_CODE,
PROCESSING_MODE_CODE,
TRANSACTION_STATUS_CODE,
ITEM_ID,
QUANTITY,VALIDATION_FLAG, 
MOBILE_TXN, 
LPN_GROUP_ID 
FROM RCV_TRANSACTIONS_INTERFACE RTI
WHERE PROCESSING_MODE_CODE = ''BATCH''
AND PROCESSING_STATUS_CODE = ''PENDING''
AND TRANSACTION_STATUS_CODE = ''PENDING''
AND (EXISTS
(SELECT 1
FROM RCV_HEADERS_INTERFACE RHI
WHERE RTI.HEADER_INTERFACE_ID = RHI.HEADER_INTERFACE_ID
AND (RHI.SHIPMENT_NUM = ''##$$IOTNUM$$##''
OR EXISTS
(SELECT 1
FROM RCV_SHIPMENT_HEADERS RSH
WHERE RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$##
AND RSH.RECEIPT_SOURCE_CODE = ''INVENTORY''
AND RHI.RECEIPT_HEADER_ID = RSH.SHIPMENT_HEADER_ID
) )
)
OR EXISTS
(SELECT 2
FROM RCV_SHIPMENT_HEADERS RSH
WHERE RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$##
AND RSH.RECEIPT_SOURCE_CODE = ''INVENTORY''
AND (RTI.SHIPMENT_HEADER_ID = RSH.SHIPMENT_HEADER_ID
OR RTI.SHIPMENT_NUM = NVL(''##$$IOTNUM$$##'' ,RSH.SHIPMENT_NUM) )
) 
OR (RTI.SHIPMENT_NUM = ''##$$IOTNUM$$##'' 
    AND RTI.TO_ORGANIZATION_ID = ##$$IOTORGID$$##
    AND RTI.RECEIPT_SOURCE_CODE = ''INVENTORY'')
)',
      p_title                  => 'Unprocessed Records in Interface - Batch Mode',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are unprocessed records in RCV_TRANSACTIONS_INTERFACE table which could prevent Receiving Transactions.',
      p_solution               => 'For solution, refer to the following note: <Br>
[210188/FAQ4846] - FAQ: Receiving Transaction Processor (RTP)',
      p_success_msg            => 'There are no unprocessed records in RCV_TRANSACTIONS_INTERFACE table. No action required.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNPROC_RTI_IOT');



