debug('begin add_signature: PORCVANLAZ_MISSING_SERIALS_SUPPLY_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14163',
      p_sig_id                 => 'PORCVANLAZ_MISSING_SERIALS_SUPPLY_IOT',
      p_sig_sql                => 'SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id, ''Item not Lot Controlled'' lot_number, mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''SHIPMENT'')
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = mut.inventory_item_id
		AND current_organization_id = mut.organization_id
		AND serial_number = mut.serial_number
		AND current_status = 5)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID 
UNION
SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id, mtln.lot_number lot_number,mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_TRANSACTION_LOT_NUMBERS mtln,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mtln.transaction_id
	AND mtln.serial_transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''SHIPMENT'')
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = mut.inventory_item_id
		AND current_organization_id = mut.organization_id
		AND serial_number = mut.serial_number
		AND lot_number = mtln.lot_number
		AND current_status = 5)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID 
UNION
SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id,''Item not Lot Controlled'' lot_number, mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM RCV_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = mut.inventory_item_id
		AND current_organization_id = mut.organization_id
		AND serial_number = mut.serial_number
		AND current_status = 5)
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID 
UNION
SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id, mtln.lot_number lot_number, mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_TRANSACTION_LOT_NUMBERS mtln,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mtln.transaction_id
	AND mtln.serial_transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM RCV_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = mut.inventory_item_id
		AND current_organization_id = mut.organization_id
		AND serial_number = mut.serial_number
		AND lot_number = mtln.lot_number
		AND current_status = 5)
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID 
UNION
SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id, ''Item not Lot Controlled'' lot_number, mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM RCV_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = rsl.item_id
		AND current_organization_id = rsl.to_organization_id
		AND serial_number = mut.serial_number
		AND current_status = 7)
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID 
UNION
SELECT rsl.from_organization_id, rsl.to_organization_id, mmt.shipment_number, rsl.item_id, mtln.lot_number lot_number, mut.serial_number, rsl.shipment_header_id, rsl.shipment_line_id, rsl.requisition_line_id, rsl.quantity_shipped, rsl.quantity_received, rsl.shipment_line_status_code
FROM 
MTL_MATERIAL_TRANSACTIONS mmt,
MTL_TRANSACTION_LOT_NUMBERS mtln,
MTL_UNIT_TRANSACTIONS mut,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh
WHERE mmt.transaction_source_type_id = 13
	AND mmt.transaction_action_id = 21
	AND mmt.transaction_id = mtln.transaction_id
	AND mtln.serial_transaction_id = mut.transaction_id
	AND mmt.transaction_id = rsl.mmt_transaction_id
	AND EXISTS ( SELECT 1
		FROM MTL_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM RCV_SUPPLY
		WHERE shipment_line_id = rsl.shipment_line_id
		AND supply_type_code = ''RECEIVING'')
	AND EXISTS ( SELECT 1
		FROM MTL_SERIAL_NUMBERS
		WHERE inventory_item_id = rsl.item_id
		AND current_organization_id = rsl.to_organization_id
		AND serial_number = mut.serial_number
		AND lot_number = mtln.lot_number
		AND current_status = 7)
	AND NOT EXISTS ( SELECT 1
		FROM RCV_SERIALS_SUPPLY
		WHERE serial_num = mut.serial_number
		AND shipment_line_id = rsl.shipment_line_id)
	AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
	AND rsl.SHIPMENT_HEADER_ID = rsh.SHIPMENT_HEADER_ID',
      p_title                  => 'IOT Shipments With Missing Serials Supply',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are IOT shipments with missing serials supply in RCV_SERIALS_SUPPLY table. <br>
So user will not be able to receive the IOT Shipments with Serial Numbers.',
      p_solution               => 'Run the datafix to insert missing serials supply in RCV_SERIALS_SUPPLY table. <br>
Review datafix present in [1060010/KB482143] No Serial Number available for Internal Requisition / Inter Org Transfer, Missing RCV_SERIALS_SUPPLY RSS Records FRM-40212 Invalid FM_SERIAL_NUMBER . <br>
This document has detailed diagnosis and includes a datafix "insert_rss_generic.sql" to insert missing serial numbers. <br>',
      p_success_msg            => 'There are no shipments with missing serials supply in RCV_SERIALS_SUPPLY table.<br>
Refer to [1060010/KB482143] for more details.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_MISSING_SERIALS_SUPPLY_IOT');



debug('begin add_signature: PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14150',
      p_sig_id                 => 'PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_IOT',
      p_sig_sql                => 'SELECT rsh.receipt_num,
rsh.ship_to_org_id,
COUNT(rsh.receipt_num)
FROM rcv_shipment_headers rsh
WHERE rsh.receipt_num IS NOT NULL
and exists (select 1 
              from rcv_shipment_headers rsh1 
             where rsh1.shipment_num = ''##$$IOTNUM$$##''
               AND rsh1.ship_to_org_id = ##$$IOTORGID$$##
               and rsh.receipt_num = rsh1.receipt_num)
GROUP BY rsh.receipt_num,
rsh.ship_to_org_id
HAVING COUNT(rsh.receipt_num) > 1
order by rsh.ship_to_org_id',
      p_title                  => 'Duplicate Receipts With Same Receipt Number In RCV_SHIPMENT_HEADERS Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are multiple receipts with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
      p_solution               => 'Run the datafix to eliminate duplicate receipt numbers in RCV_SHIPMENT_HEADERS table. <br>
Review datafix for Duplicate Receipt Numbers Exist in RCV_SHIPMENT_HEADERS Table For Same Receipt Org ( Same Receipt_Num , Different Shipment_Header_id With Same Ship_To_Org_Id) [1464290/KB446365]. <br>',
      p_success_msg            => 'No two receipts exist with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_IOT');



debug('begin add_signature: PORCVANLAZ_PENDING_INTR_SHPMT_RTI_IOT1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14064',
      p_sig_id                 => 'PORCVANLAZ_PENDING_INTR_SHPMT_RTI_IOT1',
      p_sig_sql                => 'SELECT rti.shipment_num, rti.interface_transaction_id, rti.group_id, rti.transaction_type,rti.processing_mode_code, rti.processing_status_code, rti.transaction_status_code, rti.source_document_code
FROM RCV_TRANSACTIONS_INTERFACE rti
WHERE rti.transaction_type = ''SHIP''
AND rti.processing_mode_code = ''ONLINE''
AND rti.processing_status_code IN (''PENDING'', ''RUNNING'')
AND rti.transaction_status_code = ''PENDING''
AND rti.inv_transaction_id IS NOT NULL
AND rti.source_document_code = ''INVENTORY''
AND rti.shipment_num = ''##$$IOTNUM$$##''
and rti.to_organization_id = ##$$IOTORGID$$##
AND EXISTS
(SELECT 1
FROM MTL_MATERIAL_TRANSACTIONS mmt
WHERE mmt.transaction_id = rti.inv_transaction_id
)
AND NOT EXISTS
(SELECT 1
FROM RCV_SHIPMENT_LINES rsl
WHERE rsl.mmt_transaction_id = rti.inv_transaction_id
)
UNION
SELECT rti.shipment_num, rti.interface_transaction_id, rti.group_id, rti.transaction_type,rti.processing_mode_code, rti.processing_status_code, rti.transaction_status_code, rti.source_document_code
FROM RCV_TRANSACTIONS_INTERFACE rti
WHERE processing_status_code = ''RUNNING''
AND processing_mode_code = ''ONLINE''
AND transaction_status_code = ''PENDING''
AND transaction_type = ''SHIP''
AND source_document_code = ''INVENTORY''
AND rti.shipment_num = ''##$$IOTNUM$$##''
and rti.to_organization_id = ##$$IOTORGID$$##
AND NOT EXISTS
(SELECT 1
FROM MTL_MATERIAL_TRANSACTIONS mmt
WHERE rti.inv_transaction_id = mmt.transaction_id
)',
      p_title                  => 'Pending Inter Organization Intransit Shipments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are pending receiving interface records for inter organization transfer intransit shipments.<br>',
      p_solution               => 'Reprocess the pending intransit shipment records. <br>
Review datafix to Resubmit pending and remove orphan RTI of ISO/IOT [2641413/KB603623].<br>',
      p_success_msg            => 'There are no pending receiving interface records for inter organization transfer intransit shipments.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_PENDING_INTR_SHPMT_RTI_IOT1');



debug('begin add_signature: PORCVANLAZ_UNORD_TXNTYPE_EXIST_FOR_INTR_SHPMTS_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14109',
      p_sig_id                 => 'PORCVANLAZ_UNORD_TXNTYPE_EXIST_FOR_INTR_SHPMTS_IOT',
      p_sig_sql                => 'SELECT rsh.shipment_num,
rsh.shipment_header_id,
rt.transaction_id, 
rt.transaction_type, 
rsl.item_id,
rt.quantity as rt_quantity,
rt.unit_of_measure as rt_uom,
rt.shipment_line_id,
rsl.quantity_shipped,
rsl.quantity_received
FROM RCV_TRANSACTIONS RT ,
RCV_SHIPMENT_HEADERS rsh,
RCV_SHIPMENT_LINES rsl
WHERE rt.transaction_type =''UNORDERED''
AND rsl.source_document_code =''INVENTORY''
AND rsh.shipment_header_id = rsl.shipment_header_id
and rsh.shipment_header_id = rt.shipment_header_id
AND rsl.shipment_line_id = rt.shipment_line_id
AND rsh.ship_to_org_id = rsl.to_organization_id
AND rsh.organization_id = rsl.from_organization_id
AND RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$##
AND EXISTS (SELECT ''1''
FROM MTL_SUPPLY ms
WHERE ms.supply_type_code = ''SHIPMENT''
AND ms.supply_source_id = rsl.shipment_line_id
AND ms.po_line_location_id IS null)',
      p_title                  => 'Unordered Receipt Transactions Exist For Org Transfer Shipments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are unordered receipt transactions existing for Org Transfer shipments.<br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
