debug('begin add_signature: PORCVANLAZ_NULL_EMPLOYEE_ID_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14133',
      p_sig_id                 => 'PORCVANLAZ_NULL_EMPLOYEE_ID_IOT',
      p_sig_sql                => 'select RSH.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_HEADERS'' "Level" 
from RCV_SHIPMENT_HEADERS RSH
WHERE RSH.RECEIPT_SOURCE_CODE IN (''INVENTORY'', ''INTERNAL ORDER'')
AND RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$## 
AND RSH.employee_id is null
and RSH.created_by is not null
union
select RSL.shipment_header_id, ''Employee_id is NULL in RCV_SHIPMENT_LINES'' "Level" 
from RCV_SHIPMENT_LINES RSL,
RCV_SHIPMENT_HEADERS RSH 
where RSL.employee_id is null
and RSL.created_by is not null
AND RSH.RECEIPT_SOURCE_CODE = ''INVENTORY''
AND RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$## 
AND RSH.SHIPMENT_HEADER_ID = RSL.SHIPMENT_HEADER_ID
union
select RT.shipment_header_id, ''Employee_id is NULL in RCV_TRANSACTIONS'' "Level" 
from RCV_TRANSACTIONS RT,
RCV_SHIPMENT_HEADERS RSH 
where RT.employee_id is null
and RT.created_by is not null
and RSH.SHIPMENT_NUM = ''##$$IOTNUM$$##''
AND RSH.SHIP_TO_ORG_ID = ##$$IOTORGID$$## 
AND RT.SHIPMENT_HEADER_ID = RSH.SHIPMENT_HEADER_ID',
      p_title                  => 'Receipts With Null EMPLOYEE_ID',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with null EMPLOYEE_ID in receiving tables. <br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
      p_solution               => 'Run the datafix to update EMPLOYEE_ID for all the problematic rows in receiving tables. <br>
Review datafix for RCVRCVRC: Receiver Is Null On Some Transactions [579554/KB619161]. <br>',
      p_success_msg            => 'There are no receipts with null EMPLOYEE_ID in receiving tables. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_NULL_EMPLOYEE_ID_IOT');



