      p_sig_repo_id            => '14106',
      p_sig_id                 => 'PORCVANLAZ_MISSING_INTORG_INTR_RECEIPT',
      p_sig_sql                => 'SELECT rsh.shipment_num,
       rt.shipment_header_id,
       rt.shipment_line_id,
       rt.transaction_id,
       rsl.mmt_transaction_id
FROM RCV_TRANSACTIONS rt ,
  RCV_SHIPMENT_LINES rsl ,
