  FROM MTL_MATERIAL_TRANSACTIONS
  WHERE rcv_transaction_id       = rt.transaction_id
  AND transaction_source_type_id = 13
  )
AND NOT EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS_TEMP
  WHERE rcv_transaction_id       = rt.transaction_id
  AND transaction_source_type_id = 13
  )',
