      p_sig_sql                => 'SELECT RSS.SUPPLY_TYPE_CODE,RSS.SERIAL_NUM,RSS.SHIPMENT_LINE_ID,RSH.SHIPMENT_NUM,rsh.SHIPMENT_HEADER_ID,RSS.TRANSACTION_ID,RSS.LOT_NUM
 FROM   RCV_SHIPMENT_LINES RSL,
        RCV_SHIPMENT_HEADERS RSH,
        RCV_SERIALS_SUPPLY RSS
 WHERE  RSL.SHIPMENT_LINE_ID = RSS.SHIPMENT_LINE_ID
 AND RSH.SHIPMENT_HEADER_ID = RSL.SHIPMENT_HEADER_ID
 AND RSL.SOURCE_DOCUMENT_CODE =''INVENTORY''
 AND rsh.SHIPMENT_HEADER_ID = ##$$HEADID$$##
 AND RSS.SUPPLY_TYPE_CODE = ''SHIPMENT''
 AND    NOT EXISTS (SELECT 1
                    FROM   MTL_SUPPLY MS
                    WHERE  MS.SHIPMENT_LINE_ID = RSL.SHIPMENT_LINE_ID
		    AND    MS.SHIPMENT_HEADER_ID = ##$$HEADID$$##)
 AND    NOT EXISTS (SELECT 1
                    FROM   RCV_SUPPLY RS
                    WHERE  RS.SHIPMENT_LINE_ID = RSL.SHIPMENT_LINE_ID
		    AND    RS.SHIPMENT_HEADER_ID = ##$$HEADID$$##)                   
 AND    NOT EXISTS (SELECT 1
                    FROM   MTL_SERIAL_NUMBERS MSN
                    WHERE  MSN.INVENTORY_ITEM_ID       = RSL.ITEM_ID 
                    AND    MSN.CURRENT_ORGANIZATION_ID = RSL.FROM_ORGANIZATION_ID 
                    AND    MSN.SERIAL_NUMBER           = RSS.SERIAL_NUM 
                    AND    MSN.CURRENT_STATUS          = 5)',
      p_title                  => 'IOT Shipments With Unwanted Serials Supply',
