debug('begin add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14606',
      p_sig_id                 => 'PORCVANLAZ_UNWANTED_MTL_SUPPLY_IOT',
      p_sig_sql                => 'select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms
where  quantity < 0
and    ms.shipment_header_id = ##$$HEADID$$##
and    ms.to_organization_id = ##$$IOTORGID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms,
       RCV_SHIPMENT_LINES rsl
where  ms.shipment_line_id = rsl.shipment_line_id
and    rsl.shipment_line_status_code = ''CANCELLED''
and    ms.shipment_header_id = ##$$HEADID$$##
and    ms.to_organization_id = ##$$IOTORGID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms
where  ms.shipment_line_id is not null
and    not exists (select 1
                   from   RCV_SHIPMENT_LINES rsl
                   where  rsl.shipment_line_id = ms.shipment_line_id
				   and    rsl.shipment_header_id = ##$$HEADID$$##
				   and    rsl.to_organization_id = ##$$IOTORGID$$##)
and    ms.shipment_header_id = ##$$HEADID$$##
and    ms.to_organization_id = ##$$IOTORGID$$##',
      p_title                  => 'IOT Shipments With Unwanted MTL_SUPPLY',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are IOT shipments with unwanted records in MTL_SUPPLY table. <br>
',
      p_solution               => 'Run the datafix to clear unwanted records from MTL_SUPPLY table. <br>
For datafix, refer to  [1321193/KB742361] Datafix to Remove Unwanted Supply From Supply Tables <br>',
      p_success_msg            => 'There are no shipments with unwanted records in MTL_SUPPLY table. No action required.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_IOT');



debug('begin add_signature: PORCVANLAZ_ORPHAN_PENDING_RTI_DATA_IOT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14639',
      p_sig_id                 => 'PORCVANLAZ_ORPHAN_PENDING_RTI_DATA_IOT',
      p_sig_sql                => 'select RTI.SHIPMENT_NUM,
  RTI.HEADER_INTERFACE_ID,
  RTI.INTERFACE_TRANSACTION_ID,
  RTI.GROUP_ID,
  RTI.TRANSACTION_TYPE,
  RTI.TRANSACTION_DATE,
  RTI.PROCESSING_STATUS_CODE,
  RTI.PROCESSING_MODE_CODE,
  RTI.TRANSACTION_STATUS_CODE,
  RTI.ITEM_ID,
  RTI.QUANTITY,
  RTI.UNIT_OF_MEASURE,
  RTI.AUTO_TRANSACT_CODE,
  RTI.INTERFACE_SOURCE_CODE,
  RTI.INV_TRANSACTION_ID,
  RTI.SHIPMENT_HEADER_ID,
  RTI.SHIPMENT_LINE_ID,
  RTI.SOURCE_DOCUMENT_CODE,
  RTI.TO_ORGANIZATION_ID,
  RTI.REQUISITION_LINE_ID,
  RTI.REQ_DISTRIBUTION_ID,
  RTI.DESTINATION_TYPE_CODE,
  RTI.LPN_ID,
  RTI.TRANSFER_LPN_ID
FROM RCV_TRANSACTIONS_INTERFACE rti
WHERE (EXISTS
  (SELECT 1
  FROM RCV_HEADERS_INTERFACE RHI
  WHERE RTI.HEADER_INTERFACE_ID = RHI.HEADER_INTERFACE_ID
  AND (RHI.SHIPMENT_NUM         = ''##$$IOTNUM$$##''
  OR EXISTS
    (SELECT 1
    FROM RCV_SHIPMENT_HEADERS RSH
    WHERE RSH.SHIPMENT_HEADER_ID = ##$$HEADID$$##
    AND RSH.RECEIPT_SOURCE_CODE  = ''INVENTORY''
    AND RHI.RECEIPT_HEADER_ID    = RSH.SHIPMENT_HEADER_ID
    ) )
  )
OR EXISTS
  (SELECT 2
  FROM RCV_SHIPMENT_HEADERS RSH
  WHERE RSH.SHIPMENT_HEADER_ID = ##$$HEADID$$##
  AND RSH.RECEIPT_SOURCE_CODE  = ''INVENTORY''
  AND (RTI.SHIPMENT_HEADER_ID  = RSH.SHIPMENT_HEADER_ID
  OR RTI.SHIPMENT_NUM          = NVL(''##$$IOTNUM$$##'' ,RSH.SHIPMENT_NUM) )
  ) )
AND RTI.TRANSACTION_TYPE        = ''SHIP''
AND RTI.PROCESSING_MODE_CODE    = ''ONLINE''
AND RTI.PROCESSING_STATUS_CODE IN (''PENDING'', ''RUNNING'')
AND RTI.TRANSACTION_STATUS_CODE = ''PENDING''
AND RTI.INV_TRANSACTION_ID     IS NOT NULL
AND SOURCE_DOCUMENT_CODE        =''INVENTORY''
AND EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS MMT
  WHERE MMT.TRANSACTION_ID = RTI.INV_TRANSACTION_ID
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES RSL
  WHERE RSL.MMT_TRANSACTION_ID = RTI.INV_TRANSACTION_ID
  AND RSL.SHIPMENT_HEADER_ID   = ##$$HEADID$$##
  )
UNION ALL
SELECT RTI.SHIPMENT_NUM,
  RTI.HEADER_INTERFACE_ID,
  RTI.INTERFACE_TRANSACTION_ID,
  RTI.GROUP_ID,
  RTI.TRANSACTION_TYPE,
  RTI.TRANSACTION_DATE,
  RTI.PROCESSING_STATUS_CODE,
  RTI.PROCESSING_MODE_CODE,
  RTI.TRANSACTION_STATUS_CODE,
  RTI.ITEM_ID,
  RTI.QUANTITY,
  RTI.UNIT_OF_MEASURE,
  RTI.AUTO_TRANSACT_CODE,
  RTI.INTERFACE_SOURCE_CODE,
  RTI.INV_TRANSACTION_ID,
  RTI.SHIPMENT_HEADER_ID,
  RTI.SHIPMENT_LINE_ID,
  RTI.SOURCE_DOCUMENT_CODE,
  RTI.TO_ORGANIZATION_ID,
  RTI.REQUISITION_LINE_ID,
  RTI.REQ_DISTRIBUTION_ID,
  RTI.DESTINATION_TYPE_CODE,
  RTI.LPN_ID,
  RTI.TRANSFER_LPN_ID
FROM RCV_TRANSACTIONS_INTERFACE RTI
WHERE (EXISTS
  (SELECT 1
  FROM RCV_HEADERS_INTERFACE RHI
  WHERE RTI.HEADER_INTERFACE_ID = RHI.HEADER_INTERFACE_ID
  AND (RHI.SHIPMENT_NUM         = ''##$$IOTNUM$$##''
  OR EXISTS
    (SELECT 1
    FROM RCV_SHIPMENT_HEADERS RSH
    WHERE RSH.Shipment_header_id = ##$$HEADID$$##
    AND RSH.RECEIPT_SOURCE_CODE  = ''INVENTORY''
    AND RHI.RECEIPT_HEADER_ID    = RSH.SHIPMENT_HEADER_ID
    ) )
  )
OR EXISTS
  (SELECT 2
  FROM RCV_SHIPMENT_HEADERS RSH
  where RSH.SHIPMENT_HEADER_ID = ##$$HEADID$$##
  AND RSH.RECEIPT_SOURCE_CODE  = ''INVENTORY''
  AND ( RTI.SHIPMENT_HEADER_ID = RSH.SHIPMENT_HEADER_ID
  OR RTI.SHIPMENT_NUM          = NVL(''##$$IOTNUM$$##'' ,RSH.SHIPMENT_NUM) )
  ) )
AND PROCESSING_STATUS_CODE  = ''RUNNING''
AND PROCESSING_MODE_CODE    = ''ONLINE''
AND TRANSACTION_STATUS_CODE = ''PENDING''
AND TRANSACTION_TYPE        = ''SHIP''
AND SOURCE_DOCUMENT_CODE    = ''INVENTORY''
AND NOT EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS MMT
  WHERE RTI.INV_TRANSACTION_ID = MMT.TRANSACTION_ID
  )',
      p_title                  => 'Pending and Orphan IOT Shipments in RCV_TRANSACTIONS_INTERFACE',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are pending or orphan IOT shipments in RCV_TRANSACTIONS_INTERFACE(RTI).',
      p_solution               => 'Run the datafix to resubmit pending IOT shipments and delete orphan IOT shipments of RCV_TRANSACTIONS_INTERFACE. <br>
For datafix, refer to [2641413/KB603623] Resubmit pending And Remove Orphan RTI Of ISO/IOT. <br>
',
      p_success_msg            => 'There are no pending and orphan IOT shipments in RCV_TRANSACTIONS_INTERFACE table.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_ORPHAN_PENDING_RTI_DATA_IOT');



