debug('begin add_signature: PORCANLZ_ORPHAN_RSH_RMA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11526',
      p_sig_id                 => 'PORCANLZ_ORPHAN_RSH_RMA',
      p_sig_sql                => 'SELECT SHIPMENT_HEADER_ID SHIPMENT_HEADER_ID,
  RECEIPT_NUM,
  SHIPMENT_NUM,
  RECEIPT_SOURCE_CODE,
  SHIP_TO_ORG_ID
FROM RCV_SHIPMENT_HEADERS rsh
WHERE rsh.receipt_source_code = ''CUSTOMER''
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS rt
  WHERE rt.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS_INTERFACE rti
  WHERE rti.shipment_header_id     = rsh.shipment_header_id
  AND (rti.processing_status_code IN (''RUNNING'',''PENDING'')
  OR NVL(rti.validation_flag,''N'')  = ''N'' )
  )
AND ROWNUM <=1
ORDER BY shipment_header_id',
      p_title                  => 'Orphan Receiving Shipment Headers for RMA documents',
      p_fail_condition         => '[SHIPMENT_HEADER_ID] = [##$$HEADID$$##]',
      p_problem_descr          => 'Orphan shipment headers exist in RCV_SHIPMENT_HEADERS table.<br>
There may be more number of records than the ones fetched. We are displaying only one or two records here for your reference.<br>
They will not cause any issue but can be removed.
<BR>This is a general check. This is not specific to the analyzer parameters.',
      p_solution               => 'Remove the orphaned records.<Br>
Review Datafix for Orphan Receipt or Shipment Headers (RCV_SHIPMENT_HEADERS) [977477/KB157568].',
      p_success_msg            => 'No orphan receiving shipment header records exist in RCV_SHIPMENT_HEADERS table for SHIPMENT_HEADER_ID ['||mask_text(g_header_id, nvl( upper(''), 'NO_MASK') )||'].',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '20'
      );
   l_info.delete;
debug('end add_signature: PORCANLZ_ORPHAN_RSH_RMA');



