debug('begin add_signature: PORCVANLAZ_CORRUPT_RMA_LINE_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14044',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_RMA_LINE_ID',
      p_sig_sql                => 'SELECT  oeh.order_number RMA_NUMBER,    
	      rsh.receipt_num,
	      oel_parent.line_id parent_line,
	      oel_parent.ordered_quantity parent_quantity,
	      oel_child.line_id  child_line,
	      oel_child.ordered_quantity  child_quantity,
	      rsl.shipment_line_id
FROM    OE_ORDER_HEADERS_ALL oeh,
	      OE_ORDER_LINES_ALL   oel_parent,
	      OE_ORDER_LINES_ALL   oel_child,        
	      RCV_SHIPMENT_LINES   rsl,
	      MTL_UNITS_OF_MEASURE uom,
	      RCV_SHIPMENT_HEADERS rsh
WHERE   oeh.header_id = oel_parent.header_id
AND     oeh.header_id = ##$$HEADID$$##
AND     oel_parent.header_id = oel_child.header_id
AND     oel_child.split_from_line_id IS NOT NULL
AND     oel_parent.line_id = oel_child.split_from_line_id
AND     oel_parent.line_category_code = oel_child.line_category_code
AND     oel_parent.line_category_code = ''RETURN''
AND     nvl(oel_child.fulfilled_quantity,0) = 0
AND     oel_child.order_quantity_uom = uom.uom_code
AND     oel_child.split_from_line_id = rsl.oe_order_line_id
AND     oel_child.ordered_quantity = rsl.quantity_shipped
AND     uom.unit_of_measure = rsl.unit_of_measure
AND     rsl.shipment_line_status_code = ''FULLY RECEIVED''
AND     NOT EXISTS (SELECT 1 FROM RCV_TRANSACTIONS rt 
                    WHERE  rt.shipment_line_id = rsl.shipment_line_id
                    AND    rt.transaction_type = ''DELIVER'')
AND     rsl.shipment_header_id = rsh.shipment_header_id',
      p_title                  => 'Corrupt OE_ORDER_LINE_ID in Receiving Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are receipts with corrupt OE_ORDER_LINE_ID in Receiving tables. <br>',
      p_solution               => 'Run the datafix to correct OE_ORDER_LINE_ID in Receiving tables. <br>
Review datafix for Corrupt OE_ORDER_LINE_ID In Receiving Tables [2639378/KB456972]. <br>

',
      p_success_msg            => 'There are no receipts with corrupt OE_ORDER_LINE_ID in Receiving tables.<br>
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_CORRUPT_RMA_LINE_ID');



debug('begin add_signature: PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_RMA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14152',
      p_sig_id                 => 'PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_RMA',
      p_sig_sql                => 'SELECT rsh.receipt_num,
rsh.ship_to_org_id,
COUNT(rsh.receipt_num)
FROM rcv_shipment_headers rsh
WHERE rsh.receipt_num IS NOT NULL
and exists (select 1 
              from rcv_shipment_lines rsl, rcv_shipment_headers rsh1, OE_ORDER_HEADERS_ALL SOH , OE_ORDER_LINES_ALL SOL
             WHERE SOH.ORDER_NUMBER = ''##$$RMANUM$$##''
               AND rsl.OE_ORDER_HEADER_ID = SOH.HEADER_ID
               AND rsl.OE_ORDER_LINE_ID = SOL.LINE_ID
               AND SOL.HEADER_ID = SOH.HEADER_ID
               AND SOL.LINE_CATEGORY_CODE = ''RETURN''
               AND SOH.ORG_ID = ##$$ORGID$$##
               AND rsh1.shipment_header_id = rsl.shipment_header_id
               and rsh.receipt_num = rsh1.receipt_num)
GROUP BY rsh.receipt_num,
rsh.ship_to_org_id
HAVING COUNT(rsh.receipt_num) > 1
order by rsh.ship_to_org_id',
      p_title                  => 'Duplicate Receipts With Same Receipt Number In RCV_SHIPMENT_HEADERS Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are multiple receipts with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
