      p_success_msg            => 'No two receipts exist with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_RMA');



