debug('begin add_signature: PORCVANLAZ_CORRUPT_SHID_RMA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14147',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_SHID_RMA',
      p_sig_sql                => 'SELECT distinct rsh1.shipment_num,rsh1.shipment_header_id, rsh2.shipment_header_id
FROM rcv_shipment_headers rsh1,rcv_shipment_headers rsh2,
rcv_shipment_lines rsl , oe_order_headers_all soh , oe_order_lines_all sol
WHERE soh.order_number = ''##$$RMANUM$$##''
AND rsl.oe_order_header_id = soh.header_id
AND rsl.oe_order_line_id = sol.line_id
AND sol.header_id = soh.header_id
AND sol.line_category_code = ''RETURN''
AND rsh1.shipment_header_id = rsl.shipment_header_id
AND soh.org_id = ##$$ORGID$$##
AND rsh1.receipt_source_code = rsh2.receipt_source_code
AND rsh1.ship_to_org_id = rsh2.ship_to_org_id
AND rsh1.shipment_num = rsh2.shipment_num
AND rsh1.shipment_header_id <> rsh2.shipment_header_id
UNION
SELECT distinct rsh.shipment_num,rsl.shipment_header_id, rt.shipment_header_id
FROM RCV_TRANSACTIONS rt,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh , oe_order_headers_all soh , oe_order_lines_all sol
WHERE rt.shipment_line_id = rsl.shipment_line_id
AND rsl.shipment_header_id = rsh.shipment_header_id
AND rsl.shipment_line_status_code IN (''FULLY RECEIVED'', ''PARTIALLY RECEIVED'')
AND soh.order_number = ''##$$RMANUM$$##''
AND rsl.oe_order_header_id = soh.header_id
AND rsl.oe_order_line_id = sol.line_id
AND sol.header_id = soh.header_id
AND sol.line_category_code = ''RETURN''
AND soh.org_id = ##$$ORGID$$##
AND rt.shipment_header_id <> rsl.shipment_header_id
AND NOT EXISTS (select 1
from RCV_SHIPMENT_HEADERS rtrsh
where rtrsh.shipment_header_id = rt.shipment_header_id
and rtrsh.receipt_source_code = rsh.receipt_source_code
and rtrsh.ship_to_org_id = rsh.ship_to_org_id)
UNION
SELECT distinct rsh.shipment_num,rsh.shipment_header_id, rsl.shipment_header_id
FROM RCV_SHIPMENT_HEADERS rsh,
RCV_SHIPMENT_LINES rsl, oe_order_headers_all soh , oe_order_lines_all sol
WHERE rsl.shipment_header_id = rsh.shipment_header_id
AND rsh.receipt_source_code <> decode (rsl.source_document_code,''RMA'',''CUSTOMER'')
AND soh.order_number = ''##$$RMANUM$$##''
AND rsl.oe_order_header_id = soh.header_id
AND rsl.oe_order_line_id = sol.line_id
AND sol.header_id = soh.header_id
AND sol.line_category_code = ''RETURN''
AND soh.org_id = ##$$ORGID$$##',
      p_title                  => 'Corrupt SHIPMENT_HEADER_ID In RCV_SHIPMENT_HEADERS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are shipment headers with corrupt SHIPMENT_HEADER_ID in RCV_SHIPMENT_HEADERS table. <br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
      p_solution               => 'Review RCVTXERT APP-PO-14094 FRM-40212 Receipt Record Cannot be Found RCVRCVRC / Duplicate Shipment Number RCVTXERT / Multiple Receipt For Intransit Shipment Gives Corrupted Shipment_Header_ID [1198144/KB486431]. <br>
If the issue is different from the above provided solution, refer to [1595825/KB323268], [2366712/KB784630] and [973613/KB438739].<br>
',
      p_success_msg            => 'There are no shipment headers with corrupt SHIPMENT_HEADER_ID in RCV_SHIPMENT_HEADERS table. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_CORRUPT_SHID_RMA');



debug('begin add_signature: PORCVANLAZ_UNWANTED_RCV_SUPPLY_RMA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14617',
      p_sig_id                 => 'PORCVANLAZ_UNWANTED_RCV_SUPPLY_RMA',
      p_sig_sql                => 'SELECT rs.supply_type_code ,
  rs.supply_source_id ,
  rs.shipment_header_id ,
  rs.shipment_line_id ,
  rs.item_id ,
  rs.quantity ,
  rs.unit_of_measure ,
  rs.destination_type_Code ,
  rs.oe_order_header_id ,
  rs.oe_order_line_id ,
  rs.lpn_id
FROM RCV_SUPPLY rs
WHERE quantity            <0
AND rs.oe_order_header_id = ##$$HEADID$$##
UNION
SELECT rs.supply_type_code ,
  rs.supply_source_id ,
  rs.shipment_header_id ,
  rs.shipment_line_id ,
  rs.item_id ,
  rs.quantity ,
  rs.unit_of_measure ,
  rs.destination_type_Code ,
  rs.oe_order_header_id ,
  rs.oe_order_line_id ,
  rs.lpn_id
FROM RCV_SUPPLY rs,
  OE_ORDER_LINES_ALL oel
WHERE rs.oe_order_line_id   = oel.line_id
AND NVL(oel.open_flag, ''N'') = ''N''
AND rs.oe_order_header_id   = ##$$HEADID$$##',
      p_title                  => 'RMA Receipts With Unwanted RCV_SUPPLY',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are RMA receipts with unwanted supply in RCV_SUPPLY table. <br>
',
