debug('begin add_signature: EBS_MFG_INV_PORCVANL_RMA_RESTRICT_OE_SERIAL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29378',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_RMA_RESTRICT_OE_SERIAL',
      p_sig_sql                => 'SELECT SOH.ORDER_NUMBER, SOL.LINE_NUMBER, RP.ORGANIZATION_ID, RP.ENFORCE_RMA_SERIAL_NUM, SOL.INVENTORY_ITEM_ID, MSI.SERIAL_NUMBER_CONTROL_CODE
 FROM    RCV_PARAMETERS RP, OE_ORDER_HEADERS_ALL SOH , OE_ORDER_LINES_ALL SOL, MTL_SYSTEM_ITEMS_B MSI
 WHERE SOH.ORDER_NUMBER = ''##$$RMANUM$$##''
 AND SOH.ORG_ID = ##$$ORGID$$##
 AND SOH.HEADER_ID = SOL.HEADER_ID
 AND SOL.SHIP_FROM_ORG_ID = RP.ORGANIZATION_ID
 AND RP.ENFORCE_RMA_SERIAL_NUM = ''Y''
 AND MSI.INVENTORY_ITEM_ID = SOL.INVENTORY_ITEM_ID
 AND MSI.ORGANIZATION_ID = SOL.SHIP_FROM_ORG_ID
 AND SOL.LINE_CATEGORY_CODE = ''RETURN''
 AND MSI.SERIAL_NUMBER_CONTROL_CODE IN (2, 5) 
 AND not exists (select 1 from OE_LOT_SERIAL_NUMBERS OLSN where OLSN.LINE_ID =SOL.LINE_ID)',
      p_title                  => 'Restrict Serials Missing OE Serial Record',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This is an RMA order for a serialized item created without related serials in order management (in  OE_LOT_SERIAL_NUMBERS table) while the receiving parameters are set to restrict serials. As a result, it is not possible to select the serial(s) while receiving the RMA.',
      p_solution               => 'To receive the serial(s), either add the serial numbers on the order line or disable the serial restriction in receiving parameters. 
<Br>
Review Serial Number Not Accepted For Return Sales Order: Serial Not in Receipt List of Values (LOV) / OE_LOT_SERIAL_NUMBER [2417763/KB420708]',
      p_success_msg            => 'No exceptions were found for a serialized item on the RMA where the order management serials are missing and the receiving organization is restricting serials. ',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
