      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_RMA_RESTRICT_OE_SERIAL');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_RMA_CLOSED_PERIOD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30922',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_RMA_CLOSED_PERIOD',
      p_sig_sql                => 'SELECT poh.segment1 PO_NUMBER, wdd.source_header_number RETURN_ORDER_NUMBER
, wnd.delivery_id , wnd.initial_pickup_date, wnd.ultimate_dropoff_date
, wdd.delivery_detail_id , wdd.organization_id
, wts.stop_id , wts.actual_departure_date , wts.pending_interface_flag
, rti.interface_transaction_id
, (SELECT decode(oap.open_flag, ''P'',''P - Period Close is processing'' ,''N'',''Closed'' , NULL ,''Open'' ,''Unknown'')
FROM ORG_ACCT_PERIODS oap
WHERE organization_id = wdd.organization_id
AND wts.actual_departure_date between TRUNC(period_start_date)AND TRUNC(schedule_close_date)
) inv_period_status
, ( select DECODE(glp.CLOSING_STATUS,''O'',''Open'', ''C'',''Closed'', ''F'',''Future'', ''N'',''Never'', glp.CLOSING_STATUS)
from hr_operating_units hou, gl_period_statuses glp
where poh.org_id = hou.organization_id
and glp.set_of_books_id = hou.set_of_books_id
and glp.APPLICATION_ID = 201 and wts.actual_departure_date between TRUNC(glp.start_date)AND TRUNC(glp.end_date)) po_period_status
, ( select DECODE(glp.CLOSING_STATUS,''O'',''Open'', ''C'',''Closed'', ''F'',''Future'', ''N'',''Never'', glp.CLOSING_STATUS)
from hr_operating_units hou, gl_period_statuses glp
where poh.org_id = hou.organization_id
and glp.set_of_books_id = hou.set_of_books_id
and glp.APPLICATION_ID = 101 and wts.actual_departure_date between TRUNC(glp.start_date)AND TRUNC(glp.end_date) ) gl_period_status
FROM wsh_delivery_details wdd,
wsh_delivery_assignments wda,
wsh_new_deliveries wnd,
wsh_delivery_legs wdl,
wsh_trip_stops wts,
rcv_transactions_interface rti,
po_Headers_all poh
WHERE wnd.delivery_id = wdl.delivery_id
AND wnd.status_code = ''CL''
AND wdd.organization_id = ##$$ORGID$$## -- (OR) source_header_number = ''&return_order_num''
AND wdd.delivery_detail_id = wda.delivery_detail_id
AND wdd.source_code = ''RTV''
AND wdd.inv_interfaced_flag in (''N'',''P'')
AND wdd.released_status = ''C''
AND wts.pending_interface_flag = ''Y''
AND wda.delivery_id = wnd.delivery_id
AND wdl.pick_up_stop_id = wts.stop_id
AND wnd.initial_pickup_location_id = wts.stop_location_id
AND wdd.source_line_id = rti.interface_transaction_id
AND rti.transaction_type = ''RETURN TO VENDOR''
AND rti.processing_status_code = ''WSH_INTERFACED''
AND poh.po_header_id = rti.po_header_id',
      p_title                  => 'Return Order Shipments Error With No Open Period Found for Transaction Date',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Interface trip stop for Return orders fails with error.<br>
<br>
ERROR:<br>
rvtptcontrol failed ',
      p_solution               => 'See [3059630/KB755239] for complete details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_RMA_CLOSED_PERIOD');



