debug('begin add_signature: PORCVANLAZ_RECEIPT_NUM_NULL_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4892',
      p_sig_id                 => 'PORCVANLAZ_RECEIPT_NUM_NULL_IRISO',
      p_sig_sql                => 'SELECT DISTINCT RSH.*
FROM RCV_SHIPMENT_HEADERS RSH ,
  RCV_SHIPMENT_LINES RSL ,
  PO_REQUISITION_HEADERS_ALL PRH ,
  PO_REQUISITION_LINES_ALL PRL
WHERE RSL.SHIPMENT_HEADER_ID  = RSH.SHIPMENT_HEADER_ID
AND PRH.REQUISITION_HEADER_ID = PRL.REQUISITION_HEADER_ID
AND RSL.REQUISITION_LINE_ID   = PRL.REQUISITION_LINE_ID
AND RSH.RECEIPT_SOURCE_CODE   = ''INTERNAL ORDER''
AND RSL.SOURCE_DOCUMENT_CODE  = ''REQ''
AND PRH.SEGMENT1              = ''##$$REQNUM$$##''
AND PRH.ORG_ID                = ##$$ORGID$$##
AND RSH.receipt_num            IS NULL
AND EXISTS
  (SELECT 1
  FROM rcv_transactions rt
  WHERE rt.shipment_header_id = rsh.shipment_header_id
  AND rt.shipment_header_id   = RSH.SHIPMENT_HEADER_ID
  )
AND EXISTS
  (SELECT 1
  FROM rcv_parameters rp
  WHERE rp.organization_id          = rsh.ship_to_org_id
  AND user_defined_receipt_num_code = ''AUTOMATIC''
  )',
      p_title                  => 'Receipt Number is Null',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records with a NULL RECEIPT_NUM in RCV_SHIPMENT_HEADERS table.
',
      p_solution               => 'Download the generic script stamp_receipt_num.sql from <Br>
RCVRCVRC: Receiving Transaction Summary Returns APP-PO-14094 [975312/KB287078] <Br>
This script will update the RCV_SHIPMENT_HEADERS.RECEIPT_NUM with the next available receipt number.',
      p_success_msg            => 'There are no records with NULL receipt numbers.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
