debug('begin add_signature: PORCVANLAZ_MISSING_INTRANSIT_SHIPMENT_DATA_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4893',
      p_sig_id                 => 'PORCVANLAZ_MISSING_INTRANSIT_SHIPMENT_DATA_IRISO',
      p_sig_sql                => 'SELECT TRANSACTION_ID,
  SHIPMENT_NUMBER,
  INVENTORY_ITEM_ID,
  ORGANIZATION_ID,
  TRANSFER_ORGANIZATION_ID,
  SUBINVENTORY_CODE,
  LOCATOR_ID,
  TRANSACTION_TYPE_ID,
  TRANSACTION_ACTION_ID,
  TRANSACTION_SOURCE_TYPE_ID,
  TRANSACTION_SOURCE_ID,
  TRANSACTION_QUANTITY,
  TRANSACTION_UOM,
  PRIMARY_QUANTITY,
  TRANSACTION_DATE,
  PICKING_LINE_ID,
  TRX_SOURCE_LINE_ID,
  TRANSFER_TRANSACTION_ID,
  TRANSACTION_SET_ID,
  RCV_TRANSACTION_ID,
  MOVE_TRANSACTION_ID,
  MOVE_ORDER_LINE_ID,
  LPN_ID,
  TRANSFER_LPN_ID
FROM MTL_MATERIAL_TRANSACTIONS MMT
WHERE ( (TRANSACTION_SOURCE_TYPE_ID = 8
AND TRANSACTION_ACTION_ID           = 21)
OR (TRANSACTION_SOURCE_TYPE_ID      = 8
AND TRANSACTION_ACTION_ID           = 1) )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES RSL,
    RCV_SHIPMENT_HEADERS RSH
  WHERE RSH.SHIPMENT_HEADER_ID = RSL.SHIPMENT_HEADER_ID
  AND RSH.SHIPMENT_NUM         = MMT.SHIPMENT_NUMBER
  AND RSH.RECEIPT_SOURCE_CODE  = ''INTERNAL ORDER''
  AND RSL.MMT_TRANSACTION_ID   = MMT.TRANSACTION_ID
  AND RSL.TO_ORGANIZATION_ID   = MMT.TRANSFER_ORGANIZATION_ID
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS_INTERFACE RTI
  WHERE RTI.INV_TRANSACTION_ID = MMT.TRANSACTION_ID
  )
AND NOT EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS MMT_DELIVER
  WHERE MMT_DELIVER.TRANSFER_TRANSACTION_ID = MMT.TRANSACTION_ID
  )
AND SHIPMENT_NUMBER IN
  ( SELECT DISTINCT MMT.SHIPMENT_NUMBER
  FROM MTL_MATERIAL_TRANSACTIONS MMT,
    PO_REQUISITION_LINES_ALL PRL,
    PO_REQUISITION_HEADERS_ALL PRH,
    OE_ORDER_LINES_ALL SOL,
    OE_ORDER_HEADERS_ALL OEH
  WHERE PRH.REQUISITION_HEADER_ID = PRL.REQUISITION_HEADER_ID
  AND PRH.SEGMENT1 = ''##$$REQNUM$$##''
  AND PRH.ORG_ID = ##$$ORGID$$## 
  AND PRL.SOURCE_TYPE_CODE        = ''INVENTORY''
  AND OEH.ORIG_SYS_DOCUMENT_REF   = PRH.SEGMENT1
  AND OEH.HEADER_ID               = SOL.HEADER_ID
  AND SOL.SOURCE_DOCUMENT_TYPE_ID = 10
  AND SOL.SOURCE_DOCUMENT_LINE_ID = PRL.REQUISITION_LINE_ID
  AND MMT.TRX_SOURCE_LINE_ID      = SOL.LINE_ID
  AND MMT.TRANSACTION_ACTION_ID   =21
  )',
      p_title                  => 'Missing Intransit Shipment data for ISO Shipment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are ISO Shipments with missing intransit shipment data. This will prevent creation of Receipt against the shipment.
<BR>
',
      p_solution               => 'Refer to the note: <Br>
RCVTXERT APP-PO-14094 FRM-40212 Receipt Record Cannot be Found RCVRCVRC / Duplicate Shipment Number RCVTXERT / Multiple Receipt For Intransit Shipment Gives Corrupted Shipment_Header_ID [1198144/KB486431]',
      p_success_msg            => 'There are no ISO Shipments with missing intransit shipment data.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '26'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_MISSING_INTRANSIT_SHIPMENT_DATA_IRISO');



debug('begin add_signature: PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4894',
      p_sig_id                 => 'PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IRISO',
      p_sig_sql                => 'SELECT rsl.shipment_header_id "rsl.shipment_header_id",
  rsl.shipment_line_id "rsl.shipment_line_id",
  rsh.shipment_num "rsh.shipment_num",
  rsl.requisition_line_id "rsl.requisition_line_id",
  rsl.mmt_transaction_id "rsl.mmt_transaction_id"
FROM rcv_shipment_lines rsl,
  rcv_shipment_headers rsh
WHERE rsl.shipment_header_id = rsh.shipment_header_id
AND rsl.mmt_transaction_id  IS NOT NULL
AND rsh.receipt_source_code  = ''INTERNAL ORDER''
AND rsl.requisition_line_id IN
  (SELECT requisition_line_id
  FROM po_requisition_lines_all
  WHERE requisition_header_id = ##$$HEADID$$##
  ) 
 AND EXISTS
    (
     SELECT 1
     FROM mtl_parameters mp
     WHERE mp.organization_id = rsh.organization_id
    )
 AND NOT EXISTS
    (
     SELECT 1
     FROM mtl_material_transactions mmt
     WHERE mmt.transaction_id = rsl.mmt_transaction_id
     AND   mmt.transaction_source_type_id = 8
     AND   mmt.transaction_action_id in (1,3,21,2)
    )
 AND NOT EXISTS
    (
     SELECT 1
     FROM  mtl_material_transactions mmt,
           rcv_transactions rt
     WHERE mmt.rcv_transaction_id = rt.transaction_id
     AND   rt.shipment_line_id = rsl.shipment_line_id
     AND   rt.transaction_type = ''DELIVER''
    )
 ORDER BY 1',
      p_title                  => 'Missing Issue Material Transactions For ISO Shipment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are internal sales order shipments with issue material transactions data. <br>
This will prevent creation of receipt against the shipment.<br>
You may see an error attempting to receive like this: "APP-PO-15576: Shipment source ### for shipment line ### is invalid" where the shipment source is an invalid transaction id (mmt_transaction_id).',
      p_solution               => 'Review and apply the datafix from: <br>
Datafix for missing issue material transactions for intransit shipments [789732/KB468168].',
      p_success_msg            => 'There are no internal sales order shipments with issue material transactions data.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '18'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_MISSING_ISSUE_MATERIAL_TRANSACTIONS_IRISO');



debug('begin add_signature: PORCVANLZ_ORPHAN_RSH_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11542',
      p_sig_id                 => 'PORCVANLZ_ORPHAN_RSH_IRISO',
      p_sig_sql                => 'SELECT SHIPMENT_HEADER_ID SHIPMENT_HEADER_ID,
  RECEIPT_NUM,
  SHIPMENT_NUM,
  RECEIPT_SOURCE_CODE,
  ASN_TYPE,
  SHIP_TO_ORG_ID
FROM RCV_SHIPMENT_HEADERS rsh
WHERE receipt_source_code = ''INTERNAL ORDER''
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS rt
  WHERE rt.shipment_header_id = rsh.shipment_header_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_TRANSACTIONS_INTERFACE rti
  WHERE rti.shipment_header_id     = rsh.shipment_header_id
  AND (rti.processing_status_code IN (''RUNNING'',''PENDING'')
  OR NVL(rti.validation_flag,''N'')  = ''N'' )
  )
AND ROWNUM <=1
ORDER BY shipment_header_id',
      p_title                  => 'Orphan Receiving Shipment Headers for IR/ISO',
      p_fail_condition         => '[SHIPMENT_HEADER_ID] = [##$$HEADID$$##]',
      p_problem_descr          => 'Orphan shipment headers exist in RCV_SHIPMENT_HEADERS table. <br>
There may be more number of records than the ones fetched. We are displaying only one or two records here for your reference.<br>
They will not cause any issue but can be removed.<BR>
This is a general check. This is not specific to the analyzer parameters.',
