debug('begin add_signature: PORCVANLAZ_UNPROC_RTI_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11576',
      p_sig_id                 => 'PORCVANLAZ_UNPROC_RTI_IRISO',
      p_sig_sql                => 'SELECT INTERFACE_TRANSACTION_ID,
GROUP_ID,
RTI.CREATION_DATE,
TRANSACTION_TYPE,
PROCESSING_STATUS_CODE,
PROCESSING_MODE_CODE,
TRANSACTION_STATUS_CODE,
RTI.ITEM_ID,
RTI.QUANTITY,VALIDATION_FLAG, 
MOBILE_TXN, 
LPN_GROUP_ID 
FROM RCV_TRANSACTIONS_INTERFACE RTI ,
PO_REQUISITION_HEADERS_ALL PRH ,
PO_REQUISITION_LINES_ALL PRL
WHERE PROCESSING_MODE_CODE = ''BATCH''
AND PROCESSING_STATUS_CODE = ''PENDING''
AND TRANSACTION_STATUS_CODE = ''PENDING''
AND PRH.SEGMENT1 = ''##$$REQNUM$$##''
AND PRH.ORG_ID = ##$$ORGID$$##
AND PRH.REQUISITION_HEADER_ID = PRL.REQUISITION_HEADER_ID
AND PRL.SOURCE_TYPE_CODE = ''INVENTORY''
AND (PRL.REQUISITION_LINE_ID = NVL(RTI.REQUISITION_LINE_ID,-99)
OR RTI.REQ_NUM IS NOT NULL AND RTI.REQ_NUM = PRH.SEGMENT1)',
      p_title                  => 'Unprocessed Records in Interface - Batch Mode',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are unprocessed records in RCV_TRANSACTIONS_INTERFACE table which could prevent Receiving Transactions.',
      p_solution               => 'For solution, refer to the following note : <Br>
[210188/FAQ4846] - FAQ: Receiving Transaction Processor (RTP)',
      p_success_msg            => 'There are no unprocessed records in RCV_TRANSACTIONS_INTERFACE table. No action required.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNPROC_RTI_IRISO');



debug('begin add_signature: PORCVANLAZ_STUCK_RTI_IRISO');
