FROM rcv_shipment_headers rsh
WHERE rsh.receipt_num IS NOT NULL
and exists (select 1 
              from rcv_shipment_lines rsl, rcv_shipment_headers rsh1,po_requisition_headers_all prh , po_requisition_lines_all prl
             WHERE prh.segment1 = ''##$$REQNUM$$##''
               AND prh.org_id = ##$$ORGID$$##
               AND prh.requisition_header_id = prl.requisition_header_id
               AND rsl.requisition_line_id = prl.requisition_line_id
               AND rsh1.shipment_header_id = rsl.shipment_header_id
               and rsh.receipt_num = rsh1.receipt_num)
GROUP BY rsh.receipt_num,
rsh.ship_to_org_id
HAVING COUNT(rsh.receipt_num) > 1
order by rsh.ship_to_org_id',
      p_title                  => 'Duplicate Receipts With Same Receipt Number In RCV_SHIPMENT_HEADERS Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are multiple receipts with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
      p_solution               => 'Run the datafix to eliminate duplicate receipt numbers in RCV_SHIPMENT_HEADERS table. <br>
Review datafix for Duplicate Receipt Numbers Exist in RCV_SHIPMENT_HEADERS Table For Same Receipt Org ( Same Receipt_Num , Different Shipment_Header_id With Same Ship_To_Org_Id) [1464290/KB446365]. <br>',
      p_success_msg            => 'No two receipts exist with the same receipt number in RCV_SHIPMENT_HEADERS table in a receipt organization. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_DUPLICATE_RECEIPT_NUMS_IRISO');



debug('begin add_signature: PORCVANLAZ_MISSING_SHIPMENT_SUPPLY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14056',
      p_sig_id                 => 'PORCVANLAZ_MISSING_SHIPMENT_SUPPLY',
      p_sig_sql                => 'SELECT rsh.shipment_num "Shipment Number",
       rsl.line_num "Shipment Line Number",
       rsl.from_organization_id,
       rsl.to_organization_id ,
       rsl.shipment_line_id
FROM RCV_SHIPMENT_LINES rsl,
     RCV_SHIPMENT_HEADERS rsh,
     PO_REQUISITION_HEADERS_ALL prh,
     PO_REQUISITION_LINES_ALL prl
WHERE rsh.shipment_header_id      = rsl.shipment_header_id
AND rsl.source_document_code      = ''REQ''
AND rsl.shipment_line_status_code = ''EXPECTED''
AND rsl.quantity_received         = 0
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND prh.requisition_header_id     = prl.requisition_header_id
AND prl.requisition_line_id       = rsl.requisition_line_id
AND prl.source_type_code = ''INVENTORY''
AND NOT EXISTS
  (SELECT 1
  FROM MTL_SUPPLY ms
  WHERE ms.shipment_line_id = rsl.shipment_line_id
  AND ms.supply_type_code   = ''SHIPMENT''
  )',
      p_title                  => 'Missing Intransit Shipment Supply',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are intransit shipments with missing SHIPMENT supply.<br>',
      p_solution               => 'Run the datafix to insert missing SHIPMENT supply. <br>
For datafix for Unable to Receive Against Internal Requisition Though Shipment is Intransit [2554139/KB261005] <br>',
      p_success_msg            => 'There are no intransit shipments with missing SHIPMENT supply.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_MISSING_SHIPMENT_SUPPLY');



debug('begin add_signature: PORCVANLAZ_CORRUPT_REQ_SUPPLY_QTY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14060',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_REQ_SUPPLY_QTY',
      p_sig_sql                => 'SELECT ms.supply_type_code,
  ms.supply_source_id,
  ms.quantity,
  ms.req_header_id,
  ms.req_line_id,
  prl.requisition_header_id,
  prl.requisition_line_id,
  prl.quantity,
  NVL(prl.quantity_received,0) quantity_received,
  prl.quantity_delivered,
  prl.unit_meas_lookup_code,
  prl.closed_code,
  prl.cancel_flag
FROM MTL_SUPPLY ms,
     PO_REQUISITION_LINES_ALL prl
WHERE ms.supply_type_code    = ''REQ''
AND ms.from_organization_id IS NOT NULL
AND ms.to_organization_id   IS NOT NULL
AND ms.req_line_id           = prl.requisition_line_id
AND ms.quantity              = prl.quantity
AND prl.requisition_header_id = ##$$HEADID$$##
AND prl.source_type_code     = ''INVENTORY''
AND (EXISTS
  (SELECT ''1''
  FROM MTL_SUPPLY ms1
  WHERE ms1.supply_type_code = ''SHIPMENT''
  AND ms1.req_line_id        = ms.req_line_id
  )
OR EXISTS
  (SELECT ''1''
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.requisition_line_id = ms.req_line_id
  AND rsl.from_organization_id IS NOT NULL
  AND rsl.to_organization_id   IS NOT NULL
  ))',
      p_title                  => 'Wrong Internal Requisition Supply In MTL_SUPPLY',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records with incorrect requisition supply quantity in MTL_SUPPLY table for internal requisitions.<br>',
      p_solution               => 'Run the datafix to correct the requisition supply quantity in MTL_SUPPLY table. <br>
Review datafix for REQ Supply Remains After Successful Ship Confirm Of Internal Sales Order [2641004/KB530976]. <br>',
      p_success_msg            => 'There are no records with incorrect requisition supply quantity in MTL_SUPPLY table for internal requisitions.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_CORRUPT_REQ_SUPPLY_QTY');



