debug('begin add_signature: PORCVANLAZ_CORRUPT_SHID_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14146',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_SHID_IRISO',
      p_sig_sql                => 'SELECT distinct rsh1.shipment_num,rsh1.shipment_header_id, rsh2.shipment_header_id
FROM rcv_shipment_headers rsh1,rcv_shipment_headers rsh2,
rcv_shipment_lines rsl , po_requisition_headers_all prh , po_requisition_lines_all prl
WHERE rsl.shipment_header_id = rsh1.shipment_header_id
AND prh.requisition_header_id = prl.requisition_header_id
AND rsl.requisition_line_id = prl.requisition_line_id
AND rsh1.receipt_source_code IN (''INTERNAL ORDER'', ''INVENTORY'')
AND rsl.source_document_code = ''REQ''
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND rsh1.receipt_source_code = rsh2.receipt_source_code
AND rsh1.ship_to_org_id = rsh2.ship_to_org_id
AND rsh1.shipment_num = rsh2.shipment_num
AND rsh1.shipment_header_id <> rsh2.shipment_header_id
UNION
SELECT distinct rsh.shipment_num,rsl.shipment_header_id, rt.shipment_header_id
FROM RCV_TRANSACTIONS rt,
RCV_SHIPMENT_LINES rsl,
RCV_SHIPMENT_HEADERS rsh, po_requisition_headers_all prh , po_requisition_lines_all prl
WHERE rt.shipment_line_id = rsl.shipment_line_id
AND rsl.shipment_header_id = rsh.shipment_header_id
AND rsl.shipment_line_status_code IN (''FULLY RECEIVED'', ''PARTIALLY RECEIVED'')
AND rsl.requisition_line_id = prl.requisition_line_id
AND prh.requisition_header_id = prl.requisition_header_id
AND rsh.receipt_source_code IN (''INTERNAL ORDER'', ''INVENTORY'')
AND rsl.source_document_code = ''REQ''
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND rt.shipment_header_id <> rsl.shipment_header_id
UNION
SELECT distinct rsh.shipment_num,rsh.shipment_header_id, rsl.shipment_header_id
FROM RCV_SHIPMENT_HEADERS rsh,
RCV_SHIPMENT_LINES rsl,
MTL_MATERIAL_TRANSACTIONS mmt,
po_requisition_headers_all prh , po_requisition_lines_all prl
WHERE rsh.shipment_header_id = rsl.shipment_header_id
AND rsl.mmt_transaction_id = mmt.transaction_id
AND mmt.organization_id = rsl.from_organization_id
AND mmt.transfer_organization_id = rsl.to_organization_id
AND rsl.requisition_line_id = prl.requisition_line_id
AND prh.requisition_header_id = prl.requisition_header_id
AND rsl.source_document_code = ''REQ''
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND ( rsh.receipt_source_code <> decode (rsl.source_document_code,''INVENTORY'',''INVENTORY'', ''REQ'', ''INTERNAL ORDER'')
or
rsh.ship_to_org_id <> rsl.to_organization_id
or
rsh.organization_id <> rsl.from_organization_id)',
      p_title                  => 'Corrupt SHIPMENT_HEADER_ID In RCV_SHIPMENT_HEADERS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are shipment headers with corrupt SHIPMENT_HEADER_ID in RCV_SHIPMENT_HEADERS table. <br>
There may be more number of records than the ones fetched. Only a few records are displayed here for your reference.<br>',
      p_solution               => 'Review RCVTXERT APP-PO-14094 FRM-40212 Receipt Record Cannot be Found RCVRCVRC / Duplicate Shipment Number RCVTXERT / Multiple Receipt For Intransit Shipment Gives Corrupted Shipment_Header_ID [1198144/KB486431]. <br>
If the issue is different from the above provided solution, refer to [1595825/KB323268], [2366712/KB784630] and [973613/KB438739].<br>
',
      p_success_msg            => 'There are no shipment headers with corrupt SHIPMENT_HEADER_ID in RCV_SHIPMENT_HEADERS table. <br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
