debug('begin add_signature: PORCVANLAZ_PENDING_INTR_SHPMT_RTI_REQ');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14058',
      p_sig_id                 => 'PORCVANLAZ_PENDING_INTR_SHPMT_RTI_REQ',
      p_sig_sql                => 'SELECT rti.shipment_num, rti.interface_transaction_id, rti.group_id, rti.transaction_type,rti.processing_mode_code, rti.processing_status_code, rti.transaction_status_code, rti.source_document_code, rti.shipment_header_id, rti.shipment_line_id
FROM RCV_TRANSACTIONS_INTERFACE rti,
     PO_REQUISITION_HEADERS_ALL prh , 
     PO_REQUISITION_LINES_ALL prl
WHERE rti.transaction_type      = ''SHIP''
AND rti.processing_mode_code    = ''ONLINE''
AND rti.processing_status_code IN (''PENDING'', ''RUNNING'')
AND rti.transaction_status_code = ''PENDING''
AND rti.inv_transaction_id     IS NOT NULL
AND source_document_code        = ''REQ''
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND prh.requisition_header_id = prl.requisition_header_id
AND prl.requisition_line_id  = rti.requisition_line_id
AND EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS mmt
  WHERE mmt.transaction_id = rti.inv_transaction_id
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SHIPMENT_LINES rsl
  WHERE rsl.mmt_transaction_id = rti.inv_transaction_id
  )
AND ROWNUM <=50
UNION
SELECT rti.shipment_num, rti.interface_transaction_id, rti.group_id, rti.transaction_type,rti.processing_mode_code, rti.processing_status_code, rti.transaction_status_code, rti.source_document_code, rti.shipment_header_id, rti.shipment_line_id
FROM RCV_TRANSACTIONS_INTERFACE rti,
     PO_REQUISITION_HEADERS_ALL prh , 
     PO_REQUISITION_LINES_ALL prl
WHERE processing_status_code = ''RUNNING''
AND processing_mode_code     = ''ONLINE''
AND transaction_status_code  = ''PENDING''
AND transaction_type         = ''SHIP''
AND source_document_code        = ''REQ''
AND rti.creation_date            < SYSDATE +1
AND prh.segment1 = ''##$$REQNUM$$##''
AND prh.org_id = ##$$ORGID$$##
AND prh.requisition_header_id = prl.requisition_header_id
AND prl.requisition_line_id  = rti.requisition_line_id
AND NOT EXISTS
  (SELECT 1
  FROM MTL_MATERIAL_TRANSACTIONS mmt
  WHERE rti.inv_transaction_id = mmt.transaction_id
  )
AND ROWNUM <=50',
      p_title                  => 'Internal Requisition Shipments And Receipts Pending In Receiving Interface',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are pending receiving interface records for internal requisition intransit shipments and/or receiving transactions.
<BR>This is a general check. This is not specific to the analyzer parameters.',
      p_solution               => 'Run the datafix to process the stuck internal requisition shipments. <br>
RCVTXERT APP-PO-14094 FRM-40212 Receipt Record Cannot be Found RCVRCVRC / Duplicate Shipment Number RCVTXERT / Multiple Receipt For Intransit Shipment Gives Corrupted Shipment_Header_ID [1198144/KB486431]
',
      p_success_msg            => 'There are no pending receiving interface records for internal requisition intransit shipments and receiving transactions.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_PENDING_INTR_SHPMT_RTI_REQ');



debug('begin add_signature: PORCVANLAZ_UNWANTED_SERIALS_SUPPLY_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14603',
      p_sig_id                 => 'PORCVANLAZ_UNWANTED_SERIALS_SUPPLY_IRISO',
      p_sig_sql                => 'SELECT RSS.SUPPLY_TYPE_CODE,
  RSS.SERIAL_NUM,
  RSS.SHIPMENT_LINE_ID,
  PRH.SEGMENT1 "REQUISITION NUMBER",
  PRH.REQUISITION_HEADER_ID,
  RSL.REQUISITION_LINE_ID,
  RSS.TRANSACTION_ID,
  RSS.LOT_NUM
FROM RCV_SHIPMENT_LINES RSL,
  RCV_SERIALS_SUPPLY RSS,
  PO_REQUISITION_HEADERS_ALL PRH ,
  PO_REQUISITION_LINES_ALL PRL
WHERE RSL.SHIPMENT_LINE_ID    = RSS.SHIPMENT_LINE_ID
AND PRH.REQUISITION_HEADER_ID = PRL.REQUISITION_HEADER_ID
AND RSL.REQUISITION_LINE_ID   = PRL.REQUISITION_LINE_ID
AND RSS.SUPPLY_TYPE_CODE      = ''SHIPMENT''
AND RSL.SOURCE_DOCUMENT_CODE  = ''REQ''
AND PRH.REQUISITION_HEADER_ID = ##$$HEADID$$##
AND NOT EXISTS
  (SELECT 1
  FROM MTL_SUPPLY MS
  WHERE MS.SHIPMENT_LINE_ID = RSL.SHIPMENT_LINE_ID
  AND MS.REQ_HEADER_ID      = ##$$HEADID$$##
  )
AND NOT EXISTS
  (SELECT 1
  FROM RCV_SUPPLY RS
  WHERE RS.SHIPMENT_LINE_ID = RSL.SHIPMENT_LINE_ID
  AND RS.REQ_HEADER_ID      = ##$$HEADID$$##
  )
AND NOT EXISTS
  (SELECT 1
  FROM MTL_SERIAL_NUMBERS MSN
  WHERE MSN.INVENTORY_ITEM_ID     = RSL.ITEM_ID
  AND MSN.CURRENT_ORGANIZATION_ID = RSL.FROM_ORGANIZATION_ID
  AND MSN.SERIAL_NUMBER           = RSS.SERIAL_NUM
  AND MSN.CURRENT_STATUS          = 5
  )',
