debug('begin add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14636',
      p_sig_id                 => 'PORCVANLAZ_UNWANTED_MTL_SUPPLY_IRISO',
      p_sig_sql                => 'select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.req_header_id
	  ,ms.req_line_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms
where  quantity < 0
and    ms.req_header_id = ##$$HEADID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.req_header_id
	  ,ms.req_line_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms,
       RCV_SHIPMENT_LINES rsl
where  ms.shipment_line_id = rsl.shipment_line_id
and    rsl.shipment_line_status_code = ''CANCELLED''
and    ms.req_header_id = ##$$HEADID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.req_header_id
	  ,ms.req_line_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY ms
where  ms.shipment_line_id is not null
and    not exists (select 1
                   from   RCV_SHIPMENT_LINES rsl
                   where  rsl.shipment_line_id = ms.shipment_line_id)
and    ms.req_header_id = ##$$HEADID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.req_header_id
	  ,ms.req_line_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY                 ms,
       PO_REQUISITION_HEADERS_ALL prh
where  ms.req_header_id = prh.requisition_header_id
and    ms.supply_type_code in (''SHIPMENT'', ''RECEIVING'')
and    prh.closed_code = ''FINALLY CLOSED''
and    ms.req_header_id = ##$$HEADID$$##
union
select ms.supply_type_code
      ,ms.supply_source_id
	  ,ms.req_header_id
	  ,ms.req_line_id
	  ,ms.shipment_header_id
	  ,ms.shipment_line_id
	  ,ms.item_id
	  ,ms.quantity
	  ,ms.unit_of_measure
	  ,ms.destination_type_Code
	  ,ms.from_organization_id
	  ,ms.from_subinventory
	  ,ms.to_organization_id
	  ,ms.to_subinventory
	  ,ms.rcv_transaction_id
	  ,ms.to_org_primary_quantity
	  ,ms.to_org_primary_uom
	  ,ms.cost_group_id
from   MTL_SUPPLY                 ms,
       PO_REQUISITION_LINES_ALL   prl
where  ms.req_line_id is not null
and    ms.req_line_id = prl.requisition_line_id
and    ms.supply_type_code in (''REQ'')
and    prl.quantity_received >= prl.quantity
and    prl.quantity_delivered >= prl.quantity
and    ms.req_header_id = ##$$HEADID$$##',
      p_title                  => 'Internal Requisitions With Unwanted MTL_SUPPLY',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are internal requisitions with unwanted supply in MTL_SUPPLY table. <br>
',
      p_solution               => 'Run the datafix to clear unwanted supply in MTL_SUPPLY table. <br>
For datafix, refer to [1321193/KB742361] Datafix to Remove Unwanted Supply From Supply Tables <br>',
      p_success_msg            => 'There are no internal requisitions with unwanted supply in MTL_SUPPLY table.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_UNWANTED_MTL_SUPPLY_IRISO');



