  rti.source_document_code,
  rti.to_organization_id,
  rti.requisition_line_id,
  rti.req_distribution_id,
  rti.destination_type_code,
  rti.lpn_id,
  rti.transfer_lpn_id
FROM RCV_TRANSACTIONS_INTERFACE rti,
  PO_REQUISITION_HEADERS_ALL PRH ,
  PO_REQUISITION_LINES_ALL PRL
WHERE prh.requisition_header_id = ##$$HEADID$$##
AND prh.requisition_header_id   = prl.requisition_header_id
AND prl.source_type_code        = ''INVENTORY''
AND ((rti.requisition_line_id  IS NOT NULL
AND prl.requisition_line_id     = rti.requisition_line_id)
OR (rti.req_num                IS NOT NULL
AND rti.req_num                 = prh.segment1) )
AND processing_status_code      = ''RUNNING''
AND processing_mode_code        = ''ONLINE''
AND transaction_status_code     = ''PENDING''
