debug('begin add_signature: INV_RCV_NULL_VENDOR_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22370',
      p_sig_id                 => 'INV_RCV_NULL_VENDOR_IRISO',
      p_sig_sql                => 'SELECT a.shipment_line_id,
a.shipment_header_id,
b.shipment_num,
b.vendor_id,
b.vendor_site_id,
a.shipment_line_status_code
FROM po.rcv_shipment_lines a
, po.rcv_shipment_headers b
where a.shipment_header_id = b.shipment_header_id
and a.quantity_shipped > 0
and a.quantity_received = 0
and a.source_document_code = ''REQ''
and a.shipment_line_status_code = ''EXPECTED''
and (b.vendor_id is not NULL
OR b.vendor_site_id is not NULL)
and exists (select 1 
              from po_requisition_headers_all prh , po_requisition_lines_all prl
             WHERE prh.segment1 = ''##$$REQNUM$$##''
               AND prh.org_id = ##$$ORGID$$##
               AND prh.requisition_header_id = prl.requisition_header_id
               AND prl.requisition_line_id  = a.requisition_line_id)',
