      p_sig_sql                => 'select distinct 
       PRH.REQUISITION_HEADER_ID, PRH.SEGMENT1, PRH.ORG_ID, PRH.AUTHORIZATION_STATUS, PRH.CANCEL_FLAG, PRH.TRANSFERRED_TO_OE_FLAG, 
