      ,PRL.QUANTITY, PRL.QUANTITY_RECEIVED, PRL.QUANTITY_DELIVERED, PRD.DISTRIBUTION_ID, PRD.REQUISITION_LINE_ID, PRD.REQ_LINE_QUANTITY
  from    
       RCV_SHIPMENT_HEADERS RSH
  ,    RCV_SHIPMENT_LINES RSL
  ,    PO_REQUISITION_HEADERS_ALL PRH
  ,    PO_REQUISITION_LINES_ALL PRL
  ,    PO_REQ_DISTRIBUTIONS_ALL PRD
  where  PRH.SEGMENT1 = ''##$$REQNUM$$##''
  and    PRH.ORG_ID = ##$$ORGID$$##
