debug('begin add_signature: EBS_MFG_INV_PORCVANL_MISSING_RSH_IRISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26509',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_MISSING_RSH_IRISO',
      p_sig_sql                => 'SELECT
    RSL.SHIPMENT_HEADER_ID,
    RSL.SHIPMENT_LINE_ID,
    RSL.LINE_NUM,
    RSL.ITEM_ID,
    RSL.QUANTITY_SHIPPED,
    RSL.QUANTITY_RECEIVED,
    RSL.UNIT_OF_MEASURE,    
