    RCV_SHIPMENT_LINES RSL,
    PO_REQUISITION_HEADERS_ALL PRH, 
    PO_REQUISITION_LINES_ALL   PRL
WHERE   PRH.SEGMENT1 = ''##$$REQNUM$$##''
        AND PRH.ORG_ID = ##$$ORGID$$##
        AND PRH.REQUISITION_HEADER_ID = PRL.REQUISITION_HEADER_ID
        AND PRL.SOURCE_TYPE_CODE = ''INVENTORY''
        AND PRL.REQUISITION_LINE_ID = RSL.REQUISITION_LINE_ID 
        AND RSL.SOURCE_DOCUMENT_CODE = ''REQ''
    AND NOT EXISTS (
        SELECT  ''1''
        FROM RCV_SHIPMENT_HEADERS RSH
        WHERE RSH.SHIPMENT_HEADER_ID = RSL.SHIPMENT_HEADER_ID
    )
ORDER BY RSL.SHIPMENT_HEADER_ID',
      p_title                  => 'Missing Shipment Headers for Internal Requisition Shipment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records missing for the internal requisition shipment in RCV_SHIPMENT_HEADERS.',
      p_solution               => 'Run the datafix script of following note to recreate the missing receipt header records in RCV_SHIPMENT_HEADERS table.<Br>
Datafix : How to recreate missing receipt or shipment header records (RCV_SHIPMENT_HEADERS table) [371105/KB378491].',
      p_success_msg            => 'There are no missing records in RCV_SHIPMENT_HEADERS.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
