debug('begin add_signature: EBS_MFG_INV_PORCVANL_REQLIN_CANC_ISO_SHIPPED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27651',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_REQLIN_CANC_ISO_SHIPPED',
      p_sig_sql                => 'SELECT prh.segment1, prh.authorization_status, prl.requisition_line_id, oel.source_document_line_id ,prl.quantity_delivered , prl.quantity, prl.quantity_cancelled , prl.cancel_flag
