debug('begin add_signature: PORCVANLAZ_FORMS_PERSONALIZATIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13801',
      p_sig_id                 => 'PORCVANLAZ_FORMS_PERSONALIZATIONS',
      p_sig_sql                => 'SELECT rules.form_name
  ||''.fmb'' "Form Name",
  form2.USER_FORM_NAME "User Form Name",
  rules.function_name "Function Name",
  func2.USER_FUNCTION_NAME "User Function Name",
  rules.sequence "Sequence",
  rules.description "Description",
  DECODE(rules.rule_type, ''A'', ''Function'', ''F'', ''Form'', rules.rule_type) "Rule Type Name",
  rules.rule_type "Rule Type",
  DECODE(rules.enabled,''N'',''Not Enabled'', ''Y'', ''Enabled'', rules.enabled) "Personalization Enabled",
  rules.trigger_event "Trigger",
  rules.condition "Condition",
  actions.sequence "Action Seq",
  DECODE(actions.action_type, ''P'', ''Property'', ''M'', ''Message'', ''B'', ''Builtin'', ''S'', ''Menu'', actions.action_type) "Action Type Name",
  actions.action_type "Action Type",
  actions.enabled "Action Enabled",
  DECODE( actions.action_type, ''P'', actions.object_type, ''N/A'') "Object Type",
  DECODE( actions.action_type, ''P'', actions.target_object, ''N/A'') "Target Object",
  DECODE( actions.action_type, ''M'', actions.message_text, ''N/A'') "Message Text",
  DECODE( actions.action_type, ''B'', DECODE(actions.builtin_type, ''C'', ''Launch SRS Form'', ''E'', ''Launch a Function'', ''U'', ''Launch a URL'', ''D'', ''DO_KEY'', ''P'', ''Execute Procedure'', ''G'', ''GO_ITEM'', ''B'', ''GO_BLOCK'', ''F'', ''FORMS_DDL'', ''R'', ''Raise FORM_TRIGGER_FAILURE'', ''T'', ''Execute Trigger'', ''S'', ''Syncrhonize'', ''L'', ''Call Custom Library'', ''Q'', ''Create Record Group From Query'', ''X'', ''Set Profile Value in Cache'', actions.builtin_type), ''N/A'') "Builtin Type Name",
  DECODE( actions.action_type, ''B'', actions.builtin_type, ''N/A'') "Builtin Type",
  DECODE( actions.action_type, ''B'', actions.builtin_arguments, ''N/A'') "Builtin Arguments"
FROM fnd_form_custom_actions actions,
  fnd_form_custom_rules rules,
  FND_FORM form1,
  FND_FORM_TL form2,
  FND_FORM_FUNCTIONS func1,
  FND_FORM_FUNCTIONS_TL func2
WHERE actions.rule_id=rules.id
AND (rules.form_name like ''RCV%'' or rules.function_name  like ''RCV%'')
AND func1.application_id = ''201''
AND func1.function_name  = rules.function_name
AND func1.function_id    = func2.function_id
AND form1.form_name      = rules.form_name
AND form1.form_id        = form2.form_id
AND (actions.enabled     = ''Y''
AND rules.enabled        = ''Y'')
ORDER BY rules.form_name, rules.sequence, actions.sequence',
      p_title                  => 'Receiving Forms Personalization',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Verifying if forms personalizations exist and are enabled. When personalizations are enabled, a warning is raised.',
      p_solution               => 'If you have issues related to the form function and results, suggest that you confirm if the issue remains with Forms Personalizations disabled. Steps to test with personalizations disabled follow.
<ol>
<li>Open the related form</li>
<li>Choose Help/Diagnostics/Custom - Core Code Only</li>
<li>Choose OK to the warning message</li>
<li>Close the form</li>
<li>Open the form</li>
<li>Again test and confirm - is the same issue occurring?</li></p>
</ol>
If the issue is not occurring after performing above action plan, then it seems a personalization is the cause of the problem. Refer to [2381259/KB211818] for more details.',
      p_success_msg            => 'No forms personalizations are detected on the related application''s forms. Refer to [2381259/KB211818] for more details.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_FORMS_PERSONALIZATIONS');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_TABLE_AND_ROW_LOCKS');
   l_info('##MASK##OSUSER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26205',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_TABLE_AND_ROW_LOCKS',
      p_sig_sql                => 'SELECT /*+ rule */
    S.USERNAME,
    DECODE(L.TYPE, ''TM'', ''TABLE LOCK'', ''TX'', ''ROW LOCK'',
           NULL) LOCK_LEVEL,
    O.OWNER,
    O.OBJECT_NAME,
    O.OBJECT_TYPE,
    S.STATUS,
    S.LOCKWAIT,
    S.OWNERID,
    S.PROCESS,
    S.SID,
    S.PORT,
    S.TERMINAL,
    S.MACHINE,
    S.PROGRAM,
    S.OSUSER,
    S.TYPE,
    S.SERIAL#,
    SQL_ID,
    S.PREV_SQL_ID,
    S.SQL_ADDRESS,
    S.SQL_HASH_VALUE,
    S.MODULE,
    S.MODULE_HASH,
    S.PLSQL_OBJECT_ID,
    S.BLOCKING_SESSION_STATUS,
    S.BLOCKING_SESSION,
    S.BLOCKING_INSTANCE,
    S.SEQ#,
    S.EVENT#
FROM
    V$SESSION   S,
    V$LOCK      L,
    DBA_OBJECTS O
WHERE
        L.SID = S.SID
    AND L.ID1 = O.OBJECT_ID (+)
    AND S.USERNAME IS NOT NULL
    AND OBJECT_NAME IS NOT NULL
    AND DECODE(L.TYPE, ''TM'', ''TABLE LOCK'', ''TX'',/*''ROW LOCK'',*/ NULL) IS NOT NULL',
      p_title                  => 'Table and Row level Locks',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Identify table and row level locks',
      p_solution               => 'Table and row level locks data causing any Receiving transaction failure',
      p_success_msg            => 'No locks found',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_TABLE_AND_ROW_LOCKS');



debug('begin add_signature: BOM_VPD_POLICY_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14977',
      p_sig_id                 => 'BOM_VPD_POLICY_CHECK',
      p_sig_sql                => 'SELECT V.object_owner
      ,V.object_name
      ,o.object_type
      ,V.policy_group
      ,V.POLICY
      ,V.predicate
      ,P.PACKAGE
      ,P.FUNCTION, P.ENABLE
FROM
    (  -- From signature "DISABLE ANY CUSTOM VPD POLICIES"
     SELECT DISTINCT object_owner, object_name, policy_group, POLICY, predicate
       FROM v$vpd_policy 
      WHERE object_owner IN(''BOM'',''ENG'',''INV'',''WMS'',''EGO'')
        AND POLICY <> ''ZD_SEED'' 
        AND POLICY <> ''FND_VAULT''
   ) V
  , dba_objects o
  , dba_policies P
WHERE V.object_owner = o.OWNER
  AND V.object_name = o.object_name
  AND V.object_name = P.object_name
  AND V.object_owner = P.object_owner
ORDER BY V.object_owner, V.object_name, o.object_type',
      p_title                  => 'Virtual Private Database Policies',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'One or more custom Virtual Database Policy (VPD) has been detected.
In some cases, it may be required to temporarily disable these when testing certain issues involving the database object (e.g. table) for which the VPD Policy was created.',
      p_solution               => 'Refer to the following document for an example of disabling a VPD policy.
<ul>
<li>[2542049/KB778230] - How To Use Database Policies / Virtual Private Database (VPD) To Restrict Data In Application and SQL (Subinventory Example)?</li>
</ul>',
      p_success_msg            => 'No Virtual Database Policies were detected.',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: BOM_VPD_POLICY_CHECK');



