debug('begin add_signature: PORCVANLAZ_STUCK_RTI_IN_LCM_ORG_FOR_DROPSHIP_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14046',
      p_sig_id                 => 'PORCVANLAZ_STUCK_RTI_IN_LCM_ORG_FOR_DROPSHIP_PO',
      p_sig_sql                => 'SELECT rti.interface_transaction_id, transaction_type, po_header_id, po_line_id, po_line_location_id, lcm_shipment_line_id, 
  pie.error_message
FROM RCV_TRANSACTIONS_INTERFACE rti,
  PO_INTERFACE_ERRORS pie
WHERE processing_status_code IN ( ''ERROR'',''PENDING'', ''LC_PENDING'', ''LC_INTERFACED'')
AND source_document_code      = ''PO''
AND po_header_id              = ##$$HEADID$$##
AND EXISTS
  (SELECT 1
  FROM PO_LINE_LOCATIONS_ALL
  WHERE line_location_id = rti.po_line_location_id
  AND drop_ship_flag     = ''Y''
  AND lcm_flag           = ''Y''
  )
AND rti.interface_transaction_id = pie.interface_line_id (+)',
      p_title                  => 'Stuck Receipts For Dropship PO In An LCM Enabled Organization',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records stuck in receiving interface for a drop ship PO in an LCM enabled organization.<br>',
      p_solution               => 'Run the datafix to reprocess the stuck receiving interface records for a drop ship PO in an LCM enabled organization. <br>
Review datafix for All DropShip POs Get Stuck in Transaction Status Summary (table rcv_transactions_interface) with LC_PENDING or LC_INTERFACED Status When Transacted in LCM Org [1270254/KB614897]. <br>',
      p_success_msg            => 'There are no records stuck in receiving interface for a drop ship PO in an LCM enabled organization.<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_STUCK_RTI_IN_LCM_ORG_FOR_DROPSHIP_PO');



debug('begin add_signature: PORCVANLAZ_STUCK_LCM_RTI');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14061',
      p_sig_id                 => 'PORCVANLAZ_STUCK_LCM_RTI',
      p_sig_sql                => 'SELECT rti.interface_transaction_id,
  rti.group_id,
  rti.transaction_type,
  rti.parent_transaction_id,
  rti.source_document_code,
  rti.po_header_id,
  rti.po_line_id,
  rti.po_line_location_id,
  rti.quantity,
  rti.lcm_shipment_line_id,
  rti.unit_landed_cost
FROM RCV_TRANSACTIONS_INTERFACE rti
WHERE (rti.processing_status_code IN (''LC_PENDING'', ''LC_INTERFACED'',''PENDING'', ''ERROR'',''COMPLETED'')
OR (rti.transaction_status_code    = ''ERROR''))
AND rti.lcm_shipment_line_id          IS NULL
AND rti.unit_landed_cost              IS NULL
AND rti.po_header_id                   = ##$$HEADID$$##
AND EXISTS
  (SELECT ''1''
  FROM PO_LINE_LOCATIONS_ALL pll
  WHERE pll.line_location_id = rti.po_line_location_id
  AND pll.lcm_flag = ''Y''
  AND (pll.cancel_flag       = ''Y''
  OR pll.closed_code         = ''FINALLY CLOSED'')
  )',
      p_title                  => 'Stuck LCM Receipts Against Finally Closed Purchase Orders',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are stuck receiving transactions in interface created against a finally closed purchase order in an LCM organization that is enabled as ''LCM As Service'' .<br>
For this organization, the PRE_RECEIVE flag in RCV_PARAMETERS is not enabled.<br>',
      p_solution               => 'Run the datafix to delete the stuck receiving interface records. <br>
Review datafix to Purge Unwanted RTI records in Receiving Org That is Enabled as ''LCM as a Service'' [2641441/KB485538]. <br>',
      p_success_msg            => 'There are no stuck receiving transactions in interface created against a finally closed purchase order in an LCM organization that is enabled as ''LCM As Service'' .<br>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: PORCVANLAZ_STUCK_LCM_RTI');



debug('begin add_signature: PORCVANLAZ_CORRUPT_SEC_COLS_IN_LCM_ORG_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14129',
      p_sig_id                 => 'PORCVANLAZ_CORRUPT_SEC_COLS_IN_LCM_ORG_PO',
      p_sig_sql                => 'SELECT rti.interface_transaction_id,
       rti.transaction_type,
       rti.quantity,
       rti.unit_of_measure,
       rti.secondary_quantity,
       rti.secondary_unit_of_measure,
       rti.document_num "PO Number",
       rti.po_header_id,
       rti.document_line_num "PO Line Number",
