debug('begin add_signature: WMS_RCV_ERR_WITHOUT_MO_LPN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12073',
      p_sig_id                 => 'WMS_RCV_ERR_WITHOUT_MO_LPN',
      p_sig_sql                => 'SELECT rs.supply_source_id
 ,rs.to_organization_id
 ,ph.segment1 "Document Number"
 ,rsh.shipment_num "Shipment Number"
 ,rsl.source_document_code
FROM rcv_supply rs,
po_headers_all ph,
mtl_parameters mp,
rcv_transactions rt,
rcv_shipment_lines rsl,
rcv_shipment_headers rsh
WHERE rs.po_header_id = ph.po_header_id
 AND rs.to_organization_id = mp.organization_id
 AND rs.rcv_transaction_id = rt.transaction_id
 AND rt.shipment_line_id = rsl.shipment_line_id
 AND rsl.shipment_header_id = rsh.shipment_header_id
 AND rs.item_id IS NOT NULL
 AND mp.wms_enabled_flag = ''Y''
 AND rs.lpn_id IS NULL
 AND rsl.source_document_code = ''PO''
 AND rs.supply_type_code = ''RECEIVING''
 AND ph.segment1= NVL(''##$$DOCNUM$$##'', ph.segment1)
 AND NOT EXISTS
 (SELECT 1
 FROM mtl_txn_request_lines mtrl
 WHERE line_status = 7
 AND reference_type_code = 4
 AND lpn_id IS NULL
 AND reference = ''PO_LINE_LOCATION_ID''
 AND reference_id = rs.po_line_location_id
 AND organization_id = rs.to_organization_id
 AND inventory_item_id = rs.item_id)
union all 
SELECT rs.supply_source_id, 
 rs.to_organization_id, 
 prh.segment1 "Document Number",
 rsh.shipment_num "Shipment Number",
 rsl.source_document_code
FROM rcv_supply rs,
 mtl_parameters mp,
 rcv_transactions rt,
 rcv_shipment_lines rsl,
 rcv_shipment_headers rsh,
 po_requisition_headers_all prh
WHERE rs.to_organization_id = mp.organization_id
AND rs.rcv_transaction_id = rt.transaction_id
AND rt.shipment_line_id = rsl.shipment_line_id
AND rsl.shipment_header_id = rsh.shipment_header_id
and prh.requisition_header_id = rs.req_header_id
AND rs.item_id IS NOT NULL
AND mp.wms_enabled_flag = ''Y''
AND rs.lpn_id IS NULL
AND rsl.source_document_code = ''REQ''
AND rs.supply_type_code = ''RECEIVING''
AND prh.segment1= NVL(''##$$REQNUM$$##'', prh.segment1)
AND NOT EXISTS (SELECT 1
 FROM mtl_txn_request_lines mtrl
 WHERE line_status = 7
 AND reference_type_code = 8
 AND lpn_id IS NULL
 AND reference = ''SHIPMENT_LINE_ID''
 AND reference_id = rsl.shipment_line_id
 AND organization_id = rsl.to_organization_id
 AND inventory_item_id = rs.item_id)',
      p_title                  => 'Desktop Receiving Transaction without LPN Fails with Errors in WMS Enabled Org',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Generic Check-Not specific to LPN parameter<br>
Receiving records missing data of mtl_txn_request_lines will cause RVTTH-115 errors when try to perform the Deliver transaction or Correction or Return transaction in WMS enabled ORG.',
      p_solution               => 'Review [2276452/KB159433] Receiving supply records missing data of mtl_txn_request_lines will cause RVTTH-115 errors when try to perform the Deliver transaction or Correction or Return transaction, and log a Service Request with Oracle Warehouse Management Product Support to request a datafix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: WMS_RCV_ERR_WITHOUT_MO_LPN');



