debug('begin add_signature: EBS_MFG_INV_PORCVANL_IOT_CANCEL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27596',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_IOT_CANCEL',
      p_sig_sql                => 'SELECT MMT.ORGANIZATION_ID ship_from_org_id, MMT.TRANSFER_ORGANIZATION_ID ship_to_org_id , RSH.SHIPMENT_NUM, MMT.SHIPMENT_NUMBER mmt_shipment, ''Organizations are eligible for inter-org return'' 
from RCV_SHIPMENT_HEADERS RSH, RCV_SHIPMENT_LINES RSL, MTL_MATERIAL_TRANSACTIONS MMT,
     mtl_parameters mp1, mtl_parameters mp2,
     cst_acct_info_v cav1, cst_acct_info_v cav2,
     FINANCIALS_SYSTEM_PARAMS_ALL fspa1, FINANCIALS_SYSTEM_PARAMS_ALL fspa2
where RSH.SHIPMENT_NUM    = ''##$$IOTNUM$$##'' 
AND RSH.SHIP_TO_ORG_ID    =  ''##$$IOTORGID$$##''
AND RSH.SHIPMENT_HEADER_ID = RSL.SHIPMENT_HEADER_ID
AND RSL.MMT_TRANSACTION_ID = MMT.TRANSACTION_ID
AND mmt.transaction_type_id = 21 -- shipment / 12 is receipt
  and mp1.organization_id =  MMT.ORGANIZATION_ID  -- IR Receipt Org
  and mp2.organization_id =  MMT.TRANSFER_ORGANIZATION_ID  -- ISO Shipping Org
  and mp1.process_enabled_flag = ''N''
  and mp2.process_enabled_flag = ''N''
  and DECODE(mp1.encumbrance_reversal_flag,1,1,2,0,0) = 0
  and DECODE(mp2.encumbrance_reversal_flag,1,1,2,0,0) = 0
  and NVL(decode(mp1.pm_cost_collection_enabled,1,1,0),0) = 0
  and NVL(decode(mp2.pm_cost_collection_enabled,1,1,0),0) = 0
  and NVL(decode(mp1.project_reference_enabled,1,1,0),0) = 0
  and NVL(decode(mp2.project_reference_enabled,1,1,0),0) = 0
  and not exists ( select ''PAC enabled''
                     FROM    cst_cost_group_assignments ccga,
                             cst_cost_groups ccg
                    WHERE   ccg.legal_entity is not null
                      AND   ccga.cost_group_id = ccg.cost_group_id
                      AND   ccga.organization_id = mp1.organization_id
                  )
  and not exists (select ''PAC enabled''
                     FROM    cst_cost_group_assignments ccga,
                             cst_cost_groups ccg
                    WHERE   ccg.legal_entity is not null
                      AND   ccga.cost_group_id = ccg.cost_group_id
                      AND   ccga.organization_id = mp2.organization_id
                  )
  and mp1.organization_id =  cav1.organization_id
  and mp2.organization_id =  cav2.organization_id
  and fspa1.set_of_books_id = cav1.ledger_id
  AND ( ( cav1.operating_unit is not NULL
          AND fspa1.org_id = cav1.operating_unit
        )
      OR ( cav1.operating_unit is null )
      )
  and nvl(fspa1.req_encumbrance_flag,''N'') = ''N''
  and fspa2.set_of_books_id = cav2.ledger_id
  AND ( ( cav2.operating_unit is not NULL
          AND fspa2.org_id = cav2.operating_unit
        )
      OR ( cav2.operating_unit is null )
      )
  AND nvl(fspa2.req_encumbrance_flag,''N'') = ''N''',
      p_title                  => 'Is IOT Return Allowed?',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Validate if returns is available for the organizations on this transfer (IOT). The rules from [2980242/KB271239] apply including the following:
 Organizations should be eligible for interorg return transactions
                 a.    Between two internal discrete organizations only
                 b.    No external party ; no drop-ship ; no global procurement
                 c.    Asset items only
                 d.   Costing enabled items only
                 e.   Asset sub inventory only
                 f.    Perpetual Costing methods only (Standard, Average, FIFO)
                 g.   PAC is NOT supported
                 h.   No PJM support
                 i.    No Cost Collector support
                 j.    No Expense Destination
                 k.   No Encumbrance',
      p_solution               => 'The organizations did not meet all the criteria to allow for inter-org transfer (IOT) returns.Refer to [2980242/KB271239].',
      p_success_msg            => 'The organizations met the criteria to allow for inter-org transfer (IOT) returns. Refer to [2980242/KB271239]. ',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_IOT_CANCEL');



debug('begin add_signature: EBS_MFG_INV_PORCVANL_ORG_ELIGIBLE_FOR_ISO_RETURN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29316',
      p_sig_id                 => 'EBS_MFG_INV_PORCVANL_ORG_ELIGIBLE_FOR_ISO_RETURN',
      p_sig_sql                => 'SELECT * FROM (
SELECT * FROM (
 select distinct
 rsl.requisition_line_id,
	mp.Organization_code ||''('' || mp.organization_id ||'')'' Inventory_organization
, Case when mp.process_enabled_flag = ''N'' THEN ''Passed'' Else ''Failed'' end Process_Enabled_Flag
, Case WHEN decode(mp.encumbrance_reversal_flag,1,1,2,0,0) = 0 THEN ''Passed'' Else ''Failed'' end Enc_rev_flag
, Case WHEN NVL(decode(mp.pm_cost_collection_enabled,1,1,0),0) = 0 THEN ''Passed'' Else ''Failed'' end pm_cost_coll_enabled
, Case WHEN NVL(decode(mp.project_reference_enabled,1,1,0),0) = 0 THEN ''Passed'' Else ''Failed'' end proj_ref_enabled
, nvl( ( select ''Failed'' FROM cst_cost_group_assignments ccga,  cst_cost_groups ccg
    WHERE ccg.legal_entity is not null AND ccga.cost_group_id = ccg.cost_group_id AND ccga.organization_id = mp.organization_id), ''Passed'') as Not_Pac_enabled
, ( select case when nvl(fspa1.req_encumbrance_flag,''N'') = ''N'' Then ''Passed'' Else ''Failed'' End from  cst_acct_info_v cav1, financials_system_params_all fspa1
    WHERE   mp.organization_id = cav1.organization_id  AND   fspa1.set_of_books_id = cav1.ledger_id
     AND ( ( cav1.operating_unit is not NULL AND fspa1.org_id = cav1.operating_unit) OR ( cav1.operating_unit is null ))) Fin_param_Enc_Flag
from mtl_parameters mp,
     rcv_shipment_lines rsl,
     rcv_shipment_headers rsh
WHERE rsl.shipment_header_id = rsh.shipment_header_id
  AND rsl.mmt_transaction_id  IS NOT NULL
  AND rsh.receipt_source_code  = ''INTERNAL ORDER''
AND (select release_name from fnd_product_groups where  release_name like ''12.2.1_%'' OR  release_name like ''12.2.2_%'') IS NOT NULL
  AND mp.organization_id IN (rsl.from_organization_id, rsl.to_organization_id)
  AND rsl.requisition_line_id IN
    (SELECT requisition_line_id
       FROM po_requisition_lines_all
      WHERE requisition_header_id =  ''##$$HEADID$$##''
    ) 
  )
UNPIVOT ( eligibility_Check
    FOR criteria
IN ( process_enabled_flag AS ''Org should be a discrete Org'',
     enc_rev_flag AS ''Encumbrance Reversal should NOT be enabled'',
     pm_cost_coll_enabled AS ''Cost Collection should NOT be enabled'',
     proj_ref_enabled AS ''Project Ref should NOT be enabled'',
     not_pac_enabled AS ''Org should NOT be PAC enabled'',
     fin_param_enc_flag AS ''Encumberance should NOT be enabled'' ) )
  ) 
  WHERE eligibility_Check =''Failed''',
      p_title                  => 'Internal Order Orgs Eligibility for Return',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Inventory org(s) not eligible for ISO return due to one or more validation failures. This is applicable for release 12.2.11 and higher. ',
      p_solution               => 'Refer to [2912672/KB318042] for details.
',
      p_success_msg            => 'Inventory org(s) are eligible for ISO return. This is applicable for release 12.2.11 and higher. Refer to [2912672/KB318042] for details.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_PORCVANL_ORG_ELIGIBLE_FOR_ISO_RETURN');



