---------------------------------
-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_doc_type                     IN VARCHAR2    DEFAULT NULL
           ,p_po_type                      IN VARCHAR2    DEFAULT NULL
           ,p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_po_number                    IN VARCHAR2    DEFAULT NULL
           ,p_release_number               IN NUMBER      DEFAULT NULL
           ,p_rma_number                   IN VARCHAR2    DEFAULT NULL
           ,p_req_number                   IN VARCHAR2    DEFAULT NULL
           ,p_organization_id              IN NUMBER      DEFAULT NULL
           ,p_iot_number                   IN VARCHAR2    DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'Y'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Receiving Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_doc_type                     => p_doc_type
    ,p_po_type                      => p_po_type
    ,p_org_id                       => p_org_id
    ,p_po_number                    => p_po_number
    ,p_release_number               => p_release_number
    ,p_rma_number                   => p_rma_number
    ,p_req_number                   => p_req_number
    ,p_organization_id              => p_organization_id
    ,p_iot_number                   => p_iot_number
    ,p_include_apps_check           => upper(p_include_apps_check)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: Proactive_Recommendations');
start_section('Proactive Recommendations', 'Proactive_Recommendations');
   set_item_result(check_rec_patches_1); /* Signature INV_CHECK_REC */
   set_item_result(check_rec_patches_2); /* Signature INV_RUP_CHECK */
   set_item_result(run_stored_sig('INV_RUP_CHECK2_SQL_AD_BUGS'));
   set_item_result(run_stored_sig('INV_INVALIDS'));
   set_item_result(run_stored_sig('INV_TXN_KEY_FILE_VERSIONS'));
   set_item_result(run_stored_sig('EBS_MFG_INV_INVTAZ_FREEZE_DFF_CHECK'));
   set_item_result(run_stored_sig('Inv_Trans_Specific_Profiles'));
   set_item_result(run_stored_sig('P2P_RCV_TRANSACTION_MGR_PROCESSES'));
end_section;
debug('end section: Proactive_Recommendations');

debug('begin section: Purchase_Order_Data_Collection');
IF p_doc_type = 'PO' THEN
   start_section('Purchase Order Data Collection', 'Purchase_Order_Data_Collection');
      set_item_result(run_stored_sig('PORCVANLAZ_PO_HEADER_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_LINES_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_SHIPMENTS_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_DISTRIBUTIONS_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_PV_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_PVSA_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_ITEM_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_RSH_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_RSL_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_RT_DATA'));
      IF ((substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.0') OR (substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.1') OR
(substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.2')) THEN
         set_item_result(run_stored_sig('PORCVANLAZ_PO_RHI_DATA'));
      END IF;
      IF ((substr(g_sql_tokens('##$$REL$$##'),1,4) = '11.5'))
 THEN
         set_item_result(run_stored_sig('PORCVANLAZ_PO_RHI_DATA2'));
      END IF;
      set_item_result(run_stored_sig('PORCVANLAZ_PO_RTI_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_PIE_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_MS_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_RS_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_MMTT_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_MMT_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_MTRL_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_WTS_DATA'));
