      set_item_result(run_stored_sig('PORCVANLAZ_PO_WDD_DATA'));
      set_item_result(run_stored_sig('PORCVANLAZ_PO_MOQD_DATA'));
      set_item_result(run_stored_sig('INV_PORCV_REVISION_MISMATCH'));
      set_item_result(run_stored_sig('EBS_MFG_INV_PORCVANL_OSP_WIP_JOB_INFO'));
   end_section;
END IF;
debug('end section: Purchase_Order_Data_Collection');

