PROCEDURE main_cp(
            errbuf                         OUT VARCHAR2
           ,retcode                        OUT VARCHAR2
           ,p_doc_type                     IN VARCHAR2    DEFAULT NULL
           ,p_po_type                      IN VARCHAR2    DEFAULT NULL
           ,p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_po_number                    IN VARCHAR2    DEFAULT NULL
           ,p_release_number               IN NUMBER      DEFAULT NULL
           ,p_rma_number                   IN VARCHAR2    DEFAULT NULL
           ,p_req_number                   IN VARCHAR2    DEFAULT NULL
           ,p_organization_id              IN NUMBER      DEFAULT NULL
           ,p_iot_number                   IN VARCHAR2    DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'Y'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y'
)
 IS

BEGIN
  g_retcode := 0;
  g_errbuf := null;

   main(
     p_doc_type                     => p_doc_type
    ,p_po_type                      => p_po_type
    ,p_org_id                       => p_org_id
    ,p_po_number                    => p_po_number
    ,p_release_number               => p_release_number
    ,p_rma_number                   => p_rma_number
    ,p_req_number                   => p_req_number
    ,p_organization_id              => p_organization_id
    ,p_iot_number                   => p_iot_number
    ,p_include_apps_check           => upper(p_include_apps_check)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  retcode := g_retcode;
  errbuf  := g_errbuf;
EXCEPTION WHEN OTHERS THEN
  retcode := '2';
  errbuf := 'Error in main_cp: '||sqlerrm||' : '||g_errbuf;
END main_cp;


END inv_rec_analyzer_pkg;
